// Do not edit by hand: V42_TREE_PREVIEW_APK__20261026/work/gen_app_data.py
export const METHODOLOGY_V42 = {"version":"V4.2","counts":{"sections":7,"stages":54,"programs":170},"sections":[{"id":"S1","title":"Основа: механика движений","stages":[{"id":"BASE-RELAX","no":1,"title":"Расслабление мышц","task":"Упражнения на расслабление: руки и плечевой пояс, туловище, ноги с партнёром, напряжение—расслабление на выдохе","programs":[{"id":"PRG-BASE-RELAX-1","title":"Упражнения на расслабление","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Ритмичному чередованию напряжений и расслаблений учить с первых шагов; напрягать лишь нужные группы мышц.\nРасслабление после предварительного (статического) напряжения; также силовые упражнения с быстрой сменой предельного напряжения расслаблением."]],"exercises":[{"id":"OGE66-RLX-01","text":"Туловище в полунаклоне вперёд, руки свободно опущены: поднять плечи вверх и, расслабив, опустить.","formats":[],"labels":["Подготовительное упражнение"],"needs":"","equipment":"","review":false},{"id":"OGE66-RLX-02","text":"Из стойки ноги врозь последовательно расслабить мышцы головы, шеи, верхней части туловища, затем всего туловища.","formats":[],"labels":["Подготовительное упражнение"],"needs":"","equipment":"","review":false},{"id":"OGE66-RLX-03","text":"Встать на скамейку на одной ноге, другую свободно опустить; партнёр толчком руки раскачивает опущенную ногу.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"скамейка","review":false},{"id":"OGE66-RLX-04","text":"Сидя или лежа: глубокий вдох, задержка, слегка напрячь все мышцы; через 5–6 с медленный выдох с максимальным расслаблением; 8–10 раз, увеличивая степень расслабления.","formats":[],"labels":["Подготовительное упражнение"],"needs":"","equipment":"","review":false},{"id":"OGE66-RLX-05","text":"Лежа на спине, ступни на полу: глубокий вдох, сильно сдвинуть колени, несколько секунд, медленный выдох — колени свободно «падают» сами; 8–10 раз.","formats":[],"labels":["Подготовительное упражнение"],"needs":"","equipment":"","review":false},{"id":"OGE66-RLX-06","text":"Ноги удобно, глубокий вдох, руки вверх, сильно потянуться, напрячь всё тело несколько секунд, медленный выдох — руки «падают», подбородок на грудь, колени сгибаются; слегка подпрыгнуть, расслабив ноги; 8–10 раз.","formats":[],"labels":["Подготовительное упражнение"],"needs":"","equipment":"","review":false}]}]},{"id":"BASE-STANCE","no":2,"title":"Боевая стойка, кулак, передвижение, дистанция","task":"Стойка у зеркала, положение кулака, скользящие шаги во всех направлениях, по кругу, сохранение дальней дистанции с партнёром","programs":[{"id":"PRG-BASE-PREP-1","title":"Подготовительные специальные упражнения","review":false,"formats":[],"criteria":[],"exercises":[{"id":"BUL-SP-001","text":"Руки согнуты в локтях: одновременно резко разог нуть их в локтевом суставе вперед, вверх, в стороны, вниз с шагом левой или правой ногой, сжимая кисти в конце движения.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-002","text":"Согнутые в локтях руки отведены назад: с шагом левой или правой ногой одновременно резко сводить обе руки вперед, сжимая кисти.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-003","text":"Руки опущены и согнуты в локтях: с шагом левой пли правой ногой одновременно делать рывок обеими ру ками вверх, сжимая кисти.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-004","text":"Руки перед грудью: поворот туловища налево с шагом левой ногой и поворот направо с шагом правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-005","text":"Сделать два движения, предыдущего упражнения с шагом левой и правой ногой, а затем, сгибая туловище в пояснице и имитируя прямой удар, достать правой ру кой носок левой ноги, одновременно отводя левую руку в сторону-вверх. После этого возвратиться в исходное ПО ложение. Затем сделать два шага правой и левой ногами с поворотами туловища, имитируя прямой удар; достать иосок правой ноги левой рукой, отводя правую руку в сторону-вверх и т. д. Упражнение выполняется на 3 счета.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-006","text":"На месте правая нога отставлена назад-вправо, ру«ки согнуты в локтях: с махом правой ногой резко разо гнуть левую руку вперед и кулаком коснуться носка правой ноги, имитируя прямой удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-007","text":"На месте левая нога отставлена назад: с махом левой ногой резко разогнуть правую руку вперёд и кулаком коснуться носка левой ноги, имитируя прямой удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-008","text":"Ноги шире плеч, руки перед грудью: сделать не сколько поворотов направо и налево, а затем, постепен но наклоняясь вперед, доставать попеременно носки раз ноименных ног.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-009","text":"Сидя на полу ноги врозь: резко поворачивать ту ловище налево и направо, касаясь правым и левым ку лаком левого и правого носка.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-010","text":"Лежа на спине, руки вытянуты вверх, ноги вместе: резко наклонить туловище вперед и коснуться руками носков ног.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-BASE-STANCE-1","title":"Стойка и положение кулака","review":false,"formats":["Перед зеркалом","На мешке"],"criteria":[["Техника","Вес равномерно на слегка согнутых ногах, на передней части стопы; левый кулак тыльной стороной влево-вверх, правый у подбородка; левое плечо приподнято, локти касаются туловища; перед стойкой глубокий выдох для расслабления."],["Особенности выполнения","На первых уроках свободно, без усилий; стойку сначала изучать на месте. Левше — зеркальная правосторонняя стойка."],["Типичные ошибки","Голова приподнята или повернута направо; руки широко разведены или опущены; кулак ладонью/тыльной стороной к партнёру; ноги широко или на одной линии; вес на одной ноге; излишнее напряжение."]],"exercises":[{"id":"BUL-Y1-L02-01","text":"Учебная стойка: перенос веса с левой ноги на правую и обратно, затем с выпрямлением руки (поворот туловища, рука от подбородка вперёд). Боевая стойка: из «смирно» шаг левой влево-вперёд, кисти к правой щеке, левую руку вперёд на высоту плеча; правая у подбородка. Левше — зеркально.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-011","text":"Давление ладонью руки на головки пястных кос тей и фаланги пальцев другой руки.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряд","review":false},{"id":"BUL-SP-012","text":"Нанесение ударов по боксерским снарядам.","formats":["На мешке"],"labels":[],"needs":"","equipment":"снаряд","review":false},{"id":"BUL-SP-013","text":"Проверка и исправление боевой стойки перед зер калом.","formats":["Перед зеркалом"],"labels":[],"needs":"","equipment":"зеркало","review":false},{"id":"BUL-SP-014","text":"Перемещение веса тела в боевой стойке с ноги на ногу (находить удобную площадь опоры).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"зеркало","review":false},{"id":"BUL-SP-015","text":"Повороты в боевой стойке в соответствии с перед вижением тренера (сохраняя постоянное боевое положе ние— левостороннее или правостороннее для левши).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"зеркало","review":false}]},{"id":"PRG-BASE-MOVE-1","title":"Передвижение скользящими шагами","review":false,"formats":[],"criteria":[["Техника","Начинать с ноги, стоящей впереди в направлении движения; после каждого шага сохранять положение стойки; правая нога не отрывается от пола; двигаясь спиной/боком — смотреть влево."],["Особенности выполнения","После стойки; одиночные → двойные → слитные; без напряжения.\nВыполняются в боевой стойке главным образом скользящими боксёрскими шагами на передней части ступни, как в бою."],["Типичные ошибки","Излишне сближать ступни, перекрещивать ноги."]],"exercises":[{"id":"BUL-Y1-L02-02","text":"Мелкие скользящие шаги на передней части стопы: одиночные вперёд, назад, влево, вправо (начинать с ноги, стоящей впереди по направлению) → двойные → слитные скользящие.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-016","text":"Шаг вперед — боксер начинает движение с левой ноги, правую тотчас подтягивает в положение, которое она занимает в боевой стойке (толчок для движения вперед осуществляется носком правой ноги).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-017","text":"Шаг назад — боксер делает толчок левой ногой и начинает движение назад правой ногой. Потом подтяги вает и левую ногу до положения боевой стойки.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-018","text":"Шаг влево — движение начинают с левой ноги, а потом подтягивают правую.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-019","text":"Шаг вправо—-движение начинают с правой ноги, а потом подтягивают левую.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-020","text":"Передвижение двойными и тройными шагами (вперед, назад, влево, вправо).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-021","text":"Передвижение по квадрату: вперед, вправо, назад, влево; вперед, влево, назад, вправо.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-022","text":"Передвижение в учебной фронтальной стойке на передней части ступни скользящими приставными шага ми левым (правым) боком вперед.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-023","text":"Передвижение в учебной фронтальной стойке на передней части ступни скользящими приставными шагами левым (правым) боком вперёд с поворотом на 180°.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-024","text":"Передвижение вперед (назад), влево, вправо в бо евой стойке скользящими шагами.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-BASE-DIST-1","title":"Чувство дальней дистанции","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Дальняя — основная для новичка: легче наблюдать и защищаться."]],"exercises":[{"id":"BUL-Y1-L02-03","text":"Измерение дальней дистанции: в парах в стойке сблизиться до касания вытянутой левой ладони партнёра, один шаг назад — дальняя дистанция.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-SP-025","text":"Передвижение в паре с партнером (одиночными, двойными, тройными, слитными шагами), сохраняя даль нюю дистанцию при стремлении партнера нарушить ее.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-SP-026","text":"Передвижение в паре, сохраняя дальнюю дистанцию, с задачей возможно больше раз коснуться рукой туловища, плеч партнёра, уходящего от касаний разнообразным маневрированием.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-SP-027","text":"Игра: боксер передвигается перед партнером в боевой стойке, сохраняя дальнюю дистанцию; партнер старается нарушить дистанцию и, внезапно сближаясь с ним, стремится носком левой ноги достать носок ноги партнера. Победитель — кто больше раз коснется парт нера. 189","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false}]},{"id":"PRG-BASE-STANCE-O1","title":"Позиция дальнего боя, кулак, перемещение веса, шаги и подскоки","review":false,"formats":[],"criteria":[["Техника","Удар центральной частью сочленения головок средних пястных костей с крупными фалангами; своевременное сгибание кулака в лучезапястном суставе и сжатие пальцев. Прямые с дальней — естественное положение кулака; снизу и боковые — пальцы несколько внутрь.\nЛевая впереди, правая сзади на ширину плеч, разведены 15–30 см, слегка согнуты; вес равномерно, больше на передней части стопы; левым плечом вперёд, таз чуть назад, подбородок под левым плечом; левая рука ≈ под прямым углом, кулак на высоте плеча, локоть в 10–15 см от туловища; правый локоть внутрь.\nНаступать передней частью стопы у основания большого пальца; на дальней — в основном на носках; не наступать на пятку шагающей ноги."],["Тактика","Дальняя — расстояние, при котором для удара нужен шаг вперёд.\nНа левую: сокращение дистанции и атака боковым/прямым снизу левой; вызов на прямой левой с последующим контрударом (после приседания, уклонов влево/вправо, отбивов, прикрытия локтем, «стоп»). На правую: подготовка исходного положения для ударов; ввести в заблуждение, заставить приблизиться и в последний момент атаковать.\nШаги вправо-вперёд и влево-назад меняют позицию — применяются в тактических целях.\nОсновной способ передвижения на дальней; позволяет в любой момент остановиться, сменить направление, переместить вес, создать исходное положение для атаки, защиты, контратаки."],["Типичные ошибки","Неправильное нанесение ударов — травмы кистей, чаще в начале занятий.\nНаступать на пятку — замедляет передвижение и смену направления."]],"exercises":[{"id":"OGE66-FIST-01","text":"Удар — головками средних пястных костей в сочленении с первыми фалангами; правильно и своевременно сжимать кулак.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-POS-01","text":"Принять и удерживать позицию дальнего боя.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-MOV-01","text":"Перемещения веса с ноги на ногу из позиции дальнего боя — толчком носка правой на левую и толчком левой на правую — как подготовка исходных положений для атаки, защиты, контратаки.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-MOV-02","text":"Передвижение одиночными шагами во всех направлениях: вперёд/влево — толчок правой, шаг левой, подтянуть правую; назад/вправо — толчок левой, шаг правой, подтянуть левую.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-MOV-03","text":"Передвижение слитными скользящими подскоками во всех направлениях; любая нога толчковая; короткие и длинные, быстрые и медленные; с поворотами тела на передней части стопы.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false}]}]},{"id":"MECH-STRAIGHT","no":3,"title":"Механика одиночных прямых","task":"Прямые с переносом веса: на месте, с шагами, в ходьбе, по кругу; с уклоном","programs":[{"id":"PRG-MECH-STRAIGHT-1","title":"Прямые на месте: фронтальная и боковая стойка","review":false,"formats":[],"criteria":[["Техника","Кулаки вперёд, большие пальцы кверху; при переносе веса на правую ногу туловище поворачивается вправо и левая рука выполняет прямой; левая пятка отрывается, левое бедро поворачивается вправо.\nОдноимённые действия: удар рукой той же стороны, что и опорная нога; поворот туловища в противоположную сторону.\nТуловище и бедро поворачиваются как в упражнении в прямой позиции."],["Особенности выполнения","Попеременно выносить руки, перемещая вес с ноги на ногу; затем с шагом в сторону, вперёд, назад. Под счёт раздельно, затем слитно.\nСначала на месте, затем с шагом в сторону, вперёд и назад.\nСтоя на месте."]],"exercises":[{"id":"ROM-MECH-S01","text":"Из фронтальной стойки (ноги на ширине плеч, ступни параллельны) перенос веса на правую ногу с поворотом туловища вправо и прямым левой; перенос на левую — прямой правой (разноимённо); затем с шагом в сторону, вперёд и назад.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-S02","text":"Та же фронтальная стойка, одноимённо: вес на левую ногу — прямой левой с поворотом туловища вправо; вес на правую — прямой правой с поворотом влево; затем с шагом в сторону, вперёд, назад.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-S03","text":"Из левосторонней боковой стойки на месте: вес на левую — прямой левой, затем правой (разноимённо); вес на правую — прямой правой, затем левой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-MECH-STRAIGHT-2","title":"Прямые в передвижении","review":false,"formats":[],"criteria":[["Техника","Туловище и бедро поворачиваются вокруг оси то влево, то вправо."],["Особенности выполнения","Выполнять в левостороннем и правостороннем положении.\nРазноимённо, затем одноимённо; вперёд и назад.\nПредставляют координационные трудности: сначала медленно и раздельно, затем в темпе одно за другим."]],"exercises":[{"id":"ROM-MECH-S04","text":"Механика прямых ударов в голову из боковой стойки с шагом вперёд, в стороны и назад — одноимённо и разноимённо, в левосторонней и правосторонней стойке.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-S07","text":"Ходьба с прямыми ударами в голову: шаг левой — прямой правой, шаг правой — прямой левой; затем одноимённо; то же при движении назад.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-S09","text":"По кругу приставными шагами: шаг левой — прямой левой, шаг правой — прямой правой; затем разноимённо.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-MECH-STRAIGHT-3","title":"Прямые с уклоном в голову и туловище","review":false,"formats":[],"criteria":[["Техника","Кулак поворачивается тыльной стороной кверху; вес на обеих, несколько согнутых ногах или больше на левой.\nАналогично прямому правой в голову, с небольшим уклоном влево; вес на обеих ногах или на левой в зависимости от условий и дистанции.\nВес в основном на левой ноге."],["Особенности выполнения","На месте, затем с шагом вперёд и в стороны.\nВо время ходьбы."]],"exercises":[{"id":"ROM-MECH-S05","text":"Из левосторонней стойки уклон туловища вправо с прямым левой в туловище или голову; затем с шагом вперёд и в стороны. Левше — правой с уклоном влево.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-S06","text":"Механика прямого удара правой в туловище или голову с небольшим уклоном влево.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-S08","text":"Ходьба с прямыми в туловище: шаг левой — уклон вправо с прямым левой, или уклон влево с прямым правой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-MECH-STRAIGHT-4","title":"Удары в шеренге из учебной стойки","review":false,"formats":["На мешке"],"criteria":[["Особенности выполнения","Удары, контрудары с защитами и ложными действиями могут выполняться также на снарядах (мешок, настенная подушка, груша подвесная)."]],"exercises":[{"id":"BUL-SP-028","text":"Перенос веса тела с левой ноги на правую и обратно.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-029","text":"Из учебной стойки перенос веса с левой ноги на правую и обратно с поворотом плеч и тазобедренного сустава.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-030","text":"Из учебной стойки прямые удары, удары снизу и боковые с переносом веса с левой ноги на правую и обратно.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-031","text":"Удары с одиночными шагами влево (вправо). При шаге вправо (влево) удар наносят левой (правой) рукой, перенося вес тела на правую (левую) ногу.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-032","text":"Прямые и удары снизу, боковые удары не пере нося веса тела с ноги на ногу: при ударе прямым левой вес тела остается на левой ноге, при ударе правой — на правой.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-033","text":"Удары с одиночными, двойными шагами влево (вправо). При шаге влево удар наносят левой рукой и вес тела остается на левой ноге. При шаге вправо — пра вой рукой, вес тела на правой ноге.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-034","text":"Два слитных прямых удара или боковые удары снизу: 1) при шаге влево — удар левой с переносом веса тела на левую ногу; 2) затем удар правой, вес тела оста ется на левой ноге.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-035","text":"Серии прямых ударов (снизу, боковых). 1—2) при двойном шаге вправо (влево) — повторный прямой левой (правой); 3) при шаге влево (вправо) —прямой правой (левой).","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-036","text":"Серии ударов. 1—2) два прямых удара (левой — правой); 3—4) два боковых; 5—6) два удара снизу. Пе ренести вес тела с левой ноги на правую и обратно.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false}]},{"id":"PRG-MECH-STRAIGHT-5","title":"Удары из боевой стойки на месте и в движении","review":false,"formats":["На мешке"],"criteria":[],"exercises":[{"id":"BUL-SP-037","text":"Прямой удар снизу, боковой с шагом вперед (назад, влево, вправо).","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-038","text":"Из боевой стойки прямой (снизу, боковой) удар с двойным шагом вперёд (назад, влево, вправо); удар наносят на втором шаге.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-039","text":"Прямые (снизу, боковые) удары с передвижением по квадрату. Удар наносят с тем или иным шагом по ус мотрению тренера.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-040","text":"Два слитных удара (левой — правой) с шагом вперед.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-041","text":"Из боевой стойки два слитных удара (левой — правой) с шагом назад под правую ногу.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-042","text":"Два слитных удара левой с шагом вперед и то же с шагом назад.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-043","text":"Два слитных удара левой с шагом вперед и удар правой с шагом назад.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-044","text":"Удар левой с шагом вперед и двойной (левой — правой) с шагом назад.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-045","text":"Два слитных удара с передвижением по квадра ту. Сочетание ударов по усмотрению тренера.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-046","text":"Вращение туловищем вправо — влево (с шагом вперед левой—поворот влево, с шагом правой—вправо).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-047","text":"Прямой (снизу, боковой) удар левой (правой) с шагом вперед левой ногой. Правой ногой делать свобод ный промежуточный шаг после каждого удара.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-048","text":"Прямой (снизу, боковой) удар левой с шагом пра вой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-049","text":"Попеременные удары левой и правой рукой. Удар левой наносят при шаге правой ногой, удар правой — с шагом левой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-050","text":"Упражнения 47–49 с шагами назад: удар левой — когда отставляют назад левую ногу, удар правой — когда отставляют правую.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-051","text":"Одиночные (двойные) прямые (снизу, боковые) удары с передвижением вперед-вправо, вперед-влево. Удар наносят с любым шагом по указанию тренера.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-052","text":"Одиночные (двойные) прямые (снизу, боковые) удары с передвижением назад и в сторону; удар с любым шагом по указанию тренера.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-MECH-STRAIGHT-O1","title":"Прямые левой и правой: варианты исполнения","review":false,"formats":[],"criteria":[["Техника","См. описание.\nУдар доходит, когда вес полностью на передней ноге. Правая перчатка тыльной частью к подбородку страхует голову, опущенный локоть — туловище; рука после удара кратчайшим путём возвращается.\nПри наклоне влево правая перчатка идёт несколько вперёд-вправо навстречу удару противника — страхует от встречного прямого.\nТолчок носком, шаг с носка на полную ступню выпрямляющейся ноги, вращение слева направо, кулак прямолинейно; другую ногу подтянуть в исходную. Правая перчатка тыльной частью к подбородку страхует голову, опущенный локоть — туловище; рука после удара кратчайшим путём возвращается.\nПравая перчатка при наклоне поворачивается внутренней стороной к лицу, локоть больше внутрь.\nПосле каждого удара подтягивать правую ногу; кулак не опускать — малая окружность в сагиттальной плоскости, продвижение на носках."],["Тактика","Встречный и ответный на прямой левой; подготовка прямого правой.\nПерехват инициативы при атаке противника серией в голову; создаёт положение для ответных правой в голову, левой снизу в туловище, ближнего боя, преследования серией на средней.\nС шагом назад — навык удара при отступлении, понадобится при сближении противника; с шагом вправо — после защиты шагом влево.\nПредварительно готовить обманным движением туловища вправо и влево.\nАтака с шагом; очень эффективен как контрудар на прямой левой в голову — противник открывает туловище.\nНабирать очки, заставить поднять руки и открыть туловище для правой; последующий удар в голову — с отходом правой ногой назад против ответной правой.\nТри формы: атакующий — редко, только против неподготовленного (после промаха, пропущенного удара) или после финтов/отвлекающих левой; встречный — опережение на долю секунды с небольшим уклоном влево; ответный — после прочной защиты. Готовить: отступая вызвать продвижение; обманом левой раскрыть; «левой-правой».\nАтакующий — редко, после ложных левой в голову; встречный на прямой левой в голову — один из важнейших эффективных ударов."],["Особенности выполнения","С шагом назад обязательно обучать новичков; с шагом вправо — можно обучать уже новичков, как и в остальных направлениях. Страховку систематически закреплять.\nКоординация сложна.\nОтветный правой требует искусства защиты, координации и реакции."]],"exercises":[{"id":"OGE66-NOTE-01","text":"В момент касания кулак сжимать и страховать себя свободной рукой; после прямого левой рука кратчайшим путём возвращается; при одиночном или акцентированном ударе другой рукой страховать голову раскрытой перчаткой и туловище опущенным локтем; при ударе снизу — тыльная сторона раскрытой кисти к подбородку; при боковом — кисть сбоку головы ладонью к ней; при коротком прямом — к подбородку, затем сбоку головы.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-STR-01","text":"Из позиции дальнего боя толчком носка правой вес на выпрямленную левую, левая рука резко выпрямляется, туловище слегка слева направо, кулак к цели наклоняется вперёд, кисть сжимается.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-STR-02","text":"Толчком носка левой вес на согнутую правую, левая быстро выпрямляется, туловище слегка слева направо.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-STR-03","text":"Толчком правой вес на левую с одновременным наклоном туловища влево (вправо) и вращением слева направо; рука и кулак поворачиваются по наклону.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-STR-04","text":"Прямой левой с шагом вперёд; с шагом назад (толчок левой, шаг назад); с шагом влево; с шагом вправо; в промежуточных направлениях.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-STR-05","text":"Толчком правой подать тело вперёд с поворотом справа налево, слегка сгибая левую; резким толчком левой послать тело вперёд с поворотом слева направо и небольшим шагом правой вперёд-вправо; левая резко выпрямляется.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-STR-06","text":"Толчок правой, шаг левой вперёд, туловище вперёд-вправо ≈45°, рука резко выпрямляется; на месте — без шага.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-STR-07","text":"Повторные прямые левой по 2–3 и более раза слитно; голова → туловище; туловище → (тактическая пауза, медленное выпрямление) → неожиданно голова.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-STR-08","text":"Толчком носка правой послать тело вперёд с поворотом справа налево, кулак прямолинейно; левая ладонь страхует голову, локоть — туловище; правую ногу оставить или подтянуть.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-STR-09","text":"Как прямой правой в голову, но тело больше вперёд, левый локоть больше внутрь, правую ногу подтянуть вперёд.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false}]}]},{"id":"MECH-HOOK-UPPER","no":4,"title":"Механика одиночных боковых и снизу","task":"Тот же порядок, что для прямых, для ударов сбоку и снизу","programs":[{"id":"PRG-MECH-HOOK-UPPER-1","title":"Боковые и снизу на месте и в передвижении","review":false,"formats":[],"criteria":[["Техника","Принцип прежний, меняется лишь направление движения руки."],["Особенности выполнения","Так же, как упражнения на механику прямых."]],"exercises":[{"id":"ROM-MECH-S10","text":"В той же последовательности (одноимённо и разноимённо, в прямой и боковой стойке, на месте и с передвижением) — механика одиночных ударов сбоку и снизу.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]}]},{"id":"MECH-DEFENSE","no":5,"title":"Механика защит","task":"Подставки, отбивы, уклоны, нырки без партнёра: на месте → в движении → самостоятельно; параллельно с ударами","programs":[{"id":"PRG-MECH-DEF-1","title":"Подставки","review":false,"formats":[],"criteria":[["Техника","В левосторонней — правой рукой, в правосторонней — левой; вес на левой или правой ноге.\nПлечо закрывает подбородок, туловище чуть вправо, вес на отставленной ноге.\nЛевой рукой — туловище доворачивается вправо, вес на правой; правой — туловище влево, вес на левой.\nГолова несколько опускается; вес на обеих или на одной в зависимости от позиции для контрудара; в прямой позиции подставка правой — вес на левую с поворотом влево, левой — на правую с поворотом вправо.\nПри подставке левой — поворот вправо, правой — влево."],["Тактика","Применяется при прямом ударе противника с дальней дистанции; часто с встречным прямым левой.\nСоздаёт условия для ответных прямого и бокового левой в голову и туловище, прямого и бокового правой в голову; ответ — с движением вперёд и переносом веса на левую; встречный — левой в голову с переносом веса на правую.\nПоложение создаёт условия для ответного удара.\nОтвет свободной рукой с поступательным движением и переносом веса на левую (левше — на правую).\nИспользовать поворот для ответных контрударов."],["Особенности выполнения","Изучать в боковой позиции.\nПосле защиты наносить ответный удар.\nДобавлять ответные удары свободной рукой.\nДля ближнего боя выполнять из прямой (фронтальной) позиции, затем одноимённо, затем связать с ответами."]],"exercises":[{"id":"ROM-DEF-P1","text":"Подставка правой открытой перчатки от прямых левой и правой в голову, в боковой (левосторонней) стойке; часто с одновременным встречным прямым левой в голову.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-DEF-P2","text":"Подставка левого плеча от прямых в голову и бокового правой в голову: подъём плеча, закрывающего подбородок, с небольшим поворотом вправо, в комбинации с шагом назад или уклоном; затем ответный прямой/боковой с движением вперёд или встречный левой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-DEF-P3","text":"Подставка прижатой согнутой (правой, левой) руки от прямых в туловище; добавить ответные прямые и боковые свободной рукой в голову или туловище.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-DEF-P4","text":"Подставка от боковых в голову: от левого бокового — тыльная сторона открытой правой перчатки или согнутая рука у подбородка; от правого — внутренняя сторона правой перчатки или согнутая левая; затем ответный прямой, боковой, снизу свободной рукой с движением вперёд. Те же упражнения из фронтальной стойки (ближний бой), разноимённо и одноимённо, с ответами снизу, сбоку, коротким прямым.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-DEF-P5","text":"Подставка прижатой согнутой руки от ударов снизу и коротких прямых в туловище (от левой — правую, от правой — левую) с поворотом туловища, затем ответные короткий прямой/боковой/снизу; от удара снизу в голову — подставка открытой перчатки, с встречным и ответным левой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-MECH-DEF-2","title":"Отбивы, уклоны, нырки","review":false,"formats":["Перед зеркалом"],"criteria":[["Техника","Отбив по предплечью между запястьем и локтем, когда рука противника почти вытянута; левой обычно отбивают правую, правой — левую; вес равномерно или больше на одной ноге.\nДве разновидности: наклон без перемещения веса; уклон с поворотом и переносом веса на одноимённую ногу.\nНоги согнуты, туловище чуть вперёд, голова слегка опущена и описывает полукруг; в конце нырка вес на правую ногу (от левого бокового).\nОсобое внимание на сочетание движений туловища, рук, головы и перенос веса с ноги на ногу."],["Тактика","Отбивы кнаружи — чтобы раскрыть противника; после отбива удобно отвечать незанятой рукой.\nУклоны содействуют сближению; нужны и при атаках, чтобы избежать встречных в голову при подходе.\nВыполняется, когда боксёр твёрдо стоит на обеих ногах и готов к встречному бою; вращение используется для встречного удара."],["Особенности выполнения","Разнообразные положения в момент отбива развивают координацию, реакцию, ориентировку.\nВыполнять быстро и своевременно; механику контратакующих действий изучать вместе с уклоном.\nНырок может сочетаться с подставкой тыльной стороны перчатки или шагом в сторону.\nПостепенно увеличивать скорость, доводить до автоматизма; полезно контролировать движения перед зеркалом."],["Типичные ошибки","Прямолинейное движение в атаке без уклонов — наталкивание на встречные прямые.\nПримитивный нырок только сгибанием коленей и опусканием головы не создаёт выгодного положения для действий."]],"exercises":[{"id":"ROM-DEF-OTB","text":"Механика отбивов внутренней частью открытой перчатки по предплечью (внутрь и кнаружи, вверх) — на месте, с движением вперёд, с уклоном назад/в сторону, с шагом назад/в сторону, с поворотом; затем ответ свободной рукой (с места или с шагом вперёд) или отбивающей рукой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-DEF-UKL","text":"Механика уклонов из прямой и боковой стойки: без переноса веса (небольшой наклон) и с поворотом туловища и переносом веса; в стороны, в стороны-вперёд, в стороны-назад, с вышагиванием; вместе с контрударом: уклон вправо — прямой левой в голову/туловище, уклон влево — прямой правой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-DEF-NYR","text":"Механика нырка от бокового удара: движение по направлению удара, вниз и выпрямление под бьющую руку; от левого бокового — встречный боковой левой в туловище/голову или снизу в туловище, затем ответный правой (боковой или короткий прямой в голову); зеркально от правого.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-DEF-METH","text":"Механика защит: в строю на месте → в движении вперёд, назад, в стороны, по кругу с остановками → по заданию → самостоятельно; контроль перед зеркалом; повторять удары и защиты на утренней прогулке и в начале/конце занятия.","formats":["Перед зеркалом"],"labels":[],"needs":"","equipment":"зеркало","review":false}]},{"id":"PRG-MECH-DEF-3","title":"Защиты в движении по кругу","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Упражнения в защитах можно выполнять и из поло жения боевой стойки в строю на месте и с шагом вперед, назад, а также и в двух шеренгах (лицом друг к другу на удлиненной дистанции), где одна шеренга атакует, другая защищается..\nПриём разучивается в целом и по элементам, медленно и быстро, в простых и сложных условиях; урок начинается с повторения пройденного."]],"exercises":[{"id":"BUL-SP-053","text":"Подставка правой ладони с шагом вперед (назад) левой (правой) ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-054","text":"Подставка тыльной стороны правой ладони с ша гом вперед (назад) левой (правой) ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-055","text":"Подставка тыльной стороны левой ладони с ша гом вперед правой ногой. 191","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-056","text":"Попеременная подставка тыльной стороны ладо ни левой и правой руки с шагом разноименной ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-057","text":"Подставка левого плеча с шагом вперед правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-058","text":"Подставка правого плеча с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-059","text":"Попеременная подставка левого и правого плеча с шагом вперед разноименной ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-060","text":"Попеременная подставка левого и правого плеча с шагом назад разноимённой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-061","text":"Подставка согнутой в локте правой руки (прижа той к туловищу) с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-062","text":"Подставка согнутой в локте левой руки (прижа той к туловищу) с шагом вперед правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-063","text":"Попеременная подставка согнутой в локте левой и правой руки (прижатой к туловищу) с шагом вперед разноименной ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-064","text":"Уклон влево с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-065","text":"Уклон вправо с шагом вперед правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-066","text":"Попеременные уклоны влево и вправо с шагом вперед одноименной ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-067","text":"Уклон влево с шагом назад правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-068","text":"Уклон вправо с шагом назад левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-069","text":"Попеременные уклоны влево и вправо с шагом назад разноименной ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-070","text":"Отбив правой рукой влево (внутрь) с шагом впе ред левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-071","text":"Отбив левой рукой вправо (внутрь) с шагом впе ред правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-072","text":"Попеременные отбивы правой и левой рукой внутрь с шагом вперед разноименной ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-073","text":"Отбив правой рукой вправо (наружу) с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-074","text":"Отбив правой рукой влево (внутрь) с шагом на зад правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-075","text":"Отбив левой рукой вправо (внутрь) с шагом на зад левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-076","text":"Попеременные отбивы внутрь правой и левой ру кой с шагами назад одноименной ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-077","text":"Нырок влево с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-078","text":"Нырок вправо с шагом вперед правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-079","text":"Попеременные нырки влево и вправо с шагом вперед одноименной ногой. 192","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-080","text":"Шаг левой ногой влево-вперед с поворотом туло вища налево.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-081","text":"Шаг правой ногой вправо-вперед с поворотом туловища направо.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-082","text":"Попеременные шаги влево-вправо (вперед) с пово ротами туловища в одноименную сторону.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-083","text":"Шаг левой ногой влево-назад с поворотом туло вища направо.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-084","text":"Шаг правой ногой вправо-назад с поворотом ту ловища налево.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-085","text":"Попеременные шаги влево и вправо (назад) с по воротами туловища в разноименную сторону.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-MT-01","text":"Приём осваивается в одной или двух шеренгах (без перчаток) под команду; тренер наносит удар в направлении шеренги — новички мгновенно отвечают защитой или контрударом; затем самостоятельно в парах; затем удары и защиты в ходьбе по залу за опытным направляющим.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false}]}]},{"id":"MECH-COUNTER","no":6,"title":"Механика контрударов без партнёра","task":"Защита + встречный/ответный удар: в строю на месте, затем в движении по кругу","programs":[{"id":"PRG-MECH-COUNTER-1","title":"Контрудары в строю на месте","review":false,"formats":[],"criteria":[["Особенности выполнения","Упражнения в контрударах можно выполнять и в двух шеренгах (лицом друг к другу на удлиненной ди станции); одна шеренга атакует, а другая защищается и контратакует.."]],"exercises":[{"id":"BUL-SP-086","text":"Подставка правой ладони встречный прямой ле вой (снизу, боковой).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-087","text":"Подставка согнутой в локте руки (прижатой к ту ловищу) и ответный прямой (снизу, боковой).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-088","text":"Подставка тыльной стороны кисти и встречный или ответный удар (прямой, снизу, боковой).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-089","text":"Подставка плеча (левого) и ответный прямой (снизу, боковой) правой рукой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-090","text":"Подставка левого плеча и правой ладони с уходом назад и ответный прямой (снизу, боковой) с шагом впе ред левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-091","text":"Подставка согнутой левой руки (прижатой к ту ловищу) с шагом назад и ответный удар правой с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-092","text":"Подставка плеча (левого-правого — левого-пра вого) и ответный удар (одиночный, двойной).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-093","text":"Уклон вправо, влево и встречный или ответный удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-094","text":"Уклон влево — вправо-влево и встречный удар правой или ответный левой (с уклоном вправо).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-095","text":"Отбив влево-вправо (внутрь, наружу) и встречный или ответный удар. 193 1","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-096","text":"Отбив влево-вправо—влево-вправо и ответный удар (прямой, снизу, боковой) одиночный, двойной.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-097","text":"Нырок влево, вправо и встречный или ответный удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-098","text":"Уход назад — шаг влево, вправо с поворотом ту ловища в соединении со встречным или ответным ударом.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-MECH-COUNTER-2","title":"Контрудары в движении по кругу","review":false,"formats":[],"criteria":[["Особенности выполнения","Все упражнения с контрударами можно выполнять и при боксерском передвижении мелкими скользящими ша гами, сохраняя боевое левостороннее (правостороннее) положение.."]],"exercises":[{"id":"BUL-SP-099","text":"Подставка ладони правой руки в сочетании со встречным ударом левой рукой (прямым, снизу, боко вым) с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-100","text":"Подставка ладони левой руки в сочетании со встречным ударом правой рукой (прямым, снизу, боко вым) с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-101","text":"Попеременная подставка ладоней (правой и ле вой) со встречными ударами (левой и правой) с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-102","text":"Подставка ладони правой руки в сочетании со встречным ударом левой рукой (прямым, снизу, боко вым) с шагом назад-вправо’правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-103","text":"Подставка ладони левой руки в сочетании со встречным ударом правой рукой (прямым, снизу, боко вым) с шагом назад-вправо правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-104","text":"Попеременная подставка ладоней (правой и ле вой) со встречными ударами (левой и правой) с шагом назад правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-105","text":"Подставка ладони правой руки в сочетании со встречным ударом левой рукой (прямым, снизу, боко вым) с шагом вперед правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-106","text":"Попеременная подставка ладоней (левой и пра вой) со встречными ударами. Удар правой — с шагом вперед левой, левой — под шаг правой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-107","text":"Подставка ладони правой руки в сочетании со встречным ударом левой рукой (прямым, снизу, боко вым) с шагом назад-влево левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-108","text":"Попеременная подставка ладоней (правой и ле вой) со встречными ударами. Удар левой — с шагом на зад левой ногой, правой — с шагом правой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-109","text":"Подставка тыльной стороны правой ладони; под ставка согнутой в локте правой руки (прижатой к туло вищу); отбив правой рукой влево (внутрь) с шагом вперед левой ногой и ответный удар левой рукой (пря мой, снизу, боковой) с шагом вперед правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-110","text":"Подставка тыльной стороны левой ладони; под ставка согнутой в локте левой руки (прижатой к тулови щу); отбив левой рукой вправо (внутрь) с шагом вперед правой ногой и ответный удар правой рукой (прямой, снизу, боковой) с шагом левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-111","text":"Попеременная подставка тыльной стороны ладо ней (левой и правой); попеременная подставка согнутых в локте левой и правой рук; попеременные отбивы пра вой и левой рукой и ответные удары. Удар левой — с ша гом вперед правой ногой; правой —с шагом левой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-112","text":"Подставка тыльной стороны правой ладони; от бив правой рукой влево (внутрь) с шагом назад правой ногой и удар левой (прямой, снизу, боковой) с шагом назад левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-113","text":"Подставка тыльной стороны левой ладони; отбив левой рукой вправо (внутрь) с шагом назад левой ногой и удар правой (прямой, снизу, боковой) с шагом назад правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-114","text":"Попеременная подставка тыльной стороны ладо ней (левой и правой), попеременные отбивы (внутрь) правой, левой рукой и ответные удары. Удар левой — с шагом назад левой ногой; правой — с шагом правой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-115","text":"Подставка тыльной стороны правой ладони с шагом левой ногой и ответный удар левой рукой (пря мой, снизу, боковой) со вторым шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-116","text":"Подставка тыльной стороны левой ладони с ша гом вперед левой ногой и ответный удар правой рукой (прямой, снизу, боковой) с шагом вперед левой но гой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-117","text":"Попеременная подставка тыльной стороны ладо ней (левой и правой) с ответными ударами (правой и ле вой) с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-118","text":"Подставка левого плеча с шагом вперед правой ногой и удар правой рукой (прямой, снизу, боковой) с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-119","text":"Подставка правого плеча с шагом вперед левой ногой и удар левой рукой (прямой, снизу, боковой) с ша гом вперед правой ногой. 195","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-120","text":"Попеременная подставка левого и правого плеча с ударами правой и левой руками с шагом вперед раз ноименной ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-121","text":"Уклон влево и удар правой (прямой снизу, боко вой) с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-122","text":"Уклон вправо и удар левой (прямой, снизу, бо ковой) с шагом вперед правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-123","text":"Попеременные уклоны влево и вправо с ударами и шагами вперед.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-124","text":"Нырок влево с шагом вперед левой ногой и удар левой (прямой, снизу, боковой) с шагом вперед правой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-125","text":"Нырок вправо с шагом вперед правой ногой и удар правой (прямой, снизу, боковой) с шагом вперед левой ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-126","text":"Попеременные нырки влево и вправо с ударами.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]}]},{"id":"MECH-DOUBLE","no":7,"title":"Механика двух ударов одного вида","task":"Два прямых, два боковых, два снизу — слитно, на месте, затем с шагами","programs":[{"id":"PRG-MECH-DOUBLE-1","title":"Два последовательных удара","review":false,"formats":[],"criteria":[["Техника","Перенос веса с ноги на ногу под каждый удар.\nВес остаётся на левой ноге, работа поворотом туловища.\nПеренос веса на опорную ногу под удар противоположной рукой.\nПринцип как при прямых и боковых, меняется характер и направление удара."],["Особенности выполнения","Слитно; сначала на месте, затем с шагами.\nАналогично при шагах в стороны.\nНа месте, с шагами вперёд и в стороны."]],"exercises":[{"id":"ROM-MECH-D01","text":"Из фронтальной стойки: вес на левую — прямой правой в голову или туловище; переход на правую — прямой левой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-D02","text":"Из левосторонней стойки: вес на левую — прямой левой в голову с поворотом вправо; оставаясь на левой, поворот влево с прямым правой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-D03","text":"Шаг назад — прямой правой; при подтягивании левой ноги к правой — прямой левой; то же при шагах в стороны.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-D04","text":"Из левосторонней стойки: вес на левую — боковой правой; шаг правой вправо (вес на правую) — боковой левой в голову или туловище.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-D05","text":"Из левосторонней стойки: прямой левой в туловище с уклоном вправо и с переносом веса на левую — прямой правой в голову; то же с шагами вперёд и в стороны.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-D06","text":"Из левосторонней стойки: прямой правой в туловище с небольшим уклоном влево, затем прямой левой в голову с переносом веса на правую ногу.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-D07","text":"Из левосторонней стойки: два последовательных удара снизу в голову и в туловище; вес на левой, на правой, попеременно.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]}]},{"id":"MECH-COMBO","no":8,"title":"Механика сочетаний разных ударов","task":"Прямой с боковым/снизу; серии разных ударов на одной опоре","programs":[{"id":"PRG-MECH-COMBO-1","title":"Сочетания прямых с боковыми и снизу","review":false,"formats":[],"criteria":[["Техника","Принцип движения туловища и переноса веса как при двух ударах одного вида.\nДля быстроты двух-трёх ударов удобнее сохранять вес на одной ноге или на обеих. Левши — соответственно своей стойке."],["Особенности выполнения","Выполнять 2–3 движения в разных сочетаниях; постепенно быстрее, исключив напряжение и акцент «удара»; быстро, но плавно."],["Типичные ошибки","Напряжение, связанное с акцентированием «удара» — исключать."]],"exercises":[{"id":"ROM-MECH-C01","text":"Сочетания прямого с боковым/снизу: из фронтальной стойки вес на правую — прямой левой, вес на левую — боковой правой в голову; из левосторонней шаг назад — прямой правой, на правой ноге при подтягивании левой — боковой левой в голову; с шагом вперёд прямой левой и боковой правой в голову; с шагом назад (вес на правую) прямой левой и боковой правой; фронтально вес на левую — снизу правой в туловище, шаг назад правой — боковой левой в голову.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"ROM-MECH-C02","text":"С сохранением веса на одной ноге: 1) левосторонняя — прямой левой в голову с шагом вперёд и сразу боковой правой в голову (вес на левой); 2) фронтальная — шаг вправо, вес на правую: прямой правой и сразу боковой левой в голову или снизу; 3) левосторонняя, шаг вперёд — прямой правой в туловище, затем боковой левой в голову; 4) то же положение, шаг назад и опора на правую — прямой правой в голову и боковой левой в голову.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]}]}]},{"id":"S2","title":"Дальняя дистанция","stages":[{"id":"FAR-STRAIGHT-ATTDEF","no":9,"title":"Одиночные прямые: атака и защита","task":"Прямые в голову и туловище с места и с шагом; защиты подставкой и шагом назад; без контрударов","programs":[{"id":"PRG-FAR-STRAIGHT-1","title":"Прямой и подставка; шаг назад","review":false,"formats":["На лапах","Работа в паре"],"criteria":[["Техника","Левая рука вперёд для страховки.\nУченик чувствует и контролирует, каким местом кулака наносит удар."],["Тактика","Для развития подвижности и чувства дистанции.\nРазвитие быстроты: сначала по указанию, затем по неожиданно выставленной лапе, затем инициатива ученика."],["Особенности выполнения","С места и с шагом; в шеренгах по счёту, затем произвольно.\nС места и с шагом.\n45 мин основной части; по мере овладения механика переносится в подготовительную и заключительную части.\nПрименять все ранее усвоенные действия; лёгкие, не напряжённые, но быстрые и точные удары."],["Типичные ошибки","Стремление бить сильно до овладения техникой → излишнее напряжение, потеря точности, лишние движения."]],"exercises":[{"id":"ROM-P1-S01","text":"А — прямой левой в голову с места и с шагом; Б — подставка открытой ладони правой руки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-S02","text":"А — прямой правой в голову с места и с шагом; Б — подставка открытой ладони правой руки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-S03","text":"А — прямые левой или правой в туловище с места и с шагом; Б — подставка согнутой руки (от левой — правую, от правой — левую).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-S04","text":"А — прямой левой или правой в голову; Б — шаг назад, левая рука выставлена для страховки. А — прямой в туловище; Б — шаг назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L1-01","text":"Механика ударов из разных положений на месте и в передвижении (одноимённо, разноимённо); механика защит подставками; передвижение в боевой стойке вперёд, назад, в стороны; прямые на лапах с места и с шагом вперёд; прямой в голову с места и с шагом и защита подставкой открытой перчатки в паре.","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"лапы, перчатки","review":false},{"id":"ROM-MECH-PADS","text":"Индивидуально на лапах: одиночные удары с места из всех положений (одноимённо и разноимённо) → с шагом вперёд, назад, в стороны → 2–3 удара подряд в разных сочетаниях → тренер неожиданно выставляет то левую, то правую лапу под прямой/сбоку/снизу → ученик произвольно наносит один-два удара.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы","review":false}]},{"id":"PRG-FAR-STRAIGHT-B1","title":"Прямой левой в голову: подставка, уход назад","review":false,"formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"criteria":[["Техника","Удар головками пястных костей, кулак сжимается в момент касания; правая страхует.\nВарианты: ладонь прямо перед головой; с поворотом вниз; отводя вверх; отводя влево. Применять в последний момент."],["Тактика","Применяют чаще других: с шагом — атака, на месте — остановка атаки, при отходе, при маневрировании; разведка открытых мест и реакции, ложные прямые.\nОпределять момент удара по исходному положению противника; партнёр сначала бьёт медленно, затем быстрее.\nУходы (назад и в сторону) — от всех ударов; сохранять/разрывать дистанцию, сближаться, выходить из ближнего, маневрировать."],["Особенности выполнения","Под счёт; тренер задерживает в конечном положении для исправлений, особое внимание голове.\nУдары поочерёдно, без финтов, без сильных ударов, сохраняя дальнюю.\nНепринуждённо, легко, сохраняя стойку.\nПассивная защита усваивается быстрее, но переход к ответу труден — обучать уходу с контрударом.\nНачинать с шеренг и на месте."],["Типичные ошибки","Чрезмерно поднимает локоть; бьёт тыльной/внутренней стороной перчатки; не страхуется правой; опускает левую после удара; слишком широкий шаг или прыжок; задерживает руку у цели; замах.\nПреждевременно выставляет руку; чрезмерно расслабляет руку при контакте. Атакующие не отходят назад и двигаются только вперёд; опускают левую.\nЧрезмерно широкие шаги; потеря равновесия; голова откидывается назад."]],"exercises":[{"id":"BUL-Y1-L03-01","text":"Прямой левой в голову по элементам (перенос веса на левую, поворот туловища вправо, рука к цели, правая страхует) без перчаток в шеренге: на месте → с шагом вперёд → влево/вправо → с двойным шагом вперёд и назад.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y1-L03-02","text":"Защита от прямого левой подставкой правой ладони: в одной шеренге без партнёра → в двух шеренгах в перчатках → в парах в свободном передвижении (один бьёт, другой защищается) → поочерёдно, меняясь ролями через 1–3 удара.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L03-03","text":"Бой с тенью: стойка, передвижения, прямой левой в голову, защита подставкой правой ладони — свободно по залу.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"","review":false},{"id":"BUL-Y1-L04-01","text":"Уход назад: на команду тренера (одна шеренга) → на показ удара тренером/боксёром → на атакующий удар партнёра (две шеренги); в сочетании с подставкой ладони.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L04-05","text":"Мешок, стенка, груша — техника прямых ударов (1-й год); очередь у снарядов, остальные — бой с тенью, скакалка, лапы.","formats":["Бой с тенью","На мешке","На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"мешок, стенка, груша","review":false},{"id":"BUL-MT-02","text":"Боксёры одной шеренги наносят удары по перчаткам, в голову и туловище боксёрам другой; одна шеренга атакует — другая защищается; затем в движении без контрударов, затем с ответными или встречными. Позднее — сразу в парах: один атакует, другой защищается или защищается и контратакует; в следующем раунде роли меняются (или поочерёдно внутри раунда).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-SP-028","text":"Перенос веса тела с левой ноги на правую и обратно.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":true},{"id":"BUL-SP-029","text":"Из учебной стойки перенос веса с левой ноги на правую и обратно с поворотом плеч и тазобедренного сустава.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":true},{"id":"BUL-SP-030","text":"Из учебной стойки прямые удары, удары снизу и боковые с переносом веса с левой ноги на правую и обратно.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":true},{"id":"BUL-SP-031","text":"Удары с одиночными шагами влево (вправо). При шаге вправо (влево) удар наносят левой (правой) рукой, перенося вес тела на правую (левую) ногу.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":true},{"id":"BUL-SP-032","text":"Прямые и удары снизу, боковые удары не пере нося веса тела с ноги на ногу: при ударе прямым левой вес тела остается на левой ноге, при ударе правой — на правой.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":true},{"id":"BUL-SP-033","text":"Удары с одиночными, двойными шагами влево (вправо). При шаге влево удар наносят левой рукой и вес тела остается на левой ноге. При шаге вправо — пра вой рукой, вес тела на правой ноге.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":true},{"id":"BUL-SP-037","text":"Прямой удар снизу, боковой с шагом вперед (назад, влево, вправо).","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":true},{"id":"BUL-SP-038","text":"Из боевой стойки прямой (снизу, боковой) удар с двойным шагом вперёд (назад, влево, вправо); удар наносят на втором шаге.","formats":["На мешке"],"labels":["Имитация без партнёра"],"needs":"","equipment":"снаряды","review":true},{"id":"BUL-SP-053","text":"Подставка правой ладони с шагом вперед (назад) левой (правой) ногой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":true}]},{"id":"PRG-FAR-STRAIGHT-B2","title":"Прямой левой в туловище","review":false,"formats":["Работа в паре"],"criteria":[["Техника","На месте слегка поворачивать левую пятку кнаружи; при шаге носок левой ноги несколько влево; при подготовке удара правой вес на правой ноге; тщательно страховать голову.\nРука прижата к левому боку, правая у подбородка."],["Тактика","Начальный удар для атаки правой или левой в голову, ложный при маневрировании, контрудар с дальней.\nПосле удара в туловище обычно следует быстрый правой в голову — следить за правой рукой противника."],["Особенности выполнения","Развивать боевую ловкость; без сильных ударов."],["Типичные ошибки","Чрезмерный наклон вперёд вместо уклона вправо.\nДалеко выдвигает руку навстречу удару; не смещает туловище назад; задерживает руку внизу; подставляет локоть — травма атакующего.\nНовички прибегают только к уходу назад — использовать и другие защиты."]],"exercises":[{"id":"BUL-Y1-L05-01","text":"Прямой левой в туловище по элементам (вес на согнутую левую, наклон вниз-вправо, рука к цели, поворот левой пятки наружу, правая страхует) в шеренге: на месте, с шагом вперёд/назад/в стороны, с двойным шагом (удар со вторым шагом), с передвижением по квадрату/треугольнику.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y1-L05-02","text":"Подставка согнутой в локте левой руки, слегка прижатой к боку, с поворотом туловища слева направо и отходом от партнёра — от прямого левой в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L05-04","text":"Прямой левой в туловище — подставка согнутой левой; прямой левой в голову — уклон вправо; то же — встречный прямой левой в туловище (атакующий защищается подставкой правой ладони с отбивом влево и уходом назад); то же с подставкой правой ладони — встречный левой в туловище или в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L05-05","text":"Условный бой левой рукой в голову или туловище с защитами подставкой, уклоном вправо и уходом назад, 1–2 мин, легко.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-STRAIGHT-B3","title":"Прямой правой в голову и туловище","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Без замаха; кулак при касании вполоборота налево; ускорять в конце; кулак достигает цели одновременно с передачей веса на левую; левая ладонью страхует голову, локтем туловище.\nКомбинированные защиты (3, 4) наиболее надёжны — обучать им с самого начала.\nСходен с прямым правой в голову, поворот туловища одновременно с уклоном влево."],["Тактика","Наносится с дальней и средней; эффективен при быстроте и точности.\nУдар правой наносят только в атаке, т.к. защита от него ещё не усвоена; атакующий бьёт без отвлекающих движений.\nОсобенно действен на средней; на дальней противник успевает защититься; в атаке риск встречного правой — страховать голову, быстро уходить; готовить отвлекающими ударами левой, обманными движениями.\nПуть правой руки длинный — движение легко проследить."],["Особенности выполнения","Порядок обучения тот же, что для левой; сначала с места, затем с шагом."],["Типичные ошибки","Задерживаться в конечном положении опасно — открыт туловище; после удара (особенно промаха) сразу в стойку.\nСлишком сильно отходит назад и уклоняется — мешает сразу контратаковать.\nИзлишне наклоняется вперёд, задерживает руку, не страхуется левой; наклон с прямыми ногами — опасное движение головой, таз назад."]],"exercises":[{"id":"BUL-Y1-L07-01","text":"Прямой правой в голову: толчок правой, вес на левую, поворот туловища справа налево, правая пятка кнаружи и вперёд-вправо, рука вперёд по прямой, левая страхует; на месте → с шагом вперёд → двойной шаг → по квадрату/треугольнику; без перчаток.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y1-L08-02","text":"Защиты от прямого правой в голову: подставка левого плеча; подставка правой ладони; подставка плеча и ладони на месте и с шагом назад (и вправо); подставка руки с уклонами; защита от двойного удара; ответные прямые левой после ухода.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L10-01","text":"Прямой правой в туловище: вес на левую, поворот и наклон влево-вниз (с уклоном влево), рука к цели, левая страхует, при шаге левая нога влево-вперёд по диагонали; одиночные и двойные шаги, по квадрату/треугольнику, без перчаток. Корректирующее: стоя спиной к стене в 10–15 см — удар правой в туловище с переносом веса на согнутую левую, не касаясь тазом стены.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"стена","review":false},{"id":"BUL-Y1-L10-02","text":"Подставка согнутой левой (с поворотом вправо и небольшим шагом назад) и отбив правой ладонью влево; сочетания с уходами назад и вправо, шагом влево. Упражнение 2: один непрерывно бьёт прямые левой в голову, другой защищается подставкой правой ладони, затем отбивом влево, наконец уклоном вправо с одновременным прямым левой в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L10-03","text":"Прямой правой в туловище — подставка согнутой левой; прямой левой в голову — подставка правой ладони; — отбив правой влево; — уклон вправо со встречным прямым левой в туловище; прямой левой в туловище — подставка согнутой левой и ответный прямой правой в голову; прямой (правой) в голову — уклон вправо со встречным левой в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L10-04","text":"Условный бой: левой в голову или правой в туловище с подставками левого плеча, правой ладони и согнутой левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-STRAIGHT-COUNTER","no":10,"title":"Одиночные прямые: ответные, затем встречные","task":"После защиты — ответный прямой с места, затем с шагом; затем встречные (уклоном)","programs":[{"id":"PRG-FAR-STRAIGHT-2","title":"Ответный прямой после защиты","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Ответная форма контратаки."],["Особенности выполнения","С места → с шагом вперёд; после овладения защитами."]],"exercises":[{"id":"ROM-P1-S05","text":"После одной из защит Б наносит одиночный ответный прямой в голову или туловище левой или правой — сначала с места, затем с шагом вперёд.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L2-01","text":"А — прямой левой в голову; Б — шаг назад и с движением вперёд ответный прямой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L2-02","text":"А — прямой правой в голову; Б — шаг назад и ответный прямой левой или правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L2-03","text":"А — прямой левой в туловище; Б — подставка согнутой правой и ответный прямой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-DEF-O1","title":"Защиты шагами и подставками с ответом","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Вызвать промах; сохранить дальнюю; назад-влево — сменить позицию на правостороннюю или ответить прямыми правой, левой.\nКомбинация после ухода влево очень эффективна и трудна для защиты.\nЦель — ответный прямой левой и контратака серией прямых на средней.\nПродолжения слитно: снизу левой в туловище — короткий прямой правой — боковой левой; боковой левой — снизу правой в туловище — акцентированный боковой левой; боковой левой — правой в голову — акцентированный снизу левой в туловище."]],"exercises":[{"id":"OGE66-F-DEF-01","text":"Шаг назад со страховкой правой; шаг вправо (толчок левой, правая тыльной стороной у подбородка) — ответные прямые; шаг влево (толчок правой, левая ладонь страхует, поворот справа налево) — ответный прямой левой; назад-вправо; назад-влево со сменой позиции на правостороннюю.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-DEF-02","text":"От прямого левой: шаг вправо с поворотом слева направо и отбивом правой ладонью — ответные левой снизу в туловище или боковой в голову, затем акцентированный короткий прямой правой; шаг влево с поворотом и отбивом левой ладонью — ответный прямой правой + снизу левой в туловище или боковой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-DEF-03","text":"Толчком левой отклонить тело назад с весом на правую, подставить правую ладонь; как только удар коснётся ладони — оттолкнуться правой и ответить прямым левой; развить серией прямых на средней.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-DEF-04","text":"От прямого правой или левой в голову в конце движения: левое плечо под удар, правая ладонь страхует подбородок, поворот слева направо, вес на правую; ответный прямой правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-STRAIGHT-3","title":"Встречный прямой с уклоном","review":false,"formats":["Работа в паре"],"criteria":[["Техника","При уклоне обе руки свободны."],["Тактика","Встречная форма контратаки.\nУклон используется как исходное положение для встречных."],["Особенности выполнения","Только после ответной формы.\nУклоны часто сочетаются с вышагиванием и контрдействиями."],["Типичные ошибки","Прямолинейный подход подставляет голову под встречные; потеря равновесия при движении вперёд — развивать устойчивость и сохранение дистанции."]],"exercises":[{"id":"ROM-P1-S06","text":"После овладения ответной формой — встречные прямые контрудары на прямые атаки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-UK01","text":"Уклон вправо от прямого левой в голову — встречный прямой или боковой левой в голову или туловище; уклон влево от прямого левой — встречный прямой правой в голову или туловище (в ряде случаев — левой); аналогично от прямого правой; уклоны с вышагиванием.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L2-05","text":"А — прямой левой в голову; Б — уклон вправо и встречный прямой левой в голову или туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L2-06","text":"А — прямой правой в голову; Б — уклон влево и встречный прямой правой в голову или туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-IM-03","text":"Против прямолинейного подхода: при атаке прямым левой — небольшой уклон вправо, прямым правой — уклон влево.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-STRAIGHT-B4","title":"Встречный и ответный прямой левой; уклон вправо","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Встречный — одновременно с ударом противника и защитой; ответный — после удара и защиты; принимая удар, слегка сместить ладонь в сторону; при отходе опираться на переднюю часть стопы, не переносить вес полностью на правую.\nУклон в сторону, а не вперёд; при уклоне внутрь страховать голову и живот или накладывать ладонь на свободную руку противника."],["Тактика","Встречный левой целесообразен, если противник не страхует голову правой.\nБезопаснее уклон во внешнюю сторону; новичкам чаще уклон вправо — руки свободны для контрударов. Контрудар левой в туловище — чаще встречный с уклоном вправо; ответный — после ухода назад."],["Особенности выполнения","Удары с разными, не короткими интервалами; партнёр контратакует не на каждый удар; раунды 2–3 мин.\nТри варианта применяются во всех уроках."],["Типичные ошибки","Атакующий бьёт преждевременно; защищающийся держит перчатку не у подбородка.\nСильные, акцентированные удары, обмен ударами запрещены.\nЧрезмерно сгибает туловище; задерживается в уклоне, теряет равновесие; откидывает/поворачивает голову. Атакующий вызывает контратаку без удара; партнёр контратакует, не дождавшись атаки — атакующему бить замедленно, партнёру не отвечать на каждый удар."]],"exercises":[{"id":"BUL-Y1-L04-02","text":"Встречный прямой левой с подставкой правой ладони: на команду (одна шеренга без перчаток) → с защитой от показа тренера → в двух шеренгах в перчатках (атака прямым левой с шагом — принять на правую ладонь и одновременно встречный левой) → ответный после ухода назад (резкий толчок правой и прямой левой с шагом). Упражнение-сигнал: атакующий маневрирует, бьёт по сигналу открытой ладони партнёра.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L04-03","text":"В перчатках: (1) один атакует весь раунд, другой защищается без контратаки; (2) то же с контратакой; (3) поочерёдно в течение раунда. Таблица: прямой левой в голову — уход назад с подставкой; — ответный прямой левой после подставки и ухода; — ответный или встречный прямой левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L04-04","text":"Двусторонний бой только прямыми левой в голову, обязательно с защитой (подставка, уход), без контрударов; пары равных; бой как игра — коснуться цели сжатым левым кулаком.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L05-03","text":"Уклон вправо (наружу) от прямого левой в голову; встречный прямой левой в туловище с уклоном вправо; подставка правой ладони с отбивом влево.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-STRAIGHT-B5","title":"Ответный прямой правой; уход вправо","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Точная подставка левого плеча от прямого правой, затем контрудар правой."],["Тактика","Контрудар правой в голову чрезвычайно действен; сначала ответная форма — мгновенно после прочной защиты. Ответ на правый прямой — после тех же или комбинированной защиты (шаг вправо-назад с уклоном вправо)."],["Особенности выполнения","Начинать в разомкнутом строю.\nСначала защита от контрудара без контрудара, затем с ним; атаки только в голову, одиночные с интервалом, возврат на дальнюю дистанцию; только касание."],["Типичные ошибки","Сильные удары запрещены — только касание."]],"exercises":[{"id":"BUL-Y1-L07-02","text":"Уход вправо (шаг правой вправо-вперёд) с поворотом туловища направо от прямого левой в голову; встречный и ответный, сочетаемые с уходом вправо (назад) с поворотом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L07-03","text":"Прямой левой в голову — уход вправо с поворотом; — уклон вправо и встречный прямой левой в туловище; — отбив правой влево с уходом вправо-назад и ответный левой в голову/туловище; прямой левой в туловище — подставка правой ладони (как дано) и ответный левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L09-02","text":"Подставка левого плеча (и правой ладони) от прямого правой или двойного, затем ответный прямой правой в голову; сначала после ухода назад; на атаку прямым левой — ответ правой после подставки плеча, шага назад или отбива левой вправо.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L09-03","text":"Прямой правой в голову — подставка левого плеча и правой ладони с уходом назад; двойной левой в туловище–голову — подставка согнутой левой и правой ладони; прямой левой (правой) в голову — подставка плеча и ладони с шагом назад и ответный прямой правой с шагом назад; то же без шага назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-COUNTER-O1","title":"Встречные и ответные прямые","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Сжатие и сгибание кулака в последний момент; опередить и своевременно перенести вес на левую.\nПрочно сжимать кулак в момент удара."],["Тактика","Правой в туловище — почти невозможно защититься; особенно использовать в первом раунде.\nВстречный прямой правой эффективен, часто решает исход поединка."]],"exercises":[{"id":"OGE66-F-CTR-01","text":"На атаку прямым левой в голову: толчок правой, шаг вперёд — прямой левой в голову (правая ладонь у подбородка готова сдержать удар); в туловище — маленький шаг, тело вперёд-вправо 45°.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-CTR-02","text":"Толчок правой, небольшой шаг левой вперёд, поворот справа налево — прямой правой в голову; в туловище — туловище вперёд и вниз, пальцы кулака вниз.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-CTR-06","text":"Встречный прямой правой: шаг левой, поворот справа налево, незначительный отклон головы и туловища влево; боковой правой в туловище: шаг вперёд-влево, поворот справа налево.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-PARRY","no":11,"title":"Отбивы и уклон назад от прямых","task":"Отбивы на месте, с шагом назад, с шагом в сторону; затем контрудары; уклон назад → с шагом → ответ","programs":[{"id":"PRG-FAR-PARRY-1","title":"Отбивы от прямых и контрудары","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Поворот на правой ноге в левую сторону.\nПоворот на левой ноге вправо."],["Тактика","Отбив кнаружи создаёт условия для встречных свободной рукой или ответных отбивающей."],["Особенности выполнения","На месте и с шагом назад.\nПосле усвоения отбивов; далее — с шагами в стороны с поворотом."]],"exercises":[{"id":"ROM-P1-OT01","text":"А — прямой левой в голову; Б — отбив правой влево или вправо, на месте и с шагом назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-OT02","text":"А — прямой правой в голову; Б — отбив левой вправо или влево, на месте и с шагом назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-OT03","text":"А — прямой левой в голову; Б — отбив правой влево с шагом вправо и поворотом на правой ноге влево.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-OT04","text":"А — прямой правой в голову; Б — отбив левой вправо с шагом влево и поворотом на левой ноге вправо.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-OT05","text":"А — прямой левой в туловище; Б — отбив правой вправо (кнаружи) на месте и с шагом назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-OT06","text":"А — прямой правой в туловище; Б — отбив левой влево (кнаружи) на месте и с шагом назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-OT07","text":"Отбив внутрь (левый прямой — правой влево; правый прямой — левой вправо) с ответными прямыми, боковыми, снизу в голову и туловище; отбив кнаружи с контрударами свободной рукой или ответным той рукой, что отбивала; затем те же контрудары с отбивом и шагами в стороны с поворотом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-PARRY-2","title":"Уклон назад","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Защита на дальней дистанции."],["Особенности выполнения","Уклон → с шагом назад → ответ с поступательным движением."]],"exercises":[{"id":"ROM-P1-UN01","text":"Уклон назад от прямых и боковых: сначала только уклон, затем уклон с шагом назад, затем ответные контрудары с движением вперёд (любой удар левой или правой).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-PARRY-B1","title":"Отбив и ответный","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Отбивают исключительно прямые удары, ладонью или предплечьем; лучше правой — сохраняет защитное положение и выводит противника из равновесия."],["Особенности выполнения","Сначала в строю, затем в парах в свободном перемещении."],["Типичные ошибки","Далеко и преждевременно отводит руку вперёд."]],"exercises":[{"id":"BUL-Y1-L06-02","text":"Отбив правой ладонью влево от прямого левой в голову; ответный прямой левой в голову после отбива.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L06-04","text":"Условный бой левой рукой в голову или туловище с защитами уклоном, подставкой, отбивом и уходом назад — лёгкие быстрые удары.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-PARRY-O1","title":"Отбивы, уклоны, отклоны","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Отбив — в последний момент движения кулака к цели, в предплечье.\nСобранность всех звеньев: рук, ног, головы."],["Тактика","Каждый отбив превращать в активную защиту; ответ избирателен по созданному исходному положению; отбив вниз — против уступающих в росте.\nОдна из важнейших и прочных защит; после уклона боксёр на средней/ближней — перехватывать инициативу ответными.\nХарактерен для дистанционного боя, высоких, подвижных и гибких; не упустить момент промаха."],["Особенности выполнения","Действия после уклона заранее тщательно готовить на тренировке."]],"exercises":[{"id":"OGE66-F-DEF-05","text":"Отбив левой внутрь с шагом левой — прямой правой (+ боковой левой или снизу в туловище); правой внутрь с весом на правую — прямой левой (+ правой в голову или левой снизу в туловище; или боковой левой с шагом); левой наружу тыльной стороной с выпадом вправо — прямой/боковой правой с шагом, снизу правой в туловище; правой наружу с шагом левой и наклоном вперёд-влево — прямой снизу или снизу в туловище; левой вверх с приседом — прямой снизу правой в голову; правой (левой) вниз — прямой левой (правой, снизу левой).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-DEF-06","text":"Уклон вправо: небольшой шаг навстречу, уклон вперёд-вправо ≈45°, руки прижаты, голова у левого плеча, правая подтянута. Уклон влево: толчком правой незначительный шаг левой, поворот справа налево ≈45° — ответные снизу в туловище, прямой снизу в голову, боковой левой на средней/ближней, серия.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-DEF-07","text":"В последний момент отклонить туловище назад (назад-вправо, назад-влево), создавая исходное положение: назад — ответные прямые; назад-вправо (от правой) — серия прямых правой, левой с продвижением; назад-влево (от левой) — прямой, прямой снизу или боковой левой с развитием на средней/ближней.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-DUCK-STRAIGHT","no":12,"title":"Нырок от прямых","task":"Нырок от прямых с контрударом; условный бой уклон/нырок + контрудар","programs":[{"id":"PRG-FAR-DUCK-1","title":"Нырок от прямых и контрудар","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Нырок — основная защита от боковых, но применим и от прямых."],["Особенности выполнения","Одна шеренга → две → пары с поочерёдной атакой. Тщательнее — при обучении боковым."],["Типичные ошибки","Сгибается вперёд с выпрямленными ногами (основная); опасное движение головой; чрезмерно сгибает колени и поворачивает голову, теряя противника из виду."]],"exercises":[{"id":"BUL-Y1-L13-02","text":"Нырок от прямых ударов: слегка присесть, группируясь, поднырнуть под руку и выйти влево или вправо; в сочетании с шагом и подставками/отбивами; ответный — когда партнёр выпрямляется после защиты, встречный — в момент приседания. Самостоятельно у стены: левым носком в плинтус, нырок вправо/влево; спиной к стене в учебной стойке для исправления.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L13-03","text":"Прямой левой в голову — нырок, ответный прямой левой (правой) в голову; двойной левая(голова)–правая(туловище) — подставка правой ладони и согнутой левой, ответный правой в голову; то же или левая–правая в голову — с левым плечом, одиночный прямой правой; одиночные, двойные прямые — произвольная защита, одиночные прямые левой/правой произвольно.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L14-02","text":"Совершенствование уклона вправо и нырка с контрударом; условный бой левой или правой в голову с защитами уклоном вправо или нырком, 5 мин.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-DEF-O2","title":"Нырок, приседание, комбинированная защита","review":false,"formats":["Работа в паре"],"criteria":[["Техника","У искусных — небольшая амплитуда."],["Тактика","Нырок, начатый вправо, — затем боковой левой; начатый влево — боковой правой.\nИзбежать удара и перейти в наступление на средней/ближней; особенно эффективна для низкорослых.\nУкрывает уязвимые места при неожиданной атаке серией."]],"exercises":[{"id":"OGE66-F-DEF-08","text":"По ходу бокового левой туловище влево—вниз—вправо—вверх (полукруг головой) с приседанием, мягко и слитно; от прямого — в обе стороны.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-DEF-09","text":"От прямого и бокового левой в голову в конце удара равномерно присесть; для ответа левой — вес больше на левую и вперёд, для ответа правой — на правую.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-DEF-10","text":"Одновременно: небольшой отклон назад, уклон вправо, подставки левого плеча, правой ладони, левого предплечья у туловища.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-CROSS","no":13,"title":"Встречный удар через руку","task":"Вызвать прямой левой и встретить ударом через руку; завершает первый этап","programs":[{"id":"PRG-FAR-CROSS-1","title":"Удар через руку","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Шаг вперёд, небольшой уклон влево, удар сбоку и сверху; иногда близок к прямому."],["Тактика","Требует подготовки: вызвать противника на прямой левой; после удачного удара — действия левой на ближней."],["Особенности выполнения","Требует решительности и смелости."]],"exercises":[{"id":"ROM-P1-KR01","text":"Вызвать атаку прямым левой; своевременно поступательное движение с шагом вперёд, небольшим уклоном влево и боковым в голову через левую руку противника (удар сбоку-сверху), чаще правой; правше–левше — левой через правую.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-CROSS-O1","title":"«Кросс» правой","review":false,"formats":["Работа в паре"],"criteria":[],"exercises":[{"id":"OGE66-F-CTR-05","text":"На прямой левой в голову: толчок правой, шаг левой, поворот справа налево с наклоном вниз — встречный перекрёстный правой; пальцы вниз.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-SINGLE-BOUT","no":14,"title":"Условный бой одиночными ударами","task":"Условный бой по заданию на пройденные одиночные удары и защиты; затем произвольный","programs":[{"id":"PRG-FAR-SINGLE-BOUT-1","title":"Условный бой: одиночные","review":false,"formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"criteria":[["Тактика","Задание соответствует содержанию последних занятий (например, 2–3 занятия по боковым с дальней → условный бой на них)."],["Особенности выполнения","Тренер подсказывает, может остановить для показа. В учебном бою — лёгкость, без стремления сильно ударить; требовать быстрого выполнения приёмов.\n15 мин в составе части урока."],["Типичные ошибки","Боксёра, не показывающего указанную защиту/удар, к условным боям не допускать — вернуть к изучению в паре и механике. Грубая сила и сильные удары ограничивают рост, ведут к потере равновесия."]],"exercises":[{"id":"ROM-SP-01","text":"Условный бой по заданию тренера: несколько пар по залу или одна пара на ринге строго по времени. Пример задания: защита от прямых и боковых шагом назад, затем два ответных прямых. Сначала один атакует из всех положений, другой принимает только указанные защиты; затем защищается и наносит ответные или встречные; во втором раунде меняются. Последующие бои включают пройденные и добавленные приёмы.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L2-07","text":"Условный бой: атаки прямыми одиночными в голову левой и правой, защиты уклонами со встречными прямыми в голову или туловище; атаки боковыми в голову, защиты подставками согнутой руки и ответные боковые левой или правой; затем произвольный бой с пройденными приёмами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L2-SH","text":"Передвижение в прямой и боковой позиции; прямые, боковые и снизу в голову и туловище с места и в передвижении; подставки и уклоны; «бой с тенью» с заданием действовать контратакующими ударами.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"","review":false},{"id":"ROM-L2-08","text":"Совершенствование одиночных ударов на мешке, стенке, грушах и лапе.","formats":["На мешке","На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"мешок, стенка, груши, лапа","review":false},{"id":"BUL-MT-03","text":"Односторонний: один атакует, другой защищается или защищаясь контратакует. Двусторонний: оба произвольно, но с ограниченным выбором средств. Все пары одновременно по залу; число раундов по подготовленности.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-GENERAL-ROM","title":"Общее занятие: одиночные с места → с шагом → с маневрированием","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Сначала по указанию, затем по выбору боксёров; медленно → быстрее."]],"exercises":[{"id":"ROM-P2-U01","text":"Один атакует одиночными (прямые, сбоку, снизу, в голову и туловище) с места → с шагом → с маневрированием; другой применяет защиту.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-U02","text":"Атаки одиночными, отдельные защиты с ответными одиночными, затем встречными.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-PADS-ROM","title":"Индивидуальный урок: лапы и тренер в перчатках","review":false,"formats":["На мешке","На лапах","Работа в паре"],"criteria":[["Техника","Устойчивое положение для контрудара после защиты."],["Тактика","Условно → неожиданно."],["Особенности выполнения","Медленно, расчленённо, под счёт, без напряжения → быстрее, с меньшей амплитудой.\nДетали исправлять в индивидуальном уроке → на общих занятиях → в учебной боевой практике. Снаряды: по заданию тренера, затем произвольно.\nНеожиданно; все защиты точно и быстро."]],"exercises":[{"id":"ROM-P1-TR01","text":"Лапы: одиночные удары из разных положений, тренер добивается точности. Тренер в перчатках попеременно наносит одиночные удары — сначала условно, затем неожиданно в разных сочетаниях; одна рука атакует, другая с открытой перчаткой подставляется для контрудара.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы, перчатки","review":false},{"id":"ROM-IM-01","text":"Индивидуальный урок: 1) одиночные и групповые удары на лапах; 2) тренер в перчатках как партнёр ставит задачу; 3) наблюдение за одним боксёром в паре или на снаряде. Недостаток повторять до правильного выполнения.","formats":["На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"лапы, перчатки","review":false},{"id":"ROM-IM-06","text":"Тренер держит лапу правой и неожиданно делает движение удара левой в перчатке — ученик быстро реагирует и бьёт по заданию; тренер с лапами на обеих руках неожиданно выставляет то одну, то другую — ученик бьёт соответствующий удар; с места → в движении вперёд, назад, в стороны с сохранением дистанции; то же после защиты (быстрый нырок и боковой контрудар в голову).","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы, перчатка","review":false},{"id":"ROM-IM-07","text":"Тренер в перчатках неожиданно наносит одиночные, потом двойные и серийные удары в голову и туловище — ученик быстро принимает защиту; затем то же в паре: один развивает быстроту ударов, другой — защит.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-DOUBLE-ATTDEF","no":15,"title":"Двойные удары: атака и защиты","task":"Атаки двумя ударами (прямые → с боковыми и снизу) и защиты подставками с передвижением; комбинированные защиты; без контрударов","programs":[{"id":"PRG-FAR-DOUBLE-1","title":"Двойные и подставки","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Атаковать снизу на дальней трудно; легче вторым ударом, когда дистанция сократится; при соответствующей дистанции можно и первым.\nПри ударе в туловище противник опускает руку — успеть ударить в открытую голову."],["Особенности выполнения","Все защиты выполнять также с шагами назад и в стороны, сочетая руки с передвижением. Сначала без контрударов.\nТребует быстрых действий."]],"exercises":[{"id":"ROM-P2-A01","text":"А — два последующих удара в голову с места и с подходом; Б — подставка открытой правой перчатки или в комбинации с подставкой левого плеча.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A02","text":"А — прямой левой в туловище и правой в голову; Б — подставка согнутой левой руки и открытой правой перчатки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A03","text":"А — прямой правой в туловище и прямой левой в голову; Б — подставка согнутой левой и правой открытой перчатки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A04","text":"А — прямой левой в голову и боковой правой в голову; Б — правая открытая перчатка и согнутая левая или тыльная сторона перчатки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A05","text":"А — прямой правой в голову и боковой левой в голову; Б — открытая правая перчатка и согнутая правая рука.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A06","text":"А — прямой левой в туловище и боковой правой в голову; Б — согнутая левая и левое плечо с подставкой открытой правой перчатки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A07","text":"А — прямой правой в туловище и боковой левой в голову; Б — согнутая левая и согнутая правая или тыльная сторона правой перчатки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A08","text":"А — два боковых левой и правой в голову; Б — согнутые правая и левая руки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A09","text":"А — боковой левой и прямой правой в голову; Б — согнутая правая и открытая правая перчатка. Вариант: боковой правой и прямой левой; Б — согнутая левая/тыльная сторона левой и открытая правая перчатка.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A10","text":"А — боковой левой в туловище и прямой правой в голову; Б — согнутая правая и правая или левая открытая перчатка.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A11","text":"А — прямой левой и снизу правой в голову; Б — открытая правая перчатка.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A12","text":"А — прямой левой в голову и снизу правой в туловище; Б — открытая правая перчатка и согнутая левая.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A13","text":"А — прямой правой в голову и снизу левой в голову или туловище; Б — левое плечо или правая открытая перчатка; от снизу в голову — правая открытая перчатка, в туловище — согнутая левая.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A14","text":"А — боковой левой в голову и снизу правой в туловище; Б — согнутая правая; от снизу в туловище — согнутая левая.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A15","text":"А — боковой правой в голову и снизу левой в голову; Б — согнутая левая или открытая перчатка; от снизу левой в голову — правая открытая перчатка.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A16","text":"А — прямой правой в туловище и снизу левой в голову или туловище; Б — согнутая левая; от снизу левой — правая открытая перчатка.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A17","text":"А — снизу левой в голову/туловище и боковой правой в голову; Б — правая открытая перчатка от снизу, согнутая левая от бокового.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A18","text":"А — снизу правой в голову/туловище и боковой левой в голову; Б — согнутая левая; от бокового левой — согнутая правая или тыльная часть перчатки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A19","text":"Два удара одной рукой: боковой левой в туловище и в голову; прямой правой и боковой правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-A20","text":"От комбинаций прямых с боковыми и снизу — шаг назад и в стороны или уклон назад (от ударов в голову) с шагом назад/в стороны с поворотом и уклоном в стороны.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-DOUBLE-2","title":"Комбинированные защиты от двойных","review":false,"formats":["Работа в паре"],"criteria":[["Техника","От двух быстрых ударов почти невозможно два уклона подряд; защищаться руками или от первого руками, от второго туловищем/шагом."],["Тактика","Чтобы сохранить дальнюю — отбивы с шагами назад, в стороны и уклонами назад; чтобы сблизиться — отбивы с движением вперёд."]],"exercises":[{"id":"ROM-P2-C01","text":"Два прямых в голову; защита — открытая правая перчатка и уклон влево или вправо.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-C02","text":"Прямой левой и боковой правой в голову; открытая правая перчатка и нырок от правого бокового.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-C03","text":"Прямой правой и боковой левой в голову; открытая правая перчатка и нырок от бокового левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-C04","text":"Боковой правой и боковой левой в голову; нырки от обоих или подставка от первого и нырок от второго.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-C05","text":"Прямой левой и боковой правой в голову; отбив правой влево или вправо и нырок от бокового правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-C06","text":"Прямой левой и прямой правой в голову; подставка согнутой правой и отбив левой вправо правой руки противника.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-C07","text":"Прямой правой и боковой левой в голову; отбив левой вправо/влево правой руки противника и нырок от бокового левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-DOUBLE-B1","title":"Двойные прямые левой","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Первый удар обязательно лёгкий, иначе тормозит второй; два удара с каждым небольшим шагом левой вперёд (назад — правой); согласовать ноги и руки."],["Тактика","Второй удар неожиданен и почти всегда достигает цели; лёгкими ударами выявляют реакцию противника.\nПри избирательной атаке защищающийся особенно внимателен, не стремится отвечать на каждый удар; после ухода быстро переходить в контратаку.\nПервый отвлекающий (ложный) удар в голову, чтобы противник сосредоточился на защите головы и раскрыл туловище."],["Особенности выполнения","Вначале в шеренге, затем в парах.\nСледить за координацией и согласованностью движений."],["Типичные ошибки","Попытки «попробовать» правую в бою — немедленно пресекать; действовать только по заданию."]],"exercises":[{"id":"BUL-Y1-L06-01","text":"Двойной (повторный) прямой левой в голову с шагом и страховкой правой: с шагом вперёд/назад/в стороны, с двойным шагом, по квадрату/треугольнику; затем в парах.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L06-03","text":"Избирательная атака прямым левой в голову или туловище — подставка правой ладони, согнутой левой, уклон вправо, уход назад; двойной прямой левой — подставка правой ладони с уходом назад; прямой левой в голову — отбив правой влево и ответный левой; прямой левой — уход назад с подставкой и ответ.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L08-01","text":"Двойной прямой левой в голову и в туловище с шагами и страховкой правой; также с правой в голову — без перчаток в одной и двух шеренгах.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L08-03","text":"Двойной прямой левой в голову и туловище — подставка правой ладони и согнутой левой с уходом назад; прямой правой в голову — подставка левого плеча и правой ладони, то же с уходом назад; прямой левой или правой в голову — ответный прямой левой в голову/туловище (атакующий защищается отбивом правой влево с уходом назад).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L08-04","text":"Двусторонний бой только левой рукой (одиночные, двойные) с защитами; попытки бить правой пресекать.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L09-01","text":"Двойной прямой левой в туловище — левой в голову с шагом и страховкой правой; прямые левой и правой — без перчаток в шеренгах.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-DOUBLE-B2","title":"Двойные левой — правой","review":false,"formats":["Работа в паре"],"criteria":[["Техника","При первом левом можно не переносить вес полностью, оставляя на правой для второго; с движением назад — при левом вес на левую, при правом с шагом правой назад — на правую; руки мгновенно одна за другой, не теряя равновесия.\nЗащита от двойных — сочетания защит от одиночных и простейшие комбинированные; избегать каждого удара."],["Тактика","Применяются в атаке и контратаке, во встречной и ответной форме; атаке двойными должны предшествовать отвлекающие движения, маневрирование, ложные удары."],["Особенности выполнения","Сначала в строю, затем в парах; сначала защита от ударов, потом от контрударов.\nУпражнения в строю без перчаток."]],"exercises":[{"id":"BUL-Y1-L11-01","text":"Двойные прямые левой — правой в голову: с шагом вперёд, влево, вправо, с поворотом налево, с шагом назад; защиты от двойных и одиночных; ответные после защиты от двойных.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L11-02","text":"Прямой левой в голову — подставка правой ладони; прямой правой в туловище — согнутая левая; прямой левой в голову — отбив правой влево с уходом назад, ответный прямой левой; двойной левой–правой в голову — подставка правой ладони и левого плеча с уходом назад; то же — ответный прямой правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L11-03","text":"Условный бой левой и правой рукой произвольно с изученными защитами, 3 мин.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L12-01","text":"Двойной прямой левой в туловище — правой в голову; защиты уклоном вправо и уходом; встречные после защиты. В перчатках: двойной левая(туловище)–правая(голова) — подставка согнутой левой, плеча, ладони, ответный прямой правой в голову; то же или левая–правая в голову с уходом назад; прямой левой в голову — уклон вправо, встречный левой в голову/туловище или ответный правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L12-02","text":"Атакующий — одиночные и двойные прямые в голову и туловище; контратакующий — только одиночные встречные и ответные, защиты по усмотрению.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L13-01","text":"Двойной прямой левой в голову — правой в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-DOUBLE-O1","title":"Двухударные «раз-два»","review":false,"formats":[],"criteria":[["Техника","Кулак наклоняется в лучезапястном суставе ладонью вниз; левый локоть к туловищу, ладонь защищает голову; левую ногу слегка согнуть при правой; голова под защитой плеча и свободной руки.\nУклон влево позволяет кулаку пройти между локтем противника в солнечное сплетение."],["Тактика","Атакующая, встречная, ответная формы; выход прямым левой с отходом предохраняет от контрудара правой.\nПротив боксёра, владеющего дальним боем; защищаться очень трудно.\nОтвлечь от защиты головы."],["Особенности выполнения","Обучать всех без исключения; прямой правой легче усваивается в комбинации с левой.\nСложная координация, но очень эффективны.\nХладнокровно, расслабить мышцы, бить свободно."]],"exercises":[{"id":"OGE66-F-CMB2-01","text":"Толчок правой, шаг левой вперёд, прямой левой — разворот плечевого пояса — прямой правой с переносом веса на левую и сгибанием в пояснице; вернуться толчком левой шагом назад с прямым левой.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-CMB2-02","text":"Обязательный предварительный финт левой в голову, затем под один счёт две одновременные: левая сверху вниз перекрывает защиту, правая — в подбородок; правая нога подтягивается; выход шагом назад с прямым левой.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-CMB2-03","text":"Вариант 1: левая под шаг левой, при правой правая нога подтягивается. Вариант 2: левая в голову — финт, вес на правой; правая в туловище с переносом веса на левую и уклоном влево.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-CMB2-04","text":"Левой в туловище с шагом вперёд и акцентированным наклоном вперёд-вправо — затем правой в голову с отходом, левой в голову с шагом назад.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-CMB2-05","text":"Финт прямым левой в голову с шагом левой влево — два прямых левой-правой в туловище.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-CMB2-06","text":"При атаке противника — прямой левой — правой в голову с отходом назад левой-правой ногой, несколько опережая его удары.","formats":[],"labels":["Подготовительное упражнение"],"needs":"","equipment":"","review":false}]}]},{"id":"FAR-DOUBLE-COUNTER","no":16,"title":"Двойные: контратака","task":"Ответные, затем встречные одиночные на двойные; двойной ответ на одиночную; двойной встречный; ответный двойной на двойной","programs":[{"id":"PRG-FAR-DOUBLE-3","title":"Одиночный ответ и встречный на двойные","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Ответный — рукой, не занятой защитой; если удар не достиг цели (отклон назад), можно любой рукой."],["Тактика","Выбор ответной/встречной формы зависит от защиты: отбив правой влево → ответная; уклон вправо от левого прямого → встречная.\nВстречные могут наноситься как от первого, так и от второго атакующего удара. При уклонах в стороны встречные наносятся во время уклона."],["Особенности выполнения","Сначала ответные, потом встречные."]],"exercises":[{"id":"ROM-P2-R01","text":"Два удара в голову; открытая правая перчатка и ответный прямой или боковой левой в голову или туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-R02","text":"Прямой левой в туловище и прямой правой в голову; согнутая правая от удара в туловище и отбив левой правой руки вправо, ответный прямой/боковой правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-R03","text":"Прямой левой и боковой правой в голову; отбив правой влево или открытая правая перчатка + согнутая левая; ответный прямой/боковой правой в голову или снизу в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-R04","text":"Прямой левой и боковой правой в голову; открытая правая перчатка, нырок от бокового правой и ответный боковой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-R05","text":"Боковой левой в голову и снизу правой в голову/туловище; согнутая правая и согнутая левая, ответный прямой правой, боковой в голову или снизу.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-R06","text":"Прямой левой и боковой/прямой правой в голову; уклон назад, шаг назад или их комбинация с одиночным ответным прямым/боковым левой или правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-K01","text":"Два удара в голову; открытая правая перчатка, отбив правой руки противника влево левой и встречный прямой правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-K02","text":"Прямой левой в туловище и прямой правой в голову; согнутая левая, уклон влево со встречным прямым правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-K03","text":"Прямой левой и боковой правой в голову; открытая правая перчатка и встречный прямой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-K04","text":"Прямой правой и боковой левой в голову; отклон назад с отбивом вправо и встречный прямой правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-K05","text":"Боковой левой в голову и снизу правой в туловище; согнутая правая, затем встречный прямой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-K06","text":"Боковые левой и правой в голову; встречный прямой правой в голову и нырок от левого.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-DOUBLE-4","title":"Двойной ответ на одиночную атаку","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Требует большей техники, устойчивого положения, быстроты ударов в открытые места.\nПравильный шаг назад и поступательное движение вперёд с двумя прямыми."],["Тактика","Два последующих контрудара часто приводят к сближению.\nСвоевременно отойти на дистанцию, чтобы, избежав удара, небольшим шагом вперёд нанести два удара, пока противник не собрался."],["Особенности выполнения","Удары очень быстро."]],"exercises":[{"id":"ROM-P2-D01","text":"Прямой левой в голову; открытая правая перчатка, затем два ответных прямых в голову, или боковые левой и правой, или прямой левой + боковой правой, или прямой правой + боковой левой; то же после подставки от прямого правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D02","text":"Прямой в голову; шаг назад, затем с движением вперёд два прямых ответных левой и правой, или прямой левой + боковой правой, или боковой левой + прямой правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D03","text":"Прямой правой в голову; шаг назад, вперёд прямой/боковой правой, затем прямой/боковой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D04","text":"Боковой левой в голову; согнутая правая; два ответных — боковой левой / короткий прямой / снизу, затем боковой правой, прямой или снизу в голову/туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D05","text":"Боковой левой в голову; шаг назад, затем вперёд два прямых или боковых в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D06","text":"Боковой правой в голову; согнутая левая или открытая перчатка, затем прямой/боковой/снизу правой, затем боковой или снизу левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D07","text":"Боковой левой в голову; шаг назад, вперёд прямой/боковой левой и прямой/боковой правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D08","text":"Боковой правой в голову; шаг назад, вперёд боковые правой и левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D09","text":"Прямой левой в голову; отбив правой влево, вправо или кверху, два ответных — прямой/боковой/снизу левой, затем прямой/боковой правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D10","text":"Прямой правой в голову; отбив левой влево, вправо или кверху, ответные прямой правой в туловище/голову или боковой правой, затем боковой левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D11","text":"Боковой левой в голову; нырок, затем боковой правой в голову и боковой/снизу левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D12","text":"Боковой правой в голову; нырок, затем боковые левой и правой в голову или снизу в голову и туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D13","text":"Снизу левой в голову/туловище; согнутая правая или открытая перчатка, ответные — короткий боковой, прямой или снизу левой и боковой правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-D14","text":"Снизу правой в голову/туловище; согнутая левая или открытая левая перчатка, ответные — короткий прямой/боковой/снизу правой, затем боковой/снизу левой. Вариант: шаг назад, затем с шагом вперёд два удара в разных сочетаниях.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-IM-05","text":"Задание тренера: от двух атакующих прямых в голову — шаг назад и ответ двумя последующими прямыми в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-DOUBLE-5","title":"Двойной встречный; двойной на двойной","review":false,"formats":["Бой с тенью","На мешке","Работа в паре"],"criteria":[["Тактика","Первый удар — встречный, второй — развитие встречной контратаки.\nАтакующий следит за точностью ударов, партнёр — за точностью и быстротой защит."],["Особенности выполнения","Сначала условно, потом по выбору — произвольно."]],"exercises":[{"id":"ROM-P2-V01","text":"От прямого левой — подставка открытой правой с одновременным выставлением левой руки вперёд и последующим боковым правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-V02","text":"А — прямой правой в голову; Б — уклон влево с одновременным встречным прямым правой и боковым левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-V03","text":"А — боковой правой в голову; Б — встречный прямой левой, затем боковой правой, прямой или снизу в голову и туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-V04","text":"А — снизу левой в туловище; Б — встречный прямой/боковой правой в голову с последующим боковым левой в голову или снизу в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-W01","text":"А атакует заранее условленными двойными; Б защищается руками, туловищем, передвижением и как можно быстрее наносит два ответных. Примеры: два боковых — подставки согнутыми руками, ответ боковой левой + снизу правой в туловище; прямой левой + боковой правой — подставка открытой правой, нырок от бокового, два боковых левой и правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L3-01","text":"А — два прямых в голову; Б — подставка правой и отбив левой вверх с ответным прямым правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L3-02","text":"А — прямой левой и боковой правой в голову; Б — подставка открытой правой, нырок от бокового правой с контрударами боковым правой в туловище и боковым левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L3-03","text":"А — боковой левой в голову и снизу правой в туловище; Б — встречный прямой правой в голову и боковой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L3-SH","text":"Передвижение по кругу приставным шагом, зигзагами, в разных направлениях со сменой боевых положений; два последующих удара в разных сочетаниях с движением вперёд, назад, в стороны; уклоны с контрударами; «бой с тенью» с заданием атаковать и контратаковать двумя последующими ударами из разных положений.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"","review":false},{"id":"ROM-L3-05","text":"Мешок и груша: два удара в голову и туловище в последовательности, указанной тренером (5 мин); скакалка (3 мин); произвольный «бой с тенью» (2 мин).","formats":["Бой с тенью","На мешке"],"labels":[],"needs":"","equipment":"мешок, груша, скакалка","review":false}]},{"id":"PRG-FAR-DOUBLE-B3","title":"Двойная контратака","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Конечное положение защиты — удобное для ответа в момент, когда партнёр раскрыт."]],"exercises":[{"id":"BUL-Y1-L14-01","text":"Контратака двойными: из положения защиты (конечное положение удобно для ответа); после ухода назад — двойной ответ («та же атака»); встречная начинается одновременно с защитой. В строю: атакующий перед шеренгой показывает удар — защита и контратака по команде; затем попарно и в условном бою. В перчатках: прямой левой — уход назад с подставкой плеча и ладони, ответный левой/правой; прямой левой — уход назад, двойной ответ левой–правой в голову (туловище).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-COUNTER-RETREAT","no":17,"title":"Встречные удары при отходе","task":"Встречные при отходе назад и в стороны, сохраняя дальнюю","programs":[{"id":"PRG-FAR-RETREAT-1","title":"Встречные при отходе","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Успешнее, если на удар левой отвечают правой и наоборот, по более короткому пути; прямым опережают боковые и снизу, боковым — боковые и снизу."],["Тактика","Не желая сближаться, останавливать движение противника вперёд, сохранять дальнюю."]],"exercises":[{"id":"ROM-P2-F01","text":"А — прямые левой и правой в голову; Б — отход назад или в стороны с подставкой открытой правой и выставлением левой вперёд.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-F02","text":"А — два боковых левой и правой в голову; Б — отход назад с опережающими: от бокового левой — прямой правой, от правой — прямой левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-F03","text":"А — прямой левой в голову/туловище и боковой правой в голову; Б — отход назад со встречными прямыми левой и правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-F04","text":"А — боковой левой в голову и снизу правой в туловище; Б — отход назад или в сторону со встречным прямым правой и прямым/боковым левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L3-04","text":"Условные бои для опережающих ударов при отходе назад и во встречном бою: на прямые — встречные прямые, на боковые — встречные прямые, на удары снизу — встречные прямые и боковые; особое внимание защитам.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-U04","text":"Атаки одним, двумя, тремя ударами, защиты и ответные (один или несколько в голову и туловище); затем встречные при отходе назад и в стороны.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-SERIES","no":18,"title":"Серии прямых","task":"Серии прямых: атака, защита от серии, контратака одиночными/двойными; по лапам","programs":[{"id":"PRG-FAR-SERIES-1","title":"Серии прямых: атака и защита","review":false,"formats":["На мешке","На лапах","Работа в паре"],"criteria":[["Техника","Непрерывность: каждый удар — исходное положение для следующего; с акцентом только удар, который наверняка попадёт, остальные легко — для раскрытия.\nЗащищаться не от каждого удара, а комбинированной защитой от всей серии.\nСохранять устойчивость, не «проваливаться»; первые удары легко, третий правой — с акцентом."],["Тактика","Обычно не более 2–3 ударов за ведущим; первый левой в голову (или туловище) — отвлечь от «раз-два».\nСторонник дальнего боя уходит назад или вправо и одновременно останавливает атаку прямым левой в голову.\nДезориентировать партнёра обманными движениями; изменять темп."],["Особенности выполнения","Без партнёра → мешок → лапы → условный бой."],["Типичные ошибки","Встречный обмен «удар за удар» — грубый способ, немедленно пресекать."]],"exercises":[{"id":"BUL-Y1-L15-01","text":"Серии прямых по воздуху на месте и в движении вперёд-назад, чередуя удары в голову и туловище; силу в серии — на мешке; технику серий — на лапах; тактику — в условном бою.","formats":["На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"нет; мешок; лапы","review":false},{"id":"BUL-Y1-L15-02","text":"Защита от серии в двух шеренгах и в условном бою: партнёр несильно, сначала медленно, затем быстрее; сначала договариваются, какие удары, сколько (3–4) и в каком порядке, позже без договорённости.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L15-03","text":"Серия левой–левой в голову–правой в туловище — подставка правой ладони и согнутой левой с уходом назад, ответный прямой правой в голову; прямой левой в голову — подставка левого плеча или отбив правой влево-вниз, двойные ответные правой–левой или левой–правой в голову; то же — уклон вправо, двойные встречные левой в туловище — правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L15-04","text":"Условный бой одиночными и двойными с защитами; обманные движения; после двух-трёх нарочито замедленных прямых очередной — очень быстро.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L16-01","text":"Серии прямых (первый удар в голову или туловище) и защиты от них в шеренге без перчаток; в перчатках: прямой в голову — уклон влево, встречный прямой правой в туловище; — уклон вправо или влево, встречный левой или правой в туловище; серия левой–левой–правой в голову — подставки правой ладони, левого плеча с уходом назад, ответный прямой правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L16-02","text":"Условный бой прямыми со всеми изученными защитами на дальней дистанции, 5 мин.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L17-01","text":"Атака двойными, сериями и защиты с одиночными контрударами (в шеренге без перчаток); в перчатках: одиночные прямые левой — произвольная защита, одиночные контрудары; повторный левой голова–туловище — подставка правой ладони и согнутой левой; серия левой(голова)–(туловище)–правой(голова) — подставки и левое плечо с уходом, ответный правой; двойной (из пройденного) — одиночные контрудары. Условный бой прямыми на дальней.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-SERIES-2","title":"Серии прямых по лапам и в условном бою","review":false,"formats":["На лапах","Работа в паре"],"criteria":[["Типичные ошибки","Тренер не должен двигать лапы навстречу удару — ложное представление о силе и точности, травма рук."]],"exercises":[{"id":"BUL-Y2-L02-01","text":"Атака серией прямых по перчаткам или лапам партнёра.","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"лапы/перчатки","review":false},{"id":"BUL-Y2-L02-02","text":"1-й атакует одиночными прямыми и сериями — 2-й защищается произвольно без контратаки; затем то же в соединении со встречными или ответными одиночными контрударами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-MT-08","text":"Вначале — проверка правильности ударных движений; позднее (подготовка к соревнованиям) — тактические задачи: чередовать удары в голову и туловище, готовить атаку ложными действиями, защита с контратакой.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы","review":false}]},{"id":"PRG-FAR-SERIES-O1","title":"Трёхударные серии прямых","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Опытные первый не доносят, второй проходит у лица; на втором подняться на правый носок и «обрушить» правую сверху вниз."],["Тактика","Пауза имеет значение: противник после первого пропущенного часто поднимает голову или замирает и получает «раз-два»; на средней паузы короче, в ближнем — самые короткие.\nЗащита: от левых — отходы назад и подставки правой ладони, от правой — подставка левого плеча с отклоном назад → контратака; варианты: шаг назад/шаг вправо с поворотом и серия с бокового левой; уклон вправо и правой снизу в туловище — боковой левой; на отходе — встречные прямые.\nЛучшая защита от правой в туловище — подставка левого локтя.\nАкцент, когда противник в профиль; защиты — поочерёдно подставки правой ладони, левого локтя, левого плеча.\nОслабить, «сбить» дыхание.\nЗащита: собранность, подставка левого локтя под левой в туловище и левого плеча под прямые в голову.\nНепривычна для защиты; выгодней у канатов; пауза после второго — противник раскрывается. Атакующая, ответная формы и при отступлении."],["Особенности выполнения","Серию нельзя применять шаблонно; каждый удар поражает определённую цель; приучать к ритму командой.\nЛегко разучивается в парах после усвоения «раз-два» и защит. Особая страховка левой при правой в туловище."]],"exercises":[{"id":"OGE66-F-SER3-01","text":"Серии под команду тренера с заданными паузами: «раз... раз-два» — пауза после первого, затем быстро два; «раз-раз-два» — равные паузы.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"OGE66-F-SER3-02","text":"Первый лёгкий левой на подскоке с весом на правой, второй левой и правая — под один шаг левой вперёд (вперёд-влево); вариант — с приставкой правой ноги.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-SER3-03","text":"Два прямых левой в голову (отвлечь, заставить поднять руки), без паузы акцентированный прямой правой в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"OGE66-F-SER3-04","text":"Две левые финтовые с весом на правой и небольшими шагами вперёд-влево; толчком правой акцентированный прямой правой в голову.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-SER3-05","text":"Первый «как в полную силу» с уклоном вправо, подчеркнутое выпрямление, второй финтовый на носках с задержкой приоткрытой перчатки у глаз; акцентированный правой в туловище; затем возможен правой снизу в голову.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-SER3-06","text":"Подчёркнутый левой в туловище с наклоном, пауза, быстро выпрямиться — левой-правой в голову; затем на секунду вытянуть левую и отклониться назад.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-SER3-07","text":"Варианты: левой в голову — правой в туловище — акцентированный левой в голову; левой-правой в туловище — акцентированный левой в голову; все три в голову с акцентом на третьем.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false}]},{"id":"PRG-FAR-SERIES-O2","title":"Четырёхударные серии прямых","review":false,"formats":[],"criteria":[["Тактика","Начинать в «опасной зоне» (70–80 см от канатов/угла) — противник отступает к канатам.\nЗащита: шаг назад и левый локоть; подставки левого плеча и правой ладони; левым локтем от правой в туловище; повтор другой серией вводит в заблуждение."],["Типичные ошибки","Не рассчитать продвижение — клинч, столкновение головами."]],"exercises":[{"id":"OGE66-F-SER4-01","text":"Финты левой; неожиданно левой-правой-левой-правой в голову с акцентом на последнем; каждый удар с продвижением одноимённой ногой.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-SER4-02","text":"Левой в голову с шагом — правой в туловище под приставку — левой в туловище — акцентированный правой в голову; вариант: три в голову — акцент правой в туловище, затем левая в голову и шаг правой назад.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-SER4-03","text":"Левой в туловище (отвлекающий) — укороченный акцентированный правой в голову — левой в голову (рука остаётся вытянутой, маскирует) — правой в туловище; вариант: левой в туловище — короткий правой в голову — левой в голову — акцентированный правой в голову.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false}]},{"id":"PRG-FAR-SERIES-ROM","title":"Общее занятие: атаки двумя и тремя ударами","review":false,"formats":["Работа в паре"],"criteria":[],"exercises":[{"id":"ROM-P2-U03","text":"В том же порядке — атаки двумя и тремя ударами: сначала прямые, затем с боковыми и снизу; защиты от двух и трёх ударов.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-STRAIGHT-BOUT","no":19,"title":"Бой прямыми: вольный и контрольный","task":"Вольный бой прямыми, контрольный бой, исправление ошибок, повторение после перерыва, смена партнёров","programs":[{"id":"PRG-FAR-STRAIGHT-BOUT-1","title":"Вольный и контрольный бой прямыми","review":false,"formats":["Бой с тенью","На мешке","Работа в паре"],"criteria":[["Тактика","Атаку готовить ложными действиями, основное внимание — своевременной защите.\nПодсчёт очков побуждает пользоваться финтами.\nПодбор партнёров разного роста, веса, стойки и тактики."],["Особенности выполнения","Только знакомые технические средства; разумно, корректно.\nУрок — повторение пройденного после летнего отдыха; восстановить пройденное, потом переходить к новому.\n2–3-й раунды с одними партнёрами, в 4–5-м партнёров заменить — прочнее закрепить приём в новых условиях; полезно анализировать, чем отличается один партнёр от другого."],["Типичные ошибки","Действовать вслепую и «напролом» — пресекать; сильный удар — штраф.\nСильный удар заставляет новичка напрягаться, действовать примитивно; бой переходит в драку — остановить, развести по углам на бой с тенью."]],"exercises":[{"id":"BUL-Y1-L18-01","text":"Урок вольного боя: разминка; борьба в стойке 1 раунд; бой с тенью 1 раунд; имитационный бой с партнёром (финты) 1 раунд; вольный бой 2 раунда; бой с тенью 1; приёмы в перчатках 4; снаряд 2; скакалка 1; набивной мяч.","formats":["Бой с тенью","На мешке","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L19-01","text":"Сдача нормативов: в двух шеренгах (одна атакует, напр. «прямой левой в голову с шагом», другая защищается) → в парах (атака/защита, затем смена) → 1 раунд произвольно одиночными и двойными. Подсчёт: удар без финта 1 очко, с финтом 2, защита 1, сильный удар −3; наблюдатели за каждым боксёром; оценка по пятибалльной.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L20-01","text":"После контрольного урока 1–2 занятия — исправление недостатков на дальней дистанции; общие и индивидуальные задания по усмотрению тренера.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L01-01","text":"1-й атакует одиночными прямыми левой или правой в голову — 2-й защищается произвольно с контратакой одиночными прямыми в туловище; то же с ударами и в голову; 1-й атакует прямым левой в голову — 2-й защищается произвольно с контратакой двойными прямыми.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L03-02","text":"2-й раунд: атака одиночными, двойными прямыми в голову; партнёр защищается произвольно и контратакует прямыми в туловище. 3-й — смена ролей; 4–5-й — то же с другим партнёром.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-MT-04","text":"Вольный бой без азарта; задания на листках, партнёр не знает задания другого; после раунда — разбор. 1-й год — все пары одновременно; 2-й год — на ринге после 1–2 раундов условного боя. Варианты партнёров: высокий/низкий, легче/тяжелее, левша, разные тактики.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-ROPES","no":20,"title":"Выход из угла и от канатов","task":"В строю, затем в парах по договорённости: защиты с уходом в сторону от прямых; на 2-м году — с новыми ударами; условный бой «угол/центр»","programs":[{"id":"PRG-FAR-ROPES-1","title":"Выход из угла против прямых","review":false,"formats":["Бой с тенью","Работа в паре"],"criteria":[["Техника","Для отхода на дальнюю чередовать защиту шагами вправо, влево и поворотами туловища с нырками, уклонами."],["Особенности выполнения","Начинать в подготовительной части в строю, затем в парах; вначале по договорённости; заучить 1–2 способа выхода."],["Типичные ошибки","Удар правой — легко и вначале небыстро."]],"exercises":[{"id":"BUL-Y1-L21-01","text":"Специальные упражнения в строю, затем в парах: один у канатов/в углу (или у стены), другой атакует по договорённости. Атака прямым левой в голову — отбив правой ладонью влево и уход вправо; — уклон влево или вправо с шагами в ту же сторону; одиночные атаки по договорённости — защиты с контратакой; атаки двойными — защита и контратака по договорённости.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L21-02","text":"Бой с тенью с акцентом на защиту уходами в стороны с поворотом (уклоном) туловища, 2×2 мин.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"","review":false},{"id":"BUL-Y1-L22-01","text":"Атака прямым правой в голову — защищающийся в углу/у каната: шаг левой вперёд-влево с уклоном влево и прикрытием головы правой; — шаг влево с отбивом левой и поворотом туловища вправо; атака правой с подготовкой ложными действиями левой — известные защиты и контратака прямым правой в туловище; атака двойными прямыми — произвольная защита и одиночные прямые контрудары.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-ROPES-2","title":"Выход из угла: уклоны со встречными; угол/центр","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Задание одного не должно быть известно партнёру — ближе к боевым условиям; задания на бумажках вручать перед боем, чтобы было время обдумать."]],"exercises":[{"id":"BUL-Y2-L16-01","text":"1-й атакует прямым левой в голову — 2-й уклоном вправо со встречными одиночными прямыми левой в голову или туловище; то же правой — уклоном влево со встречными прямыми правой; одиночные прямые произвольно — известные защиты с контрударами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L16-02","text":"1-й прямыми стремится отрезать путь партнёру, угрожая то левой, то правой, тесня к канатам и в угол, и внезапно атакует прямыми; 2-й прямыми стремится находиться в середине ринга, не отходить в угол и не прижиматься к канатам с помощью известных защит с контрударами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false}]}]},{"id":"FAR-SOUTHPAW","no":21,"title":"Бой с левшой","task":"Видоизменённая стойка в шеренге → защиты и контрудары → атака; не реже раза в неделю","programs":[{"id":"PRG-FAR-SOUTHPAW-1","title":"Против левши: защиты, контрудары, атака","review":false,"formats":["На лапах","Работа в паре"],"criteria":[["Техника","Стойку приблизить к прямой: туловище немного налево, правая рука ближе к цели."],["Тактика","Передвигаться влево; не атаковать коротким прямым левой; завязывать бой длинными прямыми левой; на правый прямой левши — отбив левой в правую сторону, затем правой в голову/туловище; перекрёстный (сверху) левой с шагом влево-вперёд против правого; помнить об ударе левой левши.\nЛевая рука левши выше и прикрывает голову и туловище от ударов справа; искать удобные исходные положения."],["Особенности выполнения","Шеренга (видоизменённая стойка) → защиты и контрудары → в перчатках двумя группами со сменой ролей; не реже раза в неделю.\nБоксёру в правосторонней стойке защищаться сложнее — приём вначале без контрудара."],["Типичные ошибки","Атаковать правой без подготовки отвлекающими действиями — встречный левой."]],"exercises":[{"id":"BUL-Y1-L23-01","text":"Удары в правосторонней стойке в шеренге и по перчаткам/лапам; атакующий в правосторонней, защищающийся в левосторонней: атака прямым правой в голову — шаг левой вперёд-влево и встречный прямой левой через правую руку; — отбив левой вправо и ответный прямой правой в голову; — уклон влево со встречным правой в голову (туловище). Затем роли меняются.","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки","review":false},{"id":"BUL-Y1-L24-01","text":"Атакующий в левосторонней, защищающийся в правосторонней: прямой левой в голову — защита без контрудара (произвольно или по заданию); то же с контратакой одиночными прямыми; атака двойными прямыми — то же. Условный бой с левшой прямыми на дальней (2×2).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-SOUTHPAW-2","title":"Против левши: совершенствование","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Левша в правосторонней теряется, если противник в аналогичной стойке; иногда давать обоим задание боксировать в правосторонней."],["Особенности выполнения","Методические указания — см. урок 23 1-го года."]],"exercises":[{"id":"BUL-Y2-L17-01","text":"Атакующий в правосторонней, атакуемый в левосторонней: совершенствование защиты от прямых в голову произвольно со встречными или ответными контрударами; затем защиты от произвольной атаки с контратаками. Вольный бой в левосторонней стойке (2×2).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-FEINT","no":22,"title":"Маневрирование и ложные действия","task":"Без партнёра (отдельные → комбинированные) → тень и имитационный бой → условный бой; на 2-м году — перед ударами снизу и боковыми","programs":[{"id":"PRG-FAR-FEINT-1","title":"Маневрирование и ложные шаги","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Маневрирование позволяет: подготавливать исходные положения перед атакой; сковывать противника у канатов или оттеснить в угол; создать перерыв для отдыха; занять дистанцию перед атакой; вызвать противника на атаку.\nНа дальней дистанции начать атаку труднее: неожиданно приблизиться на дистанцию удара, отвлекая ложными действиями — маневрированием, сменой дистанции."],["Особенности выполнения","Обучение маневрированию: без партнёра → с партнёром в шеренгах → в условных и вольных боях.\nУрок повторять на этапах прямых (1-й год) и апперкотов/боковых (2-й год)."]],"exercises":[{"id":"BUL-Y1-L25-01","text":"Специальные упражнения в маневрировании ложными действиями без ударов и с ударами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y1-L25-02","text":"1-й, маневрируя, выбирает момент и атакует одиночными (двойными, сериями) — 2-й защищается без контратаки; то же — 2-й с контратакой одиночными (двойными, серийными).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-SP-132","text":"Шаг вперед, шаг назад, шаг вперед с ударом (челночное движение).","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-133","text":"Шаг влево (вправо), шаг вперед с ударом.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-134","text":"Шаг влево (вправо), шаг вправо (влево) и шаг вперед с ударом.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-135","text":"Финт шагом вперед (вызов партнера на атаку одиночными ударами); от воображаемой атаки быстрый шаг назад или вправо (создавая себе исходное положе ние для контратаки).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-SP-136","text":"Финт шагом вперёд (вызов на атаку одиночными), от воображаемой атаки быстрый шаг назад или вправо и контратака по воображаемому противнику одиночными, двойными, серийными ударами.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-137","text":"Финт (вызов партнера на атаку двойными при мыми ударами, левой — правой в голову); от воображай мой атаки шаг назад с подставкой правой ладони от пер вого удара и левого плеча (или бокового шага влево) от второго удара.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-SP-138","text":"Финт (вызов на атаку двойными прямыми левой — правой в голову); от воображаемой атаки шаг назад с подставкой правой ладони от первого и левого плеча (или боковым шагом влево) от второго удара; затем контратака по воображаемому противнику.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-FAR-FEINT-2","title":"Ложные удары и финт взглядом","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Ложный удар — вялый, умышленно не доведённый до конца; первый удар наносить легко или не доводить до цели."],["Тактика","Обманы: ввести в заблуждение, отвлечь, замаскировать намерения, усыпить бдительность, вызвать на атаку/контратаку; ложные удары — для раскрытия защиты."],["Особенности выполнения","Применяется в сочетании с ложными ударами; у новичков на первых уроках малоубедителен, но знакомить необходимо."]],"exercises":[{"id":"BUL-Y1-L26-01","text":"Специальные упражнения в овладении ложными ударами: в одношереножном строю — ложный удар в туловище и основной в голову или наоборот.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y1-L26-03","text":"1-й наносит ложные и действительные удары в разной последовательности: голова—туловище, туловище—голова, голова—голова; 2-й защищается известными защитами без контрудара. Затем: при реакции на финт — атакует; 2-й страхуется от ложных, от действительных — уход назад с ответной контратакой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L26-04","text":"Ложный удар левой в туловище сопровождать взглядом, снова демонстративно нацелиться взглядом в туловище, а левой неожиданно ударить в голову; или фиксировать взгляд на голове и, когда противник защитит её, ударить в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-SP-127","text":"Ложный удар в голову — действительный удар в голову.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-128","text":"Финт в голову — удар в туловище.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-129","text":"Финт в туловище — удар в голову.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-130","text":"Финт левой — удар правой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-131","text":"Финт правой — удар левой.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-FAR-FEINT-3","title":"Ложные уклоны и нырки","review":false,"formats":["Бой с тенью","Работа в паре"],"criteria":[],"exercises":[{"id":"BUL-SP-139","text":"Уклон влево с небольшим шагом вперед-влево. Затем возвращение в боевую стойку. После ряда повто рений удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-140","text":"Уклон вправо с небольшим шагом вперёд-вправо, затем возвращение в боевую стойку; после ряда повторений — удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-141","text":"Уклоны то влево, то вправо. В момент второго или третьего уклона удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-142","text":"Уклоны то влево, то вправо, сочетаемые с ложными ударами; в момент второго или третьего уклона — удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-143","text":"Нырок влево с небольшим шагом вперед-влево, затем возвращение в боевую стойку. После ряда повто рений удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-144","text":"Нырок вправо с небольшим шагом вперёд-вправо, затем возвращение в боевую стойку; после ряда повторений — удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-145","text":"Нырок то влево, то вправо. Во время второго или третьего нырка удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-SP-146","text":"Нырки то влево, то вправо, чередуемые с уклонами влево, вправо и ложными ударами; во время второго или третьего нырка — удар.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y1-L29-01","text":"Бой с тенью в парах на финты, 2×2 мин.","formats":["Бой с тенью","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y1-L30-01","text":"Имитационный бой с партнёром без ударов (упражнения в финтах), 1 раунд.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y1-L30-02","text":"Бой с тенью с акцентом на защиты нырком и боковыми шагами, 1 раунд.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"","review":false}]},{"id":"PRG-FAR-FEINT-4","title":"Финты в тени, у зеркала, на снарядах, имитационный бой","review":false,"formats":["Бой с тенью","Перед зеркалом","На мешке","Работа в паре"],"criteria":[["Особенности выполнения","В перчатках, чтобы подготовить организм к нагрузкам после одевания перчаток."]],"exercises":[{"id":"BUL-SP-147","text":"Самостоятельное применение разнообразных ложных действий при изучении прямых ударов, ударов снизу, боковых ударов.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"зеркало","review":false},{"id":"BUL-SP-148","text":"Бой с тенью: самостоятельное применение разнообразных ложных действий перед сочетаниями ударов.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"зеркало","review":false},{"id":"BUL-SP-149","text":"Отработка различных финтов перед заркалом.","formats":["Бой с тенью","Перед зеркалом"],"labels":[],"needs":"","equipment":"зеркало","review":false},{"id":"BUL-SP-150","text":"Совершенствование финтов при нанесении пря мых ударов, ударов снизу, боковых ударов.","formats":["На мешке"],"labels":[],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-SP-151","text":"На снарядах: совершенствование финтов перед сочетаниями ударов.","formats":["На мешке"],"labels":[],"needs":"","equipment":"снаряды","review":false},{"id":"BUL-Y2-L03-01","text":"1-й раунд — имитационный бой с партнёром без ударов для совершенствования финтов.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L16-03","text":"Имитационный бой с партнёром без ударов (упражнения в финтах), 1 раунд.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-MT-06","text":"Бой с тенью или с воображаемым противником для изучения и совершенствования технических и тактических действий (методика — в уроках).","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"","review":false},{"id":"BUL-Y1-L18-02","text":"Имитационный бой с партнёром — упражнения в финтах, 1 раунд.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-FEINT-5","title":"Финты перед прямыми","review":false,"formats":["Бой с тенью","Работа в паре"],"criteria":[["Особенности выполнения","Два первых раунда — ложные действия; задание партнёра не известно; на следующих уроках задания меняются; тренер ведёт учёт заданий."]],"exercises":[{"id":"BUL-Y2-L18-01","text":"Повторение без партнёра: атака шагом вперёд, контратака шагом назад, финты отклонами, боковыми шагами и т. д.; ложные действия с последующими прямыми; бой с тенью и имитационный бой с партнёром без ударов — разнообразные ложные действия перед прямыми.","formats":["Бой с тенью","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L18-02","text":"1-й, защищаясь и наблюдая, наносит ложные прямые левой или правой в голову (привлечь внимание к защите головы), а когда партнёр теряет бдительность, — удары в туловище; 2-й, защищаясь, применяет прямые левой произвольно, стремясь определить основной атакующий удар партнёра.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L18-03","text":"1-й атакует прямым левой или правой в голову и защищается от контратаки; 2-й защищается произвольно, создавая удобные исходные положения для ответной контратаки одиночными в нужный момент; затем — излюбленные двойные прямые, защита и контратака по договорённости.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-UPPER","no":23,"title":"Одиночные удары снизу","task":"Сначала одиночные снизу и защиты без контрударов; затем как контрудар; атаки снизу с дальней — позже","programs":[{"id":"PRG-FAR-UPPER-1","title":"Удар снизу и защита","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","При атаке снизу боксёр открывается для встречных — поэтому сначала как контрудар."],["Особенности выполнения","Порядок по этапам."]],"exercises":[{"id":"ROM-P1-SN01","text":"Одиночные удары снизу и защиты от них без контрударов (первый этап); затем удары снизу как контратакующие; позднее — атаки снизу с дальней дистанции.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-MECH-UPPER-B1","title":"Удар снизу из учебной стойки","review":false,"formats":[],"criteria":[["Техника","При ударе снизу рука движется в вертикальной плоскости или под углом к ней; кулак тыльной частью к партнёру вниз или в сторону. Кулак описывает дугу снизу—вперёд—вверх; туловище поворачивается слева направо (для правой — справа налево)."],["Особенности выполнения","Вначале несколько занятий — коротким ударам, затем длинному (с разгибанием в локте).\nЕсли темп мешает освоить технику — выполнять спокойнее; добиваться координации рук и ног."]],"exercises":[{"id":"BUL-Y2-L01-02","text":"В одношереножном строю по команде тренера — короткие удары снизу без разгибания руки в локте: по воздуху, затем по собственной ладони. Одна рука полусогнута у подбородка ладонью вниз, другая наносит удар снизу с поворотом туловища.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y2-L02-03","text":"Удар снизу в шеренге с разгибанием в локте (длинный): по воздуху на месте, затем по ладони, далее по воздуху с шагами в стороны.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-FAR-UPPER-B1","title":"Снизу левой в голову","review":false,"formats":["Бой с тенью","На мешке","Работа в паре"],"criteria":[["Техника","Длинный: расслабляя и опуская левое плечо, шаг вперёд, поворот туловища слева направо с разгибанием в пояснице, левая рука вперёд-вверх с разгибанием в локте, кулак тыльной частью в сторону; правая страхует голову и туловище. Короткий: без шага, толчком правой вес на полусогнутую левую, которую в момент удара выпрямить; туловище резко выпрямить и немного повернуть направо; предплечье вертикально, кулак пальцами к себе, полукруговым движением снизу вверх; ладонь прикрывает подбородок, локоть — правую сторону туловища.\nПодставка левой: левая рука вправо-вниз, ладонь под удар. Подставка правой: правая рука вправо, ладонь под удар, слегка отклоняясь назад. Уклон назад: не опуская рук, отклонить туловище назад, страховать голову ладонью, правую ногу немного сместить назад, не опускаясь на пятку (левая на месте)."],["Тактика","Применение: атакующий, когда противник в собранной стойке или наклоняется вперёд; второй удар в атаках с дальней; контрудар в сочетании с защитами на дальней; на средней и ближней для развития атаки/контратаки. Первым — если противник в низкой стойке; действенное средство против защиты уклоном вправо. На этапе дальнего боя в атаке — только с разгибанием в локте; без разгибания — как встречный и ответный."],["Особенности выполнения","Вначале из боевой стойки без шага, затем с шагом вперёд; далее — с партнёром в перчатках → бой с тенью → снаряды (подвесная груша с песком). Вначале легко; скорость нарастает к цели, акцент в конце; не напрягаться.\nС уклоном назад новички встречаются впервые.\nВторое упражнение — поочерёдно, остальные — по раундам."],["Типичные ошибки","Замах перед ударом; недостаточное разгибание туловища и ног."]],"exercises":[{"id":"BUL-Y2-L04-01","text":"Объяснение и показ в целом и по элементам: 1) перенос веса на левую ногу с незначительным сгибанием в колене; 2) выпрямление левой ноги с поворотом туловища направо; 3) движение руки снизу к цели и положение кулака; 4) правая рука на страховке; 5) движение левой ноги при ударе с шагом. Упражнения в одной шеренге без перчаток.","formats":["Бой с тенью","На мешке","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L04-02","text":"Подставка правой и левой ладоней, уклон назад; упражнения без перчаток в защите с контрударами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L04-03","text":"Таблица: атака ударом снизу левой в голову — защита подставкой левой (правой) ладони, уклоном назад с подставкой ладоней; атака прямым или ударом снизу (разгибая руку) левой в голову — то же с уходом назад; атака прямым левой в голову — отбив правой влево, уход назад — ответный удар снизу левой в голову — защита подставкой правой, уходом назад; то же — ответный удар снизу или прямой левой — защита произвольная.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L04-04","text":"Обоим разрешено наносить прямые левой; один дополнительно может применить удар снизу левой в голову или правой в туловище, находя удобные моменты.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L04-05","text":"Контрудары снизу левой в голову (на прямой левой в голову) — на средней и ближней дистанциях, если противник в низкой стойке; часто в многоударных сериях.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-UPPER-B2","title":"Снизу левой в туловище","review":false,"formats":["Работа в паре"],"criteria":[["Техника","С разгибанием, с шагом: расслабляя и опуская левое плечо, шаг вперёд, поворот туловища направо с разгибанием в пояснице, левая рука вперёд с разгибанием в локте после опоры левой ногой, кулак тыльной частью в сторону; правая предохраняет голову и туловище; левая нога разгибается в колене и тазобедренном. Согнутой рукой — на более близкой дистанции, кулак тыльной частью к партнёру.\nПовернуть туловище налево и подставить согнутую в локте правую руку, слегка прижатую к туловищу; подставка левой ладони — как от удара в голову, но перчатку останавливать ниже."],["Тактика","Особенно эффективен, когда противник во фронтальной стойке или наносит прямые в голову."],["Особенности выполнения","Новичкам на дальней легче сначала удар с разгибанием руки в локте.\nЗащита на дальней и средней нетрудна, но требует большого внимания и чёткости движений."],["Типичные ошибки","Излишне выпрямляет туловище; недостаточно поворачивает таз и левое бедро направо."]],"exercises":[{"id":"BUL-Y2-L05-01","text":"Объяснение и показ в целом и по элементам (перенос веса на левую со сгибанием в колене; выпрямление левой с поворотом туловища направо; движение руки к цели и положение кулака; правая на страховке; движение левой ноги при ударе с шагом). Упражнения в одной шеренге без перчаток.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y2-L05-02","text":"Подставка согнутой в локте правой руки; подставка левой (правой) ладони; упражнения без перчаток в защите с контрударами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L05-03","text":"Атака ударом снизу левой в туловище — подставка левой (правой) ладони, согнутой правой руки; атака прямым или ударом снизу (разгибая) левой в голову (туловище) — то же — ответный удар снизу левой в голову (туловище) — подставка ладони с уходом назад; серия прямой левой — правой — снизу левой (все в голову) — подставка правой ладони, левого плеча, правой ладони с уходом назад — ответный прямой правой в голову — подставка левого плеча и правой ладони с уходом назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L05-04","text":"На прямые левой или правой в голову: 1) ответный после отбива правой ладонью влево; 2) ответный (разгибая руку) после отбива тыльной стороной правой перчатки вправо; 3) ответный после ухода назад с отбивом правой ладонью влево.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-UPPER-B3","title":"Снизу правой в голову","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Без шага: вес на левую, туловище налево и резко выпрямить, правое плечо сильно вперёд, рука снизу не разгибаясь, предплечье вертикально вверх, кулак тыльной стороной книзу; полусогнутую левую энергично выпрямить в колене и голеностопе; левая ладонью защищает голову, локтем — левую сторону туловища. С разгибанием: толчок правой, вес на вышагивающую левую, левую выпрямить, правую подтянуть; правая тыльной частью в сторону вниз и вперёд-вверх.\nЧаще подставка ладоней левой или правой; правую руку вперёд и немного влево, напрягая в момент касания; уместен шаг назад."],["Тактика","С дальней дистанции в атаке — только если противник наклоняется вперёд; для первого удара непригоден; вторым или в серии, где первые удары отвлекают. После удара снизу правой заканчивать атаку ударом левой в голову.\nКонтрудары снизу правой в голову на прямой левой: ответный после отбива левой ладонью вправо; ответный после ухода назад с отбивом левой вправо."],["Особенности выполнения","В первоначальном обучении удары снизу правой доступнее в контратаке; учить при активном противодействии партнёра левой рукой.\nЗащита проста: стойка с приподнятым левым плечом и правой ладонью у головы создаёт удобное защитное положение.\nТребовать чаще применять удары снизу в условном бою."],["Типичные ошибки","Скован; отводит руку назад; поднимает подбородок; недостаточно разгибает ноги и туловище."]],"exercises":[{"id":"BUL-Y2-L06-01","text":"Объяснение и показ в целом и по элементам (вес на левую с незначительным сгибанием; выпрямление левой с поворотом налево; движение руки снизу вверх и положение кулака; левая на страховке; движение левой при ударе с шагом). Упражнения без перчаток в одной шеренге.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L06-02","text":"Подставка правой ладони; уход назад в сочетании с подставкой; упражнения без перчаток с контрударами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L06-03","text":"Атака снизу правой в голову — подставка правой ладони с уходом назад; атака прямым левой в голову — уход назад с отбивом левой вправо — ответный снизу правой в голову — уход назад с подставкой правой ладони; двойной прямой левой—правой в голову — подставка правой ладони и левого плеча с уходом назад — ответный прямой или снизу правой в голову — подставка левого плеча, правой ладони с уходом назад; двойной левой снизу — правой в голову — подставка правой ладони с уходом назад — произвольная.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L06-04","text":"Условный бой одиночными прямыми и ударами снизу и двойными из сочетаний прямых и ударов снизу, со всеми пройденными защитами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-UPPER-B4","title":"Снизу правой в туловище","review":false,"formats":["Работа в паре"],"criteria":[["Техника","С разгибанием: расслабляя и опуская правое плечо, шаг вперёд с поворотом туловища налево, правая вниз и вперёд до цели, кулак тыльной частью в сторону; после опоры левой разгибать правую в локте; левая предохраняет голову и туловище. Без разгибания — как снизу правой в голову, но с меньшего расстояния, кулак тыльной стороной к противнику.\nПодставка правой ладони: правую руку вниз и влево, напрягая при касании. Подставка левого предплечья/согнутой левой: слегка отклонить туловище назад, опустить предплечье и остановить удар."],["Тактика","Удобен высоким; против низкой боевой стойки, во встречной и ответной контратаках. Чаще на близком расстоянии, но многие применяют и на дальней, выпрямляя руку."],["Особенности выполнения","Удар с разгибанием изучать вместе с другими ударами дальнего боя.\nЦель — учить действовать при активном противодействии партнёра левой рукой; чаще применять удары снизу в условном бою."],["Типичные ошибки","Недостаточно поворачивает таз налево; не разгибает ног в коленях; поднимает подбородок."]],"exercises":[{"id":"BUL-Y2-L07-01","text":"Объяснение и показ в целом и по элементам (вес на левую; выпрямление левой с поворотом налево; движение руки по наклонной к цели и положение кулака; левая на страховке; движение левой с шагом). Упражнения без перчаток в одной шеренге.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y2-L07-02","text":"Подставка согнутой левой руки, правой ладони, уходы в сочетании с подставкой; упражнения без перчаток с контрударами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L07-03","text":"Атака снизу правой в туловище — подставка согнутой левой, правой ладони с уходом назад; атака прямым левой в голову — уход назад с отбивом левой вправо — ответный снизу правой в голову (туловище) — уход назад с подставкой правой ладони; то же на прямой левой или правой; одиночные, двойные прямые и снизу произвольно — произвольная защита и ответные прямые/снизу.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L07-04","text":"Условный бой одиночными, двойными ударами (прямыми, снизу) с пройденными защитами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-UPPER-B5","title":"Двойные и серии с ударами снизу; контроль","review":false,"formats":["Работа в паре"],"criteria":[],"exercises":[{"id":"BUL-Y2-L08-01","text":"Таблица: одиночные прямые и снизу левой в голову (туловище) — произвольная защита; двойной прямой левой в голову — снизу правой в туловище — подставка правой ладони и согнутой левой с уходом назад — ответные одиночные прямые/снизу правой в голову (туловище) — произвольная; серия прямой левой — левой в голову — правой снизу в туловище — то же; серия прямых левой—правой—левой—правой (все в голову) — подставка правой ладони и левого плеча с уходом назад. Сначала без перчаток, затем в перчатках.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L09-01","text":"Контрольные упражнения в перчатках в двухшереножном строю и в парах на ринге; тренер оценивает по пятибалльной системе количество и технику нанесённых ударов снизу; наблюдатели ведут счёт ударов в раунде.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-FEINT-6","title":"Финты перед ударами снизу","review":false,"formats":["Бой с тенью","Работа в паре"],"criteria":[["Особенности выполнения","Требовать разумных ложных действий, позволяющих нанести удар снизу.\nПартнёр стремится разрушить подготовку атаки ударами левой; если атаки не удаются — партнёру применять лишь защиты, иногда напоминая ударом левой о защите."]],"exercises":[{"id":"BUL-Y2-L19-01","text":"Без партнёра: после отдельных упражнений — комбинированные ложные действия: имитировать то уклон влево с небольшим шагом вперёд-влево, то уклон назад с подставкой правой ладони (от воображаемых прямых левой), после ряда повторений — удар снизу в голову или туловище. Бой с тенью, имитационный бой.","formats":["Бой с тенью","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L19-02","text":"1-й, маневрируя, наносит ложные прямые левой, выбирает момент для двойной атаки: прямой левой в голову — снизу правой в туловище (или прямой правой в голову); 2-й, страхуясь от ложных и применяя произвольно прямой левой, следит за началом действительной атаки и применяет комбинированную защиту; затем — с ответной контратакой длинным снизу правой в туловище или прямым правой в голову; затем произвольно по договорённости.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-HOOK","no":24,"title":"Одиночные боковые: атака/защита, ответные, встречные","task":"Боковые в голову и туловище; подставки и шаг назад; ответные; встречные; нырки","programs":[{"id":"PRG-FAR-HOOK-1","title":"Боковой и защита","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Атака боковым с дальней требует сокращения дистанции, подготовки и выбора момента; противник может опередить встречным прямым."],["Типичные ошибки","Ошибка в расчёте дистанции при боковом: промах → потеря равновесия; чрезмерное сокращение → запрещённый удар/по затылку.\nНедостаточный заворот кулака — удар запрещённой частью перчатки."]],"exercises":[{"id":"ROM-P1-B01","text":"А — боковой левой в голову; Б — подставка согнутой правой руки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-B02","text":"А — боковой правой в голову; Б — подставка согнутой левой руки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-B03","text":"А — боковой левой (правой) в голову; Б — шаг назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-B04","text":"А — боковой левой в туловище; Б — подставка согнутой правой руки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-B05","text":"А — боковой левой в туловище; Б — шаг назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-IM-02","text":"Если при боковом правой в голову кулак недостаточно заворачивается (удар запрещённой частью) — наносить этот удар много раз с разных дистанций и из разных положений.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-HOOK-2","title":"Ответные на боковые","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Ответная контратака."]],"exercises":[{"id":"ROM-P1-BC01","text":"А — боковой левой в голову; Б — подставка согнутой правой и ответный прямой, боковой или снизу левой в голову (туловище).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-BC02","text":"А — боковой правой в голову; Б — подставка согнутой левой и ответные: прямой/снизу правой в голову и туловище или боковой правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-BC03","text":"А — боковой правой в голову; Б — подставка левого плеча и ответные одиночные правой: прямые, боковые, снизу в голову и туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-BC04","text":"А — боковой левой (правой) в голову; Б — шаг назад и ответный прямой или боковой правой (левой) в голову или туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-L2-04","text":"А — боковой левой в голову; Б — подставка согнутой правой и ответный прямой или боковой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-HOOK-3","title":"Встречные на боковые и нырки","review":false,"formats":["Работа в паре"],"criteria":[["Техника","При нырке обе руки свободны."],["Тактика","Встречная форма; после освоения ответных.\nКороткий прямой опережает боковой.\nШирокие возможности для контратак."],["Особенности выполнения","Порядок: ответные правой → встречные левой → комбинации."]],"exercises":[{"id":"ROM-P1-BC06","text":"А — боковой левой в голову; Б — подставка правой согнутой руки и встречные прямой, боковой или снизу левой в голову или туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-BC07","text":"А — боковой правой в голову; Б — подставка согнутой левой и встречные прямой, боковой или снизу правой в голову или туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-BC08","text":"А — боковой левой в голову; Б — встречный прямой правой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-BC09","text":"А — боковой правой в голову; Б — встречный прямой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-BC10","text":"А — боковой левой в туловище; Б — встречный прямой правой в голову или встречный боковой левой с подставкой правой руки. (Также от боковых в голову — подставка тыльной стороны перчатки.)","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P1-NY01","text":"Нырок от бокового левой в голову: сначала ответные правой, затем встречные левой, затем комбинации встречных и ответных в голову и туловище; аналогично от правого бокового.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-MECH-HOOK-B1","title":"Боковой из учебной стойки","review":false,"formats":[],"criteria":[["Техника","Положение кулака: пальцы вниз, пальцы внутрь или вполоборота к полу (среднее); наиболее удобно среднее — позволяет перейти к удобному для себя."],["Особенности выполнения","Сначала движения коротких боковых; правильное положение руки и кулака. Об особенностях боковых на этом уроке не рассказывать."],["Типичные ошибки","Пальцами внутрь — излишнее напряжение предплечья и удары внутренней стороной перчатки; пальцами вниз — сила на слабую часть кулака; отведение руки назад для замаха; опуская локти — удар внутренней стороной перчатки, запрещённый правилами."]],"exercises":[{"id":"BUL-Y2-L08-02","text":"Короткие боковые удары под прямым углом из учебной стойки; у стены спиной (не касаться локтем стены, без замаха); по собственной ладони вытянутой полусогнутой руки на высоте подбородка с поворотом туловища.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"нет (стена)","review":false}]},{"id":"PRG-MECH-HOOK-O1","title":"Боковой левой с дальней дистанции","review":false,"formats":[],"criteria":[["Техника","Кулак пальцами к себе сжимается; правая ладонь страхует голову, локоть — туловище; левый локоть на уровне плеча.\nТуловище в пояснице не разгибается, рука выпрямлена больше, кулак сильно согнут в лучезапястном, шаг правой вперёд-вправо длиннее."],["Тактика","Попадание в печень — опускание рук, возможность двух боковых правой-левой в голову в ближнем бою."],["Особенности выполнения","Очень сильный, требует точной координации; обычно опытные и физически сильные."]],"exercises":[{"id":"OGE66-F-HK-01","text":"Толчком правой, незначительный шаг левой с вращением справа налево — вес полностью на левую; толчком левой резкий бросок тела вперёд с выпрямлением и вращением слева направо, шаг правой вперёд — боковой левой.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-F-HK-02","text":"Из того же исходного положения толчком левой послать тело вперёд с поворотом слева направо — боковой левой в туловище.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false}]},{"id":"PRG-FAR-HOOK-B1","title":"Боковой левой в голову","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Длинный с шагом: толчком правой вес на вышагивающую вперёд-влево левую; левая по дуге снизу вверх и далее горизонтально к цели; туловище слева направо; правая предохраняет голову и туловище. Короткий: шаг левой вперёд, но несколько влево; согнутой левой без замаха с поворотом направо полукругом снизу вверх и по горизонтали; кулак в среднем положении.\nТыльная сторона правой перчатки: незначительно отвести правую вперёд-вправо (как бы отдавая честь), напрячь при касании. Предплечье: приподнять согнутую правую, остановить удар средней частью предплечья. Также: правую вправо и остановить ладонью, или уклон назад, не опуская правой, вес на правую ногу."],["Тактика","Боковые на всех дистанциях; короткие и длинные; на дальней угол разгибания больше. Длинным атакующим боковым правой не атаковать — длинный путь, намерения видны. Короткие боковые с дальней — в серии не первым или как контрудары. Боковой левой: начинать атаку с дальней, как ложный для подготовки атаки, заканчивать атаку; реже — ответный/встречный. Часто сочетают с прямым левой в голову и туловище; хорош как повторный.\nДвойной левой: если от первого удара партнёр защитится подставкой правой ладони с уходом назад, его «достают» вторым боковым со вторым небольшим шагом вперёд-влево."],["Особенности выполнения","Встречные боковые новичку трудны — требуют мастерства; ответные усваиваются быстро."],["Типичные ошибки","Излишне резко поворачивает туловище направо; теряет равновесие; очень большой замах. Удар внутренней стороной перчатки — устранять с первых занятий."]],"exercises":[{"id":"BUL-Y2-L10-01","text":"Объяснение и показ на месте и с шагом в целом и по элементам: 1) перенос веса на правую ногу; 2) поворот туловища направо; 3) движение согнутой руки вправо-вперёд к цели и положение кулака; 4) правая на страховке; 5) движение левой ноги влево-вперёд (по диагонали) для удара с шагом. Упражнения в шеренге без перчаток.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y2-L10-02","text":"Подставка тыльной стороны правой кисти (перчатки); правого предплечья; упражнения без перчаток.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L10-03","text":"Встречные и ответные боковые контрудары левой после защиты подставкой. На прямой левой в голову: 1) ответный после уклона назад; 2) ответный после шага назад; 3) ответный после шага назад с подставкой правой ладони или отбивом правым предплечьем вправо-вверх и уклоном влево; 4) встречный с подставкой тыльной стороны правой кисти или предплечья.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L10-04","text":"Атака боковым левой в голову — подставка тыльной стороны правой кисти или правого предплечья (поочерёдно); то же — ответный (встречный) боковой левой в голову — подставка; атака прямым или боковым левой в голову — отбив правой ладонью влево, подставка предплечья/кисти с уклоном влево; двойной прямой левой — боковой левой в голову — подставка правой ладони, тыльной стороны правой кисти.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L10-05","text":"Условный бой прямыми (любыми) и боковым левой в голову с изученными защитами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-HOOK-B2","title":"Нырок от бокового левой; серия с боковым","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Небольшой уклон влево (по ходу удара), затем туловище по дуге вниз-вправо-вверх, сгибая и разгибая ноги; перед нырком — низкая боевая стойка; ноги слегка согнуты, подбородок опущен, плечи сведены, руки защищают голову и туловище; после прохода удара — слева направо и вверх, вес на правую."],["Тактика","Наиболее надёжна: руки свободны для контрударов, противник теряет равновесие и тратит силы."],["Особенности выполнения","Сначала восстановить нырок от прямых, затем от боковых; повторять на каждом уроке; с партнёром и без; контроль у стены."]],"exercises":[{"id":"BUL-Y2-L11-01","text":"Упражнения в серии из двух прямых в голову (левой — правой) и бокового левой в голову.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y2-L11-02","text":"Объяснение и показ защиты нырком от бокового левой в голову; упражнения в защите нырком от бокового левой и от серии ударов.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L11-03","text":"Атака боковым левой в голову — нырок вправо (поочерёдно); прямой (боковой) левой — то же — ответный прямой правой в голову — подставка левого плеча, правой ладони; прямой левой — уклон влево — ответный боковой левой в голову — подставка правого предплечья или кисти; серия прямых левой—правой—боковой левой (все в голову) — подставка правой ладони, левого плеча, тыльной стороны правой кисти с уходом назад — ответный боковой или снизу левой в голову — уход назад. Упражнения в боковых и прямых контрударах после подставки, уклона, нырка.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-HOOK-B3","title":"Боковой левой в туловище","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Наносят теми же способами, что и в голову, но больше наклоняют туловище вправо; начиная удар, наклонить туловище не к противнику, а несколько влево — устраняет замах.\nПодставка согнутой правой: принять удар у локтевого сгиба, слегка прижать руку к туловищу, повернуть туловище налево; подставка левой ладони: левую вправо-вниз, напрячь при касании; уход назад — как от других ударов."],["Тактика","На всех дистанциях; легко сочетать с прямым левой в голову — для подготовки атак: отвлекающий прямой (боковой) левой в голову, затем действительный боковой в туловище; и как отвлекающий перед ударом в голову; встречный/ответный."],["Особенности выполнения","Атакующий защищает подбородок правой ладонью от контратаки.\nЧисло защит ограничено; простая надёжная — подставка согнутой правой."],["Типичные ошибки","Опасное движение головой; излишне приседает; не страхуется; недостаточно поворачивает туловище и таз направо."]],"exercises":[{"id":"BUL-Y2-L12-01","text":"Объяснение и показ в целом и по элементам (вес на правую; поворот направо; движение согнутой руки к цели; движение левой ноги влево-вперёд при ударе с шагом). Упражнения в боковом и двойном (прямой левой в туловище — боковой левой в голову) в шеренге без перчаток.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y2-L12-02","text":"Подставка согнутой правой руки с уходом назад; от двойного — подставка согнутой левой и правого предплечья; упражнения без перчаток; контрудары после защиты от двойных в шеренге.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L12-03","text":"Боковой левой в туловище — подставка согнутой правой, уход назад с подставкой левой ладони (поочерёдно); двойной прямой левой в туловище — боковой левой в голову — подставка согнутой левой, правого предплечья — ответный прямой (снизу или боковой) левой в голову; двойной прямой левой в голову — боковой левой в туловище — подставка правой и левой ладони с уходом назад — то же; прямой (снизу) или боковой правой в голову — боковой левой (оба в голову) — уход назад — двойной ответный прямой — подставка левого плеча с уходом назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-HOOK-B4","title":"Боковой правой в голову","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Вес на правую; шаг вперёд с поворотом налево, рука резко по дуге справа налево к цели, левая страхует голову и туловище; в конце сместить правую к левой до положения боевой стойки, сохраняя устойчивость."],["Тактика","Обычно им не атакуют даже опытные; лучше как встречный или ответный; атаковать — после отвлечения ударами левой и отвлекающими действиями; удары правой в атаке первыми не наносят."],["Особенности выполнения","Внимание на быстроту, точность, внезапность, страховку от встречных; без замаха, с защитой подбородка левой. Усваивается быстрее других — следить, чтобы не злоупотребляли и не били в полную силу в вольном бою.\nНа первом этапе — подставка и уход, затем сочетания защиты с контратакой."]],"exercises":[{"id":"BUL-Y2-L13-01","text":"Объяснение и показ в целом и по элементам (вес на левую; поворот налево; движение согнутой руки влево-вперёд и положение кулака; левая на страховке; движение левой при ударе с шагом). В шеренге без перчаток — на месте, затем с шагом.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y2-L13-02","text":"Подставка левого плеча и правой ладони (комбинированная) — на месте и с уходами в стороны; с уклоном вправо; уходом назад. Без перчаток в шеренге: по команде повернуться направо, приподнять левое плечо, отклониться вправо-назад, закрыв правой рукой голову и туловище; затем добавить небольшой шаг назад; затем в парах в перчатках.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L13-03","text":"Боковой правой в голову — подставка левого плеча (поочерёдно); двойной прямой левой — прямой правой (оба в голову) — то же и подставка правой ладони — ответный боковой (прямой) правой в голову — подставка левого плеча с уходом назад; прямой или боковой левой в голову — произвольная — ответные/встречные боковые левой; двойной прямой левой—правой в голову — подставка правой ладони и левого плеча — прямой правой в голову, боковой левой в туловище (голову) — подставка левого плеча, согнутой правой с уходом назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-HOOK-B5","title":"Боковой правой в туловище; серии; контроль","review":false,"formats":["Работа в паре"],"criteria":[["Техника","С шагом: поворот налево, удар по дуге влево-вниз, левая предохраняет голову и туловище; после опоры левой подтянуть правую вперёд-вправо, повернув налево, пяткой слегка наружу.\nПодставить согнутую левую, слегка прижав локоть к левому боку; немного повернуться направо; нетрудно защититься шагом назад."],["Тактика","Не атакующий; в основном короткий контрудар с защитой от ударов правой или удар в серии на ближней и средней."],["Особенности выполнения","Новички изучают только две защиты: подставку согнутой левой и уход назад; остальные — при изучении ближнего боя.\nНаносить серии не спеша, думая, как точнее выполнить и защищаться; тренер запрещает беспорядочный обмен ударами."],["Типичные ошибки","Небрежно направленный удар — повреждение кисти о локоть, удар в спину."]],"exercises":[{"id":"BUL-Y2-L14-01","text":"Объяснение и показ в целом и по элементам; в одной шеренге без перчаток, затем в перчатках в двух шеренгах и в парах, произвольно перемещающихся по залу.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L14-02","text":"Подставка согнутой левой; подставка правой ладони на месте и с уходом в стороны; упражнения без перчаток с контрударом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L14-03","text":"Боковой правой в туловище — подставка согнутой левой, правой ладони, уход назад (поочерёдно); прямой левой в голову — подставка левого плеча (отбив левой ладонью вправо) — ответный боковой правой в голову — уход назад с подставкой левого плеча; двойной прямой левой в туловище — боковой правой в голову — подставка согнутой левой, левого плеча с уходом назад — двойной ответный прямой (боковой) правой — прямой левой в голову; серии из пройденного — произвольно.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L15-01","text":"Каждая пара по очереди боксирует 2 раунда по 2 мин перед просмотром после самостоятельной разминки; затем совершенствование в перчатках с теми же партнёрами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-FEINT-7","title":"Финты перед боковыми","review":false,"formats":["Бой с тенью","Работа в паре"],"criteria":[["Особенности выполнения","Комбинированные ложные действия — основные упражнения при совершенствовании боковых ударов и защит от них."]],"exercises":[{"id":"BUL-Y2-L12-04","text":"Условный бой прямыми и боковыми левой на дальней со всеми изученными защитами; чаще применять финты: финт прямым левой в голову — по реакции партнёра прямой правой в туловище или боковой левой в туловище или голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L20-01","text":"Без партнёра: упражнения с одноимённым шагом и нырком влево — чаще; при ложном нырке вправо — забегание мелкими шагами вправо; комбинированные ложные действия: то нырок, то уклон влево, вправо, с мелкими передвижениями и забеганиями во всех направлениях; в строю — имитация «глухой» защиты (предплечье у груди) или двойной локтевой.","formats":["Бой с тенью","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L20-02","text":"1-й, маневрируя на дальней с ложными (прямым, снизу) левой, выбирает момент для атаки длинным боковым левой; 2-й, страхуясь и применяя произвольно прямой левой в атаке и контратаке, следит за действительным ударом, защищаясь подставкой или нырком; затем — с защитой от контратаки / контратакой боковым левой в голову (туловище); затем двойные (прямые со снизу) или излюбленные боковые — по договорённости.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-COUNTER-O2","title":"Встречные боковые и снизу на дальней","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Кулак пальцами к себе, согнут в лучезапястном."]],"exercises":[{"id":"OGE66-F-CTR-03","text":"С весом на левую: шаг вперёд-влево, поворот на носке — боковой левой в голову (локоть на уровне плеча или выше); в туловище — короткий, пятка к противнику, правой перчаткой отвести удар вправо. С весом на правую: шаг правой вперёд-вправо, поворот слева направо — боковой левой в голову / туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-CTR-04","text":"В туловище: шаг левой, пятка слегка к противнику, вес на левую, резкий поворот слева направо, пальцы вверх. В голову: шаг левой с наклоном, таз вперёд, выпрямить ноги и спину, рывок левым плечом вверх; правой перчаткой отвести бьющую руку вправо.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-F-CTR-07","text":"На боковой левой в голову: шаг левой, поворот на носке слева направо — боковой левой. На прямой левой: шаг левой, поворот бедра и туловища — снизу левой в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-TACTICS","no":25,"title":"Разведка и бой с разными противниками","task":"Задания на разведку (сначала несложные); партнёры разного роста и манеры; самостоятельные задания","programs":[{"id":"PRG-FAR-TACTICS-1","title":"Разведка в условном бою","review":false,"formats":["Бой с тенью","Работа в паре"],"criteria":[["Тактика","Тактическая подготовка: разведывать боевые средства противника; анализировать его действия; создавать обманными действиями обстановку для атаки; контратаковать, используя мнимое раскрытие (вызов на удар).\nФинтами, ложными раскрытиями выявить излюбленные удары, защиты, атаки и контратаки партнёра."],["Особенности выполнения","Вначале задания несложные; лучше, если партнёр не знает о задании; после раунда доклад тренеру о наблюдениях и контрдействиях."]],"exercises":[{"id":"BUL-Y1-L25-03","text":"Атакует и контратакует прямыми с заданием найти уязвимые места в защите партнёра; партнёр ведёт бой прямыми с заданием разгадать маневр и после боя дать характеристику.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L26-05","text":"Атакует и контратакует прямыми; ложные — в голову, действительные — в туловище. Партнёр ведёт бой прямыми с заданием узнать излюбленные удары и защиты партнёра.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L13-04","text":"Условный бой на дальней прямыми, снизу и боковым левой со всеми защитами. 1-й раунд: одному — выявить способы защиты партнёра, другому — типичные отвлекающие удары перед атакой; 2-й раунд — задачи наоборот; в перерыве — доклад тренеру.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L14-04","text":"Условный бой прямыми, снизу и боковыми со всеми защитами; 1-й раунд: один находит уязвимые места партнёра, второй — излюбленные действия партнёра в атаке; после боя рассказать о наблюдениях и что предприняли.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L21-01","text":"Бой с тенью: ложные атаки и ложные открытия — вызов воображаемого противника на атаку; ложные действия с последующими одиночными, двойными, серийными ударами.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"","review":false},{"id":"BUL-Y2-L21-02","text":"1-й маневрирует, применяет ложные прямые левой (ложные снизу или боковые) в голову или туловище и, выбирая момент, атакует — 2-й защищается без контратаки; то же с защитой от контратаки / с контратакой; 1-й маневрирует, применяет ложные удары, раскрытия, вызывая партнёра на атаку, защищается и контратакует — 2-й страхуется от ложных и выбирает момент для атаки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L21-03","text":"Примерные задания (для двух боксёров): как реагирует партнёр на финты / какие защиты от прямых (снизу, боковых); какие удары чаще пропускает / какие ложные действия перед атакой; характерные способы атаки / излюбленные удары; атака или контратака / какие контрудары и когда; что представляет собой партнёр и как действовать против его тактики / оценить силы, технику, манеру боя.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-TACTICS-2","title":"Противники разного роста и манеры","review":false,"formats":["Бой с тенью","Работа в паре"],"criteria":[["Тактика","Боксёр должен проверить, как ему удаётся вести бой с высоким, низким, равным по росту, с левшой, с ведущим прорывную атаку или выжидающим."],["Особенности выполнения","К упражнениям по технике тренер может добавить задание по тактике: какие ложные действия партнёр применяет перед атакой, какие прорехи в его атаках."]],"exercises":[{"id":"BUL-Y2-L22-01","text":"Бой с тенью с превышающим в росте воображаемым противником; имитационный бой с партнёром (без перчаток / в перчатках).","formats":["Бой с тенью","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-Y2-L22-02","text":"1-й применяет одиночные прямые с маневрированием и ложными действиями — 2-й, наблюдая и защищаясь, выбирает момент и неожиданно атакует двойными; затем 1-й с ложными левой и правой атакует двойными в любом сочетании — 2-й, защищаясь, контратакует одиночными или двойными.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L22-03","text":"Выше ростом атакует одиночными и двойными, не подпуская партнёра, защищаясь отходами назад и боковыми шагами; ниже ростом, финтуя и маневрируя, прижимает партнёра к канатам (ограничив маневр) и стремительно атакует.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false},{"id":"BUL-Y2-L22-04","text":"Задания: наступательный бой с активным сближением, удобное исходное положение и быстрая атака — против маневрирующего, избегающего ударов и сближения, после каждой атаки уходящего на дальнюю; неожиданная стремительная атака из маневрирования (в основном боковыми) — против разнообразных защит со встречными прямыми и ударами во время отходов; бой прямыми с дальней с быстрым возвратом — против оттесняющего к канатам и в угол со стремительной атакой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false}]},{"id":"PRG-FAR-TACTICS-3","title":"Самостоятельные и волевые задания","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Решительность — внезапный переход от защиты к контратаке; самообладание — сдерживаться от неорганизованных атак, наблюдать за руками, туловищем, ногами партнёра, комбинированные защиты, следить за дистанцией."],["Особенности выполнения","Разбирая действия, тренер иногда важнее подчеркнуть даже небольшую удачу, а не только критиковать ошибки."],["Типичные ошибки","Зажмуривать глаза, поворачиваться спиной, уходить назад вместо ответных и встречных; подбирать слабых партнёров."]],"exercises":[{"id":"BUL-Y2-L05-05","text":"По своему усмотрению совершенствовать пройденное; перед боем объяснить тренеру, какие приёмы хотят совершенствовать, после боя — как удалось осуществить задуманное.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-VOL-01","text":"Условный бой с заданиями: атаковать партнёра разными способами с финтами; развивать атаки сериями; быстрый и внезапный переход от защиты к контратаке или выбор между двумя вариантами атаки; встречные удары; внезапный выход из углов ринга; один партнёр отвечает одним прямым левой на атаку сериями прямых.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"FAR-SPEED","no":26,"title":"Быстрота реакции","task":"На знакомом, хорошо усвоенном материале: реакция без перчаток → в перчатках на дистанции → бой с тенью","programs":[{"id":"PRG-FAR-SPEED-1","title":"Реакция без перчаток (тренер/пары)","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Упражнения 152, 153, 154, 155 могут выполняться в парах (шеренгах). Для этого боксерам следует располо житься в парах на дистанции 3—4 шага друг от друга. Один из них вначале выполняет роль тренера, другой ученика, а затем наоборот. Если обучаемый не правильно выполнил то или иное действие, боксер обя зан указать партнеру на его ошибки."]],"exercises":[{"id":"BUL-SP-152","text":"Упражнения для развития быстроты и точности защитной реакции на атаку противника; тренер или бок сер, стоя перед группой, имитирует нанесение тех или иных ударов, а обучаемые избирательно защищаются. Например: а) тренер атакует прямым ударом левой в голову, обучаемые применяют защиту подставкой правой ладони; уклоном вправо и т. д.; б) тренер атаку ет прямым левой —прямым правой в голову; обучаемые защищаются подставкой правой ладони, подставкой ле вого плеча в сочетании с уходом назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-SP-153","text":"Упражнения для развития умения быстро пере ходить в контратаку (ответную или встречную); тренер имитирует атаку, зани мающиеся применяют защиту и контратаку ют, нанося удары по воздуху. Например: а) тренер атакует пря мым ударом левой в го лову, обучаемые защи щаются отбивом пра вой рукой влево с от","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-SP-154","text":"Упражнения для развития быстроты движения при атаке: тренер, стоя перед группой в положении бое вой стойки, внезапно раскрывает отдельные части тела или ставит ладони в различные положения, как мишени.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"BUL-SP-155","text":"Упражнения для разви тия быстроты и точности за щитной реакции от контруда ров; тренер, так же как и в пре дыдущем упражнении, подает сигнал для атаки, на который ученики реагируют одиночным ударом. Тренер, защищаясь от атаки, произвольно имитирует Рпс. 41. Упражнения в нанесение ответного контруда контрударах ра. Группа обучаемых защи щается.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false}]},{"id":"PRG-FAR-SPEED-2","title":"Реакция в перчатках на дистанции","review":false,"formats":["На мешке","Работа в паре"],"criteria":[["Особенности выполнения","Подбирать партнёров: один легче или быстрее и подвижнее; урок повторять не раз.\nСнаряды легче обычного; скакалка — больше оборотов; темп всех упражнений высокий."]],"exercises":[{"id":"BUL-SP-156","text":"Упражнения для развития быстроты и точности реакции на внезапно появляющуюся цель (раскрытие противника). В парах на дальней дистанции один из боксеров (по договоренности), маневрируя, изменяя дистанции, вне запно раскрывает перчатки, ставя их на том или ином уровне тела и в различном положении: фронтально — для прямых ударов; горизонтально — для ударов снизу или, повернув перчатки в сторону, — для боковых ударов. Другой стремится мгновенно нанести удар.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-SP-157","text":"Как №156 (в парах на дальней один, маневрируя, внезапно раскрывает перчатки как цель), но, показав раскрытую перчатку, мгновенно убирает её в момент удара; атакующий, чтобы попасть, должен применять обманные движения.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-SP-158","text":"Упражнения с партнером в условном бою для развития быстроты реакции ври защите: а) односторон ней (один боксер атакует, другой защищается с макси мальной быстротой); б) двусторонней (оба партнера произвольно применяют приемы атаки и защиты, огра ниченные точным заданием).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-SP-159","text":"Упражнения с партнером в условном бою для развития быстроты реакции при контратаке; применяют ся те же упражнения (см. упражнения 157, 158), однако защиту объединяют с контратакой (встречной или от ветной).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L27-03","text":"1-й атакует определённым ударом (по усмотрению тренера или партнёра) — 2-й защищается и отвечает встречным или ответным контрударом; то же двойными (серийными).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y1-L27-04","text":"Условный (вольный) бой с заданием действовать возможно быстрее, 2×2 мин.","formats":["На мешке","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-MT-05","text":"Спарринг в затруднённых условиях: на ринге трое, двое против одного — для реакции на боковые атаки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-SPEED-3","title":"Быстрота: тень, лапы, ловкость","review":false,"formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"criteria":[["Особенности выполнения","Атака из удобного исходного положения со страховкой и возвращением в стойку немедленно после удара.\nУпражнения строятся на знакомом, хорошо усвоенном материале; тренер вправе требовать непринуждённого и быстрого выполнения.\nФинты, удары после нырков и боковых шагов связаны со специальной ловкостью.\nПроверка разнообразия защит и контрударов; в 1-м раунде тренер следит за одним боксёром, после смены ролей — за другим."]],"exercises":[{"id":"BUL-SP-160","text":"Передвигаясь во всех направлениях, боксер изби рательно атакует или контратакует прямым ударом ле вой (правой) в голову (туловище). Атака проводится из удобного исходного положения с применением страховки и удара и возвращением в стойку немедленно после нане сения удара.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"","review":false},{"id":"BUL-SP-161","text":"Бой с тенью: передвигаясь во всех направлениях, боксёр атакует или контратакует двойными (серийными) ударами.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"","review":false},{"id":"BUL-SP-162","text":"Боксер применяет различные подготовительные действия (маневрирование, ложные удары и т. д.) перед атакой одиночными (двойными, серийными) ударами.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"","review":false},{"id":"BUL-Y1-L27-01","text":"Упражнения для быстроты: атака двойными; защита от одиночных и контратака двойными; атака серией; защита от серии и контратака одиночными.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-Y1-L27-02","text":"Упражнения в перчатках для быстроты приёмов атаки двойными и сериями по перчаткам или лапам партнёра.","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"лапы/перчатки","review":false},{"id":"BUL-Y1-L26-02","text":"Совершенствование атакующих ударов (одиночных, двойных, серийных) по лапам (перчаткам) партнёра.","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"лапы/перчатки","review":false},{"id":"BUL-Y1-L29-02","text":"Контрудары, сочетаемые с защитами нырком и боковыми шагами с поворотом туловища от прямых в голову, по перчаткам или лапам партнёра.","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"лапы/перчатки","review":false},{"id":"BUL-Y1-L29-03","text":"1-й атакует прямым левой в голову (туловище) — 2-й применяет все виды защиты без контратаки; затем то же со встречными или ответными одиночными контрударами (любыми).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-IM-08","text":"Удары и защиты одиночно и слитно, «бой с тенью» — с максимальной быстротой при правильной технике; быстрота ударов на мешке, грушах, лапах, в паре.","formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"мешок, груши","review":false}]}]},{"id":"FAR-COMPETE","no":27,"title":"Подготовка к соревнованиям","task":"Только изученный материал; атака двумя ударами, бой на ринге поочерёдно; снижение нагрузки перед стартом; разбор; сила и специальная выносливость","programs":[{"id":"PRG-FAR-COMPETE-1","title":"Предсоревновательные уроки и разбор","review":false,"formats":["Бой с тенью","Работа в паре"],"criteria":[["Особенности выполнения","Перед соревнованием совершенствовать не новый материал, а изученный. Задания соответствуют возможностям новичка; только после усвоения приёма — к новым.\nВ последнем уроке нагрузка снижается; урок короче; время в перчатках сокращается.\nОтмечать недостатки и положительные стороны; поощрять искусно боксировавших даже при проигрыше."]],"exercises":[{"id":"BUL-Y2-L23-01","text":"Совершенствование в атаке двумя любыми ударами и защит от них с контрударами; условный бой по индивидуальным заданиям; вольный бой 2×2; бой на ринге по очереди парами («поточный» способ).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false},{"id":"BUL-Y2-L24-01","text":"Любая атака одного, защита и контратака другого — 10 мин; произвольные действия левой рукой — 5 мин; бой с тенью 2×2.","formats":["Бой с тенью","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"BUL-Y2-L25-01","text":"Разбор боёв; упражнения в перчатках по индивидуальным заданиям; бой с тенью 2×2.","formats":["Бой с тенью"],"labels":[],"needs":"","equipment":"перчатки","review":false}]},{"id":"PRG-FAR-COMPETE-2","title":"Сила и специальная выносливость","review":false,"formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"criteria":[["Техника","Удары из боевой стойки без замахов, свободная рука страхует.\nДыхание ровное, акцентированные удары с выдохом."],["Тактика","Ложные движения перед ударом — внезапность; быстрый атакующий шаг — навык сближения."],["Особенности выполнения","Гантели: лёгким весам — до 1 кг, тяжёлым — до 2 кг. Упражнения в перчатках — скоростно-силовые, перчатки — отягощение.\nБыстрый, но доступный темп без чрезмерного утомления; периодически повторять на 2-м году.\nДистанцию постепенно увеличивают; учитывать возможности новичков.\nПосле механики и лап."],["Типичные ошибки","Резкие шумные выдохи при каждом ударе утомляют.\nРазвивать силу удара сильными мышечными напряжениями в паре с партнёром ни в коем случае нельзя."]],"exercises":[{"id":"BUL-Y2-L26-01","text":"1-й наносит одиночные (двойные, серийные) атакующие удары по лапам (перчаткам) партнёра — 2-й держит лапы и контролирует движения; затем контратакующие удары по лапам. Бой с тенью с гантелями 2 раунда.","formats":["Бой с тенью","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"лапы; гантели до 1–2 кг","review":false},{"id":"BUL-Y2-L28-01","text":"Двойные и серии по перчаткам или лапам партнёра — 20 мин; защита от атаки серией (атакуемый избирательно наносит ответные одиночные контрудары) — 10 мин; условный бой 2×3; вольный бой; бой с тенью; снаряды 2×3.","formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"лапы/перчатки","review":false},{"id":"BUL-Y2-L29-01","text":"Бег по раундам: 500 м за 2 мин, 550 м за 2 мин, 600 м за 2 мин; между раундами шагом; после каждых 100–150 м — рывки 10–15 м или быстрые серии ударов в движении вперёд.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"BUL-MT-07","text":"Снаряды после вольного или условного боя; руки забинтованы; все удары из стойки без замахов, страхуясь свободной рукой; чаще уклоны во все стороны; атаку с дальней — с максимально быстрым атакующим шагом; удары после ложных движений быстро и точно.","formats":["На мешке"],"labels":[],"needs":"","equipment":"снаряды, бинты, снарядные перчатки","review":false},{"id":"ROM-MECH-APP","text":"Совершенствование техники ударов на мешке, груше, настенной подушке, мяче на резине.","formats":["На мешке"],"labels":[],"needs":"","equipment":"мешок, груша, настенная подушка, мяч на резине","review":false},{"id":"ROM-IM-09","text":"После боевой практики (например, 3 раунда по 3 минуты) — небольшой перерыв и ещё один-два плотных раунда на снарядах.","formats":["На мешке"],"labels":[],"needs":"","equipment":"снаряды","review":false},{"id":"ROM-PH-01","text":"Основные упражнения для силы удара — на мешке. Силу также развивают: борьба с партнёром, штанга небольшого веса (жим, толчок, рывок), повороты туловища сидя/лёжа, гимнастические снаряды, грузы на блоках; для кистей и предплечий — накручивание ворота с грузом, гантели, набивные мячи, булавы.","formats":["На мешке","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"мешок; штанга, гантели, набивные мячи, булавы, ворот с грузом","review":false}]},{"id":"PRG-FAR-COMPETE-ROM","title":"Предсоревновательные занятия, вольный бой, сбор","review":false,"formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"criteria":[["Тактика","Менять тактику: пропустив 2–3 раза боковой правой — повысить бдительность и не давать его провести; проигрывая в ближнем — подвижнее, на дальней и средней."],["Особенности выполнения","Только после хорошо усвоенных технических действий. Подбор партнёров: несколько слабее для уверенности, периодически равный/сильнее.\nЗа две недели до состязаний 2–3 раза за 10 дней; один партнёр на все раунды; можно на 1–2 раунда больше соревновательных, но не удлинять раунды.\nДля зрелых, постоянно тренирующихся боксёров.\nОбщие задания для всех: прямой левой из всех положений, активные защиты на средней и ближней, ближний бой. Перчатки не тяжелее 10–12 унций.\nОбязательно маски и капы; перчатки большего размера."],["Типичные ошибки","Останавливать при грубом ведении, опасности потери равновесия, силовом характере боя.\nУдлинение раундов нарушает чувство времени; частая смена партнёров не даёт провести планы.\nСильные удары в боевой практике ограничивают мастерство и создают боязнь удара; злоупотребляющего силой — снимать с ринга."]],"exercises":[{"id":"ROM-SP-02","text":"Вольный бой только попарно на ринге, строго дозируется по времени; тренер не вмешивается, подсказки — в минутном перерыве.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-PC-01","text":"Разминка; уклоны, повороты, подъёмы ног, приседания 7–10 мин; плечевой пояс 3–5 мин; «бой с тенью» по заданию тренера 2–3 мин; лёгкий бой с партнёром на дальней с обозначением ударов 3 мин; вольный бой на ринге; через 5 мин — снаряды в повышенном темпе 1–2 раунда; отдельные элементы техники.","formats":["Бой с тенью","На мешке","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-IM-10","text":"Предсоревновательный период: три тура по три раунда — 3 раунда отдельных приёмов в высоком темпе с минутным перерывом; через 3–5 мин вольный бой 3×3 мин; небольшой отдых; 1 раунд снаряды в высоком темпе, 1 раунд скакалка, 1 раунд «бой с тенью» или лапы.","formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"снаряды, скакалка, лапы","review":false},{"id":"ROM-CMP-01","text":"Вводная часть: борьба, скакалка, «бой с тенью», темповые упражнения с мячами — раундами по 3 мин с минутным перерывом (25–30 мин). Основная: в парах по индивидуальному плану, вначале медленно с остановками и поправками, раунды по 5–6 мин; в каждом раунде условия для одного из боксёров; 4–6 раундов с минутным перерывом; затем произвольный 3-раундовый бой лёгкими быстрыми ударами. Заключительная: лапа ≤5 мин, мешок 1–2 раунда, скакалка 3–5 мин.","formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки","review":false},{"id":"ROM-CMP-02","text":"Тренер в больших перчатках (14–15 унций) 15–20 мин: вызывает на атаку прямым и наносит лёгкие встречные прямые, заставляя бить с небольшим уклоном; при слабой защите от боковых — бьёт боковые, боксёр защищается нырками/подставками и бьёт контрудары по подставленным перчаткам.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-CMP-03","text":"Трёхраундный бой по процедуре соревнований с судьёй; задача — выиграть по очкам лёгкими ударами, оставаться неуязвимым; затем мешок и груши 3 раунда по 3 мин.","formats":["На мешке","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]}]},{"id":"S3","title":"Средняя дистанция","stages":[{"id":"MID-POSITION","no":28,"title":"Позиция и передвижение на средней","task":"Позиция средней дистанции при сближении; шаги во всех направлениях","programs":[{"id":"PRG-MID-POS-O1","title":"Позиция и шаги на средней","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Туловище выпрямлено, слегка вперёд; плечи выдвинуты, подбородок на груди; руки согнуты под острым углом, сведены и прижаты; кулаки у подбородка; вес равномерно на слегка согнутых ногах; таз назад.\nПередвижение с носка и на всю ступню."],["Тактика","Средняя — длина вытянутой руки, «дистанция сферы удара»; основная или переходная в ближнюю/дальнюю; долго не задерживаются.\nДругие способы передвижения (как на дальней) невозможны — противник воспользуется дистанцией; отступая, наносить встречные прямые, сохраняя среднюю — вырабатывается терпеливой тренировкой."],["Типичные ошибки","При сближении атаковать из позиции дальнего боя — правая нога сзади тормозит удар правой, нет резкости."]],"exercises":[{"id":"OGE66-M-POS-01","text":"Принять позицию средней дистанции при сближении (одновременно изменив положение ног, рук, туловища).","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-M-MOV-01","text":"Шаги вперёд, назад, влево, вправо и промежуточные — с носка на всю ступню; сохранять среднюю дистанцию; при отходе противника двигаться за ним шагами той же величины.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-MID-DIST-ROM","title":"Чувство дистанции с партнёром","review":false,"formats":["Работа в паре"],"criteria":[],"exercises":[{"id":"ROM-HR-01","text":"Упражнения с партнёром для чувства дистанции (хлопки по ладоням); борьба с захватом шеи, нырками и лёгкими толчками; перебрасывание малых мячей с передвижением в боевой позиции.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"малые мячи","review":false}]},{"id":"PRG-TR-FM-R1","title":"Ответ после защиты от атаки с дальней — развитие на средней","review":true,"formats":["Работа в паре"],"criteria":[["Техника","Своевременно принимать соответствующую позицию (исходное положение ног, рук и туловища) на вновь образовавшейся средней дистанции боя."],["Тактика","Выбор дистанции ближней или средней после защиты уклоном влево зависит от задуманных действий боксера, его возможностей и способностей, а также тактических соображений."],["Особенности выполнения","Действия боксера после защиты уклоном должны быть всегда заранее тщательно подготовлены на тренировке."],["Типичные ошибки","При сближении они начинают атаковать противника обеими руками, находясь в прежней позиции дальнего боя."]],"exercises":[{"id":"OGE66-F-DEF-01","text":"Шаг назад со страховкой правой; шаг вправо (толчок левой, правая тыльной стороной у подбородка) — ответные прямые; шаг влево (толчок правой, левая ладонь страхует, поворот справа налево) — ответный прямой левой; назад-вправо; назад-влево со сменой позиции на правостороннюю.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":true},{"id":"OGE66-F-DEF-03","text":"Толчком левой отклонить тело назад с весом на правую, подставить правую ладонь; как только удар коснётся ладони — оттолкнуться правой и ответить прямым левой; развить серией прямых на средней.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":true},{"id":"OGE66-F-DEF-04","text":"От прямого правой или левой в голову в конце движения: левое плечо под удар, правая ладонь страхует подбородок, поворот слева направо, вес на правую; ответный прямой правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":true},{"id":"OGE66-F-DEF-06","text":"Уклон вправо: небольшой шаг навстречу, уклон вперёд-вправо ≈45°, руки прижаты, голова у левого плеча, правая подтянута. Уклон влево: толчком правой незначительный шаг левой, поворот справа налево ≈45° — ответные снизу в туловище, прямой снизу в голову, боковой левой на средней/ближней, серия.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":true}]}]},{"id":"MID-SHORT","no":29,"title":"Короткие удары на средней","task":"Попеременно короткие прямые, боковые, снизу: один атакует, второй защищается и отвечает; затем с подходом на среднюю","programs":[{"id":"PRG-MID-SHORT-1","title":"Атака-защита-ответ короткими","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Найти дистанцию для коротких ударов, не подходить вплотную, удобное защитное положение головы и туловища."],["Тактика","Страховать себя защитами, быть готовым к ответным/встречным."],["Особенности выполнения","Удары сначала задаёт тренер, потом по выбору."]],"exercises":[{"id":"ROM-P2-U05","text":"В собранном положении на дистанции коротких ударов попеременно: один наносит короткие прямые, боковые, снизу в голову и туловище, второй только защищается, после окончания атаки отвечает тем же. Затем — с маневрированием и подходом на среднюю; второй не отходит, принимает бой защитами руками и туловищем.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-MID-SERIES-1","title":"Механика серий","review":false,"formats":[],"criteria":[["Техника","Устойчивое положение на обеих ногах; вес может незначительно перемещаться с лёгкими поворотами туловища и бёдер или находиться на одной ноге."],["Тактика","Подготавливают к сложным формам боя на средней и ближней дистанциях."],["Особенности выполнения","Начинать только после овладения одиночными и двойными ударами и защитами от них."]],"exercises":[{"id":"ROM-MECH-SER","text":"Механика серий из трёх и более ударов в устойчивом положении на обеих ногах, с движением вперёд, в стороны и назад и положением тела для страховки.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-MID-SERIES-O1","title":"Серии прямых без шага на средней (три случая)","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Основное — страховка свободной рукой и максимальная собранность; недооценка страховки при акцентированном ударе может привести к нокауту."],["Тактика","Три случая: противник стоит или прижат к канатам; отступает; атакует серией — прямые контрудары при отходе. Боковые и снизу на средней — с небольшими шагами и развиваются прямыми.\nБоковые и снизу со средней — с небольшими шагами вперёд/вперёд-влево/вперёд-вправо."]],"exercises":[{"id":"OGE66-M-SER-01","text":"Серии прямых в голову и туловище без шага: левой в голову (отвлечь) — правой в туловище (акцент) — левой в туловище — правой в голову (акцент).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-K-MID-02","text":"Серии прямых в голову и туловище: 1) противник стоит или прижат к канатам; 2) при его отступлении; 3) контрударами с отходом на его серию прямых. Атаку начинать, когда противник в 70–80 см от канатов; прижав, не отпускать; отход с выбрасыванием левой руки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false}]}]},{"id":"MID-ATTACK-POS","no":30,"title":"Исходные положения для атаки на средней","task":"Атаки из фронтального приседа и приседа с поворотом (прямые снизу в голову, снизу в туловище); боковой «скачковый» левой","programs":[{"id":"PRG-MID-IP-O1","title":"Атака из приседа: прямые снизу в голову, снизу в туловище","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Толчок носка левой ноги, выпрямление ног и поворот туловища слева направо — одним слитным движением; для удара правой толчковая нога — правая."],["Тактика","Положение позволяет легко сменить исходное положение для атаки другим ударом или защиты.\nПрямой снизу левой неожидан из непривычного положения; снизу правой выгоден против правостороннего противника."]],"exercises":[{"id":"OGE66-M-IP-01","text":"Из фронтального приседа — защита от прямых, боковых, коротких прямых; прямой снизу левой и правой в голову с шагами во всех направлениях.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-M-IP-02","text":"Присед, повёрнутый справа налево — прямой снизу левой в голову с шагом вперёд или вперёд-вправо (вес на правую): толчок левой, выпрямление ног, поворот слева направо слитно. Повёрнутый слева направо — прямой снизу правой в голову с шагом вперёд/вперёд-влево; из приседа — также удары снизу в туловище и голову; после приседания — боковые с шагом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-MID-IP-O2","title":"Боковой «скачковый» удар левой в голову","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Рука к цели свободна, слегка разогнута; в момент удара сгибается в локте и запястье, резко напрягается, кулак крепко сжат; после удара подбородок под левым плечом."],["Тактика","Готовить ложным прямым/боковым правой в туловище — противник наклоняется и опускает руки; лучшая защита — нырок. Финтовые удары снизу нецелесообразны — встречный прямой."]],"exercises":[{"id":"OGE66-M-IP-04","text":"Шаг левой вперёд с бóльшим приседом на левую; резким толчком левой скачок вперёд с вращением слева направо, приземление на согнутую правую; сразу боковой левой, затем опустить левую ногу; вес на правую, правая страхует.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"MID-DEFENSE","no":31,"title":"Защиты на средней","task":"Защиты ногами, руками, уклоны, наклоны, нырок, отклоны, приседание, комбинированная; затем ответная контратака из положений уклона, отклона, наклона","programs":[{"id":"PRG-MID-DEF-O1","title":"Защиты ногами, руками, уклонами","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Выгоднее против малоподвижных, медлительных, с плохой реакцией. Шаг назад — защититься, вызвать противника на движение вперёд и встретить, изменить его план, утомить.\nОтбив левой внутрь — ответный прямой правой; отбив правой наружу — прямой левой снизу; вниз — высоким; снизу вверх — низкорослым против высоких. На средней руками защищаются реже — освобождают для атаки.\nНаклоны особенно успешны на средней, экономичны — для быстрых с хорошей реакцией."],["Особенности выполнения","Все защиты руками на средней выполнять исключительно быстро, чтобы, защитившись, нанести ответный удар, комбинацию или серию."]],"exercises":[{"id":"OGE66-M-DEF-01","text":"Шаг назад (вызвать на движение вперёд и встретить), вправо (вызвать поворот и встречный правой), влево (встречный левой), назад-вправо (от правой с шагом), назад-влево (от левой с шагом).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-M-DEF-02","text":"Подставки ладоней, локтей, предплечий; отбивы ладонью внутрь, тыльной стороной наружу, вниз, вверх — исключительно быстро с ответом; двойная локтевая — дать бить по локтям и утомить.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-M-DEF-03","text":"Уклон вправо (от прямых, бокового и короткого прямого правой) — ответ прямым снизу правой, снизу правой в туловище, боковым правой с шагом левой, затем серия прямых; уклон влево — то же левой. Наклоны вправо/влево от прямых — встречный прямой на месте.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-MID-DEF-O2","title":"Нырок, отклоны, приседание, комбинированная","review":false,"formats":["Работа в паре"],"criteria":[["Техника","От бокового правой — одно слитное круговое движение туловища вправо, вниз, влево и вверх с небольшим приседом; от бокового левой — влево, вниз, вправо и вверх.\nОтклоняясь назад, вытягивать вперёд левую руку (при отклоне назад-влево — правую), чтобы остановить продвижение противника и рассчитать расстояние для ответного удара.\nБез ответа — приседать равномерно на полные ступни; для ответа — вес на переднюю часть стоп и больше на ногу, одноимённую руке ответа.\nВ одном действии: небольшой отклон назад, приседание, уклон вправо, подставки левого плеча, правой ладони и предплечья согнутой левой руки, прикрывающей туловище."],["Тактика","Вызывать на атаку, открывая голову, — нырок — три боковых слитно (пример Тимошина).\nВысоким у канатов против низкорослых; низкорослый финтом левой в голову и акцентом правой в туловище лишает высокого отклонов.\nНаиболее характерна для средней; опытные мастера."]],"exercises":[{"id":"OGE66-M-DEF-04","text":"От бокового правой: слитно туловище вправо—вниз—влево—вверх с небольшим приседом; от бокового левой — наоборот; от прямых — в любую сторону по плану контратаки; в конце серии — ответная серия боковых и снизу в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-M-DEF-05","text":"Отклон назад с вытянутой левой — контратака прямыми; назад-вправо (от правой после левой) с вытянутой левой — прямой левой, снизу левой в туловище; назад-влево (от левой после правой) с вытянутой правой — прямой левой, правой, снизу в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-M-DEF-06","text":"Без ответа — равномерно на полные ступни; для ответа — на переднюю часть стоп с весом на правую (ответ правой) или левую (ответ левой); ответы прямыми снизу и боковыми с весом на разноимённую или одноимённую ногу.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-M-DEF-07","text":"От прямого, бокового, короткого прямого правой: одновременно небольшой отклон, присед, уклон вправо, подставки левого плеча, правой ладони, левого предплечья.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-MID-IP-O3","title":"Ответная контратака из положений после защиты: уклон, отклон, наклон","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Отклоняясь назад-вправо, одновременно вытянуть левую руку к голове противника (назад-влево — правую), рассчитать расстояние для короткого прямого на месте или с шагом.\nТыльной стороной перчатки страховать подбородок, опущенным локтем — туловище; все элементы удара — одним слитным движением."],["Тактика","Положение создают при атаке противника прямыми в голову, чтобы, защитившись, нанести контрудары.\nНеожиданный отход с поворотом 45° — противник промахивается и «проваливается» вперёд.\nДошедший прямой левой раскрывает противника для прямого правой в туловище."]],"exercises":[{"id":"OGE66-M-IP-03","text":"Уклон влево с поворотом справа налево — снизу левой в туловище с шагом правой, прямой снизу левой в голову, + серия правой-левой-правой-левой в голову. Уклон вправо — снизу правой в туловище с шагом или прямой снизу правой с шагом левой + левой-правой-левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-M-IP-05","text":"Отклон назад от прямых/боковых в голову — ответные прямые с отходом; шаг правой назад-вправо с поворотом справа налево 45° — противник «проваливается» — боковой левой, повторные снизу левой в туловище; против левши — шаг левой назад-влево. Отклон назад-вправо + вытянутая левая — короткий прямой правой; назад-влево + вытянутая правая — короткий прямой левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-M-IP-06","text":"Наклон влево (от прямого левой), вес на левой — прямой левой в голову толчком носка левой с поворотом слева направо, пальцы вправо — затем прямой правой в туловище; наклон вправо (от прямого правой) — прямой правой с весом на правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"MID-COUNTER","no":32,"title":"Опережение во встречном бою на средней","task":"Опережающие удары, сохраняя среднюю; сначала с тренером, затем в парах","programs":[{"id":"PRG-MID-COUNTER-1","title":"Опережение с тренером","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Ученик опускает голову и страхует челюсть поднятым плечом (правым при боковом правой; левым при снизу левой)."],["Особенности выполнения","Медленно, удары и защиты заранее установлены; к парам — только когда умеет опережать, сдерживать удар и страховаться; 10–15 мин на каждом занятии несколько месяцев."],["Типичные ошибки","Первое время пропускают удары; применять в вольном бою без навыков — становиться «жертвой» более быстрого противника; подбирать партнёров, умеющих сдерживаться."]],"exercises":[{"id":"ROM-P2-U06","text":"Опережающая форма на средней: сначала индивидуально с тренером — ученик медленно наносит указанные короткие удары, тренер опережает (боковой правой ученика — опережение боковым левой через руку; снизу левой ученика — опережение боковым правой), затем роли меняются; потом в парах; затем по выбору и с маневрированием.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-MID-COUNTER-2","title":"Опережение в парах","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Устойчивое положение, удары сбоку, снизу, короткие прямые; страховка: голова опущена, туловище наклонено, плечо поднято («крауч»); опережающий удар — изнутри, снаружи или через руку.\nАтакующие и контратакующие страхуют голову выбранными защитами."],["Тактика","Не отходить, а идти на сближение, сохраняя среднюю; преимущество у того, кто опередит; подходит превосходящим в быстроте и выносливости."]],"exercises":[{"id":"ROM-P2-G01","text":"Атака: боковые левой и правой в голову; опережение — короткие прямые или боковые правой и левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-G02","text":"Атака: боковой левой в голову и снизу правой в голову/туловище; опережение — снизу правой в голову и боковой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-G03","text":"Атака: два снизу левой и правой в голову/туловище; опережение — два коротких прямых или боковых правой и левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-G04","text":"Атака: прямой левой, боковой правой, боковой левой в голову; от прямого — открытая ладонь, от бокового правой — короткий прямой левой, от бокового левой — короткий прямой правой или снизу.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-HR-02","text":"А — боковой левой и правой в голову; Б — подставки согнутых рук и нырки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-HR-03","text":"А — боковой левой в голову, снизу правой в туловище, боковой правой в голову; Б — согнутая правая, согнутая левая, нырок от правого и ответные боковой правой в голову и снизу левой в туловище.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-HR-04","text":"А — два боковых левой и правой в голову; Б — встречные короткие прямые правой и левой. А — снизу правой в голову, сбоку левой в голову, снизу правой в туловище; Б — встречные боковой левой в голову, снизу правой в голову, сбоку левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-MID-COUNTER-69","title":"Встречные прямые при отходе против серии прямых","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Позиция средней: туловище выпрямлено и слегка наклонено вперёд, плечи и таз вперёд, подбородок на груди, локти сведены, ступни на полу на ширине плеч; страховка свободной рукой, особенно при акцентированном ударе."],["Особенности выполнения","Сначала замедленный темп атаки партнёра, затем боевой."],["Типичные ошибки","Акцентированный удар без страховки — может привести к нокауту."]],"exercises":[{"id":"OGE69-K-MID-01","text":"Партнёр по договорённости атакует серией прямых в голову — сначала в замедленном темпе, затем, когда боксер усвоил своевременность отхода назад с встречными прямыми, быстроту атаки увеличивают до боевой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]}]},{"id":"S4","title":"Ближняя дистанция: базовая техника","stages":[{"id":"CLOSE-POSITION","no":33,"title":"Ближний бой: положение рук и удары","task":"Борьба за положение рук на месте → удары из положений → преодоление нажима","programs":[{"id":"PRG-CLOSE-1","title":"Положения рук и удары вплотную","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Оградить солнечное сплетение: туловище чуть вперёд, голова к груди/плечу противника; руки мешают противнику и позволяют бить самому.\nУдар внутри рук и через руки с заворотом кулака внутрь в последний момент, удар косточками основания пальцев."],["Особенности выполнения","Изучать только с партнёром; сначала весьма медленно, на месте."]],"exercises":[{"id":"ROM-P2-N01","text":"Оба в собранном положении на месте ведут борьбу за выгодное положение рук — весьма медленно; затем удары из разных положений.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-N02","text":"Руки внутри рук противника: накладка предплечья и открытой перчатки на плечо — боковой в голову с закручиванием кисти этой рукой; если руки противника внутри — перевод своих внутрь, иначе снизу в голову с разгибанием ног и туловища; при попытке противника бить снизу — руки вниз, локти в стороны, накладка на предплечья у локтя и удар снизу или сбоку-снизу в челюсть.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-N04","text":"При равных положениях — бить рукой, находящейся внутри, быстрее противника, или перевести руку внутрь и сблокировать. Защиты вплотную: от фланговых и снизу — подставки согнутой руки или тыльной стороны перчатки, от сбоку — нырки, от снизу — открытая перчатка.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-POS-O1","title":"Позиции ближнего боя","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Активнозащитная — отдых, защита от правой, выбор момента; наступательная — развитие успеха, руки свободны; защитные — для имеющих преимущество в росте."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-C-PRN-02","text":"Поворот туловища направо/налево для бокового; уклон вправо с приседом на правой; таз назад и наклон для удара снизу; отклон назад с поворотом для короткого прямого/бокового; присед с поворотом для ответного; круговые движения (нырок) с выпрямлением для ответного; шаги в стороны и назад для вызова.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE66-C-POS-01","text":"Активнозащитная: согнут в пояснице, наклон вперёд, таз назад, ноги на ширине плеч параллельно, касание головами у левого плеча, руки под острым углом прижаты. Наступательная: слегка согнут, таз вперёд, руки опущены, головами не касаются. Защитные (3): наложение предплечий на предплечья/локтевые сгибы; руки снизу под руки противника.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-CP-01","text":"Наступательная позиция","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-CP-02","text":"Активно-защитная позиция","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-CP-03","text":"Защитные позиции","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-POS-69","title":"Позиции и координация таза","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Ноги касаются пола всей ступнёй, мышцы не напряжены."],["Тактика","Активно-защитная — отдых и защита от ударов правой в голову, выбор момента для атаки; наступательная — для активных действий; защитные — при преимуществе в росте."],["Особенности выполнения","Включать в 2–3 первых урока ближнего боя, затем повторять по надобности.\nВыполнять перед обучением ударам — ускоряют усвоение; затем переходить к ударам снизу."]],"exercises":[{"id":"OGE69-PRN-02","text":"Повороты туловища направо/налево для боковых; уклон и присед на правой/левой для бокового или снизу; отведение таза и наклон вперёд для удара снизу; отклон назад с поворотом для короткого прямого; приседание для защиты с ответом снизу; присед с поворотом для ответного бокового/короткого прямого; круговые движения туловищем против бокового с ответом; шаги и забеги в стороны для вызова противника.","formats":[],"labels":["Техника выполнения"],"needs":"","equipment":"","review":false},{"id":"OGE69-C-POS-01","text":"Активно-защитная: туловище согнуто и наклонено вперёд, таз назад, ноги слегка согнуты на ширине плеч, ступни параллельны, вес поровну, касание головами у левого плеча, руки прижаты. Наступательная: туловище слегка согнуто, таз вперёд, головами не касаются, руки свободны. Защитные (3 варианта): предплечья на предплечья/локтевые сгибы противника; прямые руки снизу под руки и развести.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-POS","text":"По команде принять позицию ближнего боя; изменить — таз больше назад, туловище вперёд (голова касается плеча противника); бить снизу в туловище поочерёдно левой и правой, не меняя позиции; «Стоп!»; сменить позицию — таз вперёд, снова удары снизу; затем чередовать обе позиции.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"OGE69-L-COORD","text":"Круговые движения таза по и против часовой; таз вперёд, назад, вправо, влево; движение в правом тазобедренном суставе вперёд и справа налево — с переносом веса на левую, с весом на правой, с переносом с левой на правую; то же левым суставом.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]}]},{"id":"CLOSE-UPPER-BODY","no":34,"title":"Удары снизу в туловище и защиты","task":"8 вариантов ударов снизу в туловище; защиты подставкой локтя, остановкой предплечьем/ладонью. Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-UPPER-BODY-O1","title":"Удары снизу в туловище и защиты","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Из исходного положения: выпрямить ноги; вращение и разгибание в тазобедренных, таз вперёд; поворот и выпрямление туловища; рука согнута, вперёд-вверх; кулак сжать в момент удара; в голову с акцентом — подняться на носки. Удары в туловище — менее согнутой рукой; чем ближе противник, тем больше сгибать руку."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-04","text":"Удары правой и левой снизу в туловище — 8 вариантов (одновременно изучаются защиты от них)","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-CP-05","text":"Защита от ударов снизу в туловище: подставка левого (правого) локтя; остановка наложением правого (левого) предплечья на предплечье бьющей руки; остановка наложением левой ладони на двуглавую мышцу; остановка наложением левого (правого) предплечья","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-UP-01","text":"Варианты для каждой руки: вес на обе ноги; на разноимённую; на одноимённую; с шагом вправо; влево; вперёд левой; вперёд правой с поворотом; назад одноимённой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-DEF-01","text":"Подставка локтя (сгиба) в конце удара; остановка наложением предплечья (одноимённого или противолежащего) в начале движения; остановка ладонью на двуглавую мышцу бьющей руки с приседом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-UPPER-BODY-69A","title":"Удары снизу в туловище: варианты и упражнения без перчаток","review":false,"formats":["На мешке","Работа в паре"],"criteria":[["Техника","Движение: выпрямить ноги, разогнуть тазобедренные и подать таз вперёд, повернуть и выпрямить туловище, рука вперёд-вверх, кулак пальцами кверху, сжать в момент удара; в туловище рука менее согнута, чем в голову; сгиб тем больше, чем ближе противник.\nЭнергичный толчок носком, ноги согнуты, акцент и сжатие кулака в момент удара с немедленным расслаблением; кулаки — в одну цель (солнечное сплетение)."],["Особенности выполнения","Свободной рукой страховать: при ударе снизу — тыльная сторона раскрытой кисти к подбородку, локоть опущен; при боковом — кисть сбоку головы ладонью к ней; при коротком прямом — к подбородку, затем сбоку головы; движения страховки много повторять до автоматизма.\nВ разомкнутом строю без перчаток по команде тренера; тренер наблюдает со стороны, на возвышении.\nВ разомкнутом строю без перчаток; каждое новое упражнение многократно повторять."],["Типичные ошибки","Неэнергичный толчок, мало согнуты колени, нет акцента и сжатия кулака; недостаточный поворот в тазобедренном суставе; низко опущена левая при ударе правой; утрированное или преждевременное движение бедром; слишком выпрямлены туловище и ноги в исходном; параллельные удары мимо одной цели — попадут по локтям.\nВместо одноимённых ног привычно переносят вес на разноимённые — прервать и повторить очень медленно без ошибок."]],"exercises":[{"id":"OGE69-C-UP-B","text":"Варианты: вес на обе ноги; перенос на разноимённую; на одноимённую; с шагом вправо; влево; вперёд левой; вперёд правой с поворотом; назад правой — для каждой руки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-UPB","text":"Из позиции «таз вперёд» по команде правой снизу в туловище с переносом веса на разноимённую ногу; «Стоп!» — разбор; затем левой; поочерёдно левой и правой в одну точку; с шагом вперёд ногой, разноимённой руке; назад — под одноимённую ногу; шаг влево с правой, вправо с левой; во всех направлениях.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"OGE69-L-UPSP","text":"Поочерёдные левой и правой в туловище с весом на одноимённую; то же на разноимённую; левой снизу (вес на правую) — правой (вес остаётся на правой); правой (вес на левую) — левой (вес на левой); левой—правой и правой—левой с акцентом на втором; серии из четырёх: левой—правой—левой на разноимённые + правой снизу; правой—левой—правой + левой снизу. Затем то же в голову.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false},{"id":"OGE69-L-UP2","text":"Два удара снизу (туловище, затем голову) — расчленённо в двухшереножном строю без перчаток; варианты по команде вперемешку; с акцентом на первом или втором; 18 координационных упражнений: левой—правой / правой—левой с шагом вперёд и назад под одноимённые и разноимённые ноги, с шагом влево и вправо, со сменой ноги и шагом назад.","formats":["На мешке"],"labels":[],"needs":"","equipment":"","review":false}]},{"id":"PRG-CLOSE-UPPER-BODY-69B","title":"Защиты от ударов снизу: имитация, шеренги, бой по заданию","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Подставка — в конце удара противника; остановка — в начале его движения; другой рукой локтем страховать туловище, перчаткой — голову.\nДвижения защиты мягкие, слитные, несуетливые."],["Типичные ошибки","Поворачивать вместе с локтем всё туловище — опасно (боковой или короткий прямой в голову)."]],"exercises":[{"id":"OGE69-C-DEF-UB","text":"Подставка левого (правого) локтя в конце удара; остановка — наложение предплечья одноимённой или противолежащей руки на предплечье бьющей в начале движения (с небольшим приседом); наложение ладони на двуглавую мышцу бьющей руки с приседом и наклоном.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-UPDEF","text":"Имитация подставки — движение локтем к солнечному сплетению; имитация остановки предплечьем; две шеренги: одна бьёт снизу в туловище (позже в голову), другая защищается; затем партнёр с каждым ударом шагает вперёд — защита локтем; затем остановка; от ударов в голову — подставка ладони, отклон, отбив; бой по заданию 1–3 раунда; затем два удара снизу в перчатках против подставки локтей и остановки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"CLOSE-UPPER-HEAD","no":35,"title":"Удары снизу в голову и защиты","task":"8 вариантов; защиты отклоном, подставкой ладоней, остановкой. Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-UPPER-HEAD-O1","title":"Удары снизу в голову и защиты — вариант 1","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Из исходного положения: выпрямить ноги; вращение и разгибание в тазобедренных, таз вперёд; поворот и выпрямление туловища; рука согнута, вперёд-вверх; кулак сжать в момент удара; в голову с акцентом — подняться на носки. Рывок плечом вверх в последний момент; кулак пальцами к себе."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-06","text":"Удары правой и левой снизу в голову — 8 вариантов (одновременно изучаются защиты от них)","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-CP-07","text":"Защита от ударов снизу в голову: отклон туловища назад; подставка правой ладони; подставка левой ладони; остановка наложением ладони на двуглавую мышцу","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-UP-02","text":"Варианты: вес на обе; на разноимённую; на одноимённую; с шагом влево; вправо; вперёд одноимённой; вперёд левой; назад одноимённой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-DEF-02","text":"Отклон назад; подставка правой/левой ладони с отводом кулака в сторону в конце удара; остановка ладонью на локтевой сгиб в начале; отбив предплечьем с поворотом туловища.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-UPPER-HEAD-69","title":"Удары снизу в голову и защиты — вариант 2","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Перед ударом слегка согнуть туловище и присесть; резко выпрямить ноги и спину, рывок плечом вверх, в момент акцентированного удара подняться на носки.\nКисть пальцами к себе — бить в подбородок средней частью кулака."],["Особенности выполнения","Свободной рукой страховать: при ударе снизу — тыльная сторона раскрытой кисти к подбородку, локоть опущен; при боковом — кисть сбоку головы ладонью к ней; при коротком прямом — к подбородку, затем сбоку головы; движения страховки много повторять до автоматизма.\nУдары с переносом на одноимённую ногу повторять на нескольких уроках; индивидуально — тренер спиной к боксёру, взяв за руки, проделывает перенос веса вместе с ним."],["Типичные ошибки","Мало сгибают одноимённую ногу — не включается четырёхглавая мышца."]],"exercises":[{"id":"OGE69-C-UP-H","text":"Варианты: вес на обе; на левую; на правую; с шагом влево; вправо; вперёд правой; вперёд левой; назад правой — для каждой руки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-UPH","text":"Подготовка исходного: небольшой присед и поворот в сторону удара; самостоятельно, затем по общей команде. Вариант с весом на одноимённую ногу — расчленённо: перенести вес на правую; движение правого бедра вперёд и справа налево; удар снизу правой с весом на правой; затем целостно; так же левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false},{"id":"OGE69-C-DEF-UH","text":"Отклон назад; подставка правой/левой ладони в конце удара с отводом кулака в сторону; остановка ладонью на локтевой сгиб в начале удара; отбив предплечьем внутрь с поворотом туловища.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"CLOSE-HOOK","no":36,"title":"Боковые в голову и туловище, защиты","task":"8 вариантов боковых; защиты нырком, комбинированной, приседанием, остановкой, отклоном. Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-HOOK-O1","title":"Боковые в голову и туловище, защиты","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Кулак пальцами к себе, локоть в одной плоскости с кулаком на уровне подбородка противника.\nРука под прямым углом, кулак пальцами к себе, кисть согнута в лучезапястном внутрь."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-08","text":"Боковые удары правой и левой в голову — 8 вариантов (одновременно изучаются защиты)","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-CP-09","text":"Защита от боковых в голову: нырок; комбинированная защита; приседание; остановка; отклон назад","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-HK-01","text":"Варианты: вес на обе; на левую; на правую; с шагом вправо; влево; вперёд левой; вперёд правой; назад одноимённой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-HK-02","text":"Варианты: вес на левую; на правую; на обе; с шагом вправо; влево; вперёд левой; вперёд правой; назад одноимённой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-DEF-03","text":"Нырок (слитно: поворот, присед, уклон, наклон вниз, поворот, выпрямление); приседание на полные ступни; комбинированная; остановка наложением предплечья на двуглавую в начале; уклон (поворот с наклоном вперёд-вниз).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-DEF-04","text":"Подставка локтя с незначительным поворотом (смягчить); отклон таза назад с выпрямлением ног; шаг в сторону с поворотом туловища.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-HOOK-69A","title":"Боковые: без перчаток, по фазам, с шагами","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Исходное — поворот туловища направо; толчок ногой и поворот справа налево; в момент удара кулак пальцами к себе, локоть в одной плоскости с кулаком на уровне подбородка противника.\nРука согнута под прямым углом, кулак пальцами к себе, кисть несколько согнута в лучезапястном суставе внутрь.\nЛокоть в одной плоскости с кулаком на уровне или чуть выше; отдельный боковой в голову — локоть несколько выше уровня плеча, минуя защиту локтем."],["Особенности выполнения","Свободной рукой страховать: при ударе снизу — тыльная сторона раскрытой кисти к подбородку, локоть опущен; при боковом — кисть сбоку головы ладонью к ней; при коротком прямом — к подбородку, затем сбоку головы; движения страховки много повторять до автоматизма.\nБоковые с весом на одноимённую ногу несильные — служат исходным положением для более сильного короткого прямого или бокового."],["Типичные ошибки","Забывают страховать голову при боковом левой; локоть ниже кулака — удар внутренней стороной перчатки; исправление — боковой по своей ладони с низким, затем поднятым локтем."]],"exercises":[{"id":"OGE69-C-HK-H","text":"Варианты: вес на обе; на левую; на правую; с шагом вправо; влево; вперёд левой; вперёд правой; назад правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-C-HK-B","text":"Варианты: на левую; на правую; на обе; с шагом вправо; влево; вперёд левой; вперёд правой; назад правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-HK","text":"Без перчаток по команде боковые правой и левой с весом на разноимённую; вариант на одноимённую — три фазы: перенос веса; перенос и поворот туловища; перенос, поворот и удар; серии левой—правой/правой—левой с разными переносами веса; 18 упражнений с шагами вперёд, назад, в стороны и в промежуточных направлениях.","formats":[],"labels":["Имитация без партнёра"],"needs":"","equipment":"","review":false}]},{"id":"PRG-CLOSE-HOOK-69B","title":"Защиты от боковых и боевая практика по раундам","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Руки при нырке и приседании согнуты под острым углом, прижаты к туловищу.\nНырок — в собранной позиции; при одиночном боковом всегда страховать голову и туловище согнутой рукой."],["Тактика","Приседание — экономная защита против высоких; лучше удаётся низкорослым."],["Типичные ошибки","Несобранная позиция при нырке, опоздание; опускают руки, поднимают подбородок."]],"exercises":[{"id":"OGE69-C-DEF-HH","text":"Нырок (слитно: поворот, присед, уклон, наклон вниз, поворот, выпрямление); приседание на полные ступни; комбинированная (отклон, уклон, подставки плеча, ладони, предплечья одновременно); остановка предплечьем на двуглавую мышцу с подбородком к груди; уклон с поворотом и наклоном вперёд-вниз.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-C-DEF-HB","text":"Подставка локтя с незначительным поворотом (смягчить); отклон таза назад с выпрямлением ног; шаг в сторону (правой вправо от правой) с поворотом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-HKDEF","text":"Без перчаток, мысленно представляя кулак противника: нырок, остановка предплечьем на двуглавую мышцу, приседание, отклон назад; затем в двух шеренгах в перчатках: от одиночного правой, от одиночного левой, от правой и левой. Боевая практика: 1-й раунд — ближний бой ударами снизу и защитами; 2-й раунд — ударами снизу и боковыми и защитами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"CLOSE-SHORT","no":37,"title":"Короткие прямые и защиты","task":"6 вариантов короткого прямого; защиты комбинированной, приседанием, отклоном. Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-SHORT-O1","title":"Короткие прямые и защиты","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Отвести кисть несколько в сторону, кулак на уровне своего подбородка; толчок, вращение туловища, рука поворачивается в плече, кулак прямолинейно; в последний момент кисть сгибается вперёд."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-10","text":"Короткий прямой удар правой в голову — 6 вариантов (одновременно изучаются защиты)","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-CP-11","text":"Защита от короткого прямого в голову: комбинированная защита; приседание; отклон назад","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-SP-01","text":"Варианты: вес на разноимённую; на одноимённую; с шагом вперёд; вправо; влево; назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-SHORT-69","title":"Короткий прямой: по ладони → перчатке → груше","review":false,"formats":["На мешке","На лапах","Работа в паре"],"criteria":[["Техника","Перенести вес, повернуть туловище, отвести кисть вправо на уровень своего подбородка; толчком ноги и вращением туловища кулак прямолинейно к цели; в последний момент согнуть кисть вперёд.\nСвоевременно сгибать кисть в лучезапястном суставе; рассчитывать дистанцию до цели."],["Особенности выполнения","Свободной рукой страховать: при ударе снизу — тыльная сторона раскрытой кисти к подбородку, локоть опущен; при боковом — кисть сбоку головы ладонью к ней; при коротком прямом — к подбородку, затем сбоку головы; движения страховки много повторять до автоматизма."]],"exercises":[{"id":"OGE69-C-SP-H","text":"Варианты: вес на левую; на правую; с шагом вперёд левой; вправо; влево; назад правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-SP","text":"Вытянуть левую ладонью к лицу и бить по ней коротким прямым правой (и наоборот), приближая и отдаляя ладонь; два варианта переноса веса; затем в двух шеренгах по внутренней стороне перчаток партнёра на уровне подбородка; затем подвесная тяжёлая груша (с водой или горохом) на уровне головы, тяжёлый мешок, лапы. Защиты: комбинированная, приседание, отклон назад.","formats":["На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки, тяжёлая груша, мешок, лапы","review":false}]}]},{"id":"CLOSE-COMBO2","no":38,"title":"Комбинации из двух ударов","task":"12 комбинаций в туловище и голову, одновременно защиты от них. Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-COMBO2-O1","title":"Комбинации из двух ударов","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Повторный снизу в туловище усиливать поворотом и движением таза вперёд; в голову — выпрямлением спины, рывком плеча, подъёмом на носки."],["Тактика","От двух в одну цель — одно защитное движение; в разные цели — два."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием.\nВладеть каждой комбинацией во всех вариантах; выполнять быстро, доводить до автоматизма."]],"exercises":[{"id":"OGE66-CP-12","text":"Комбинации из двух ударов (туловище/голова) — 12 вариантов: левой—правой снизу в туловище; правой—левой снизу в туловище; левой—правой боковые в голову; правой—левой боковые в голову; левой снизу (боковой) в туловище — короткий прямой правой (боковой) в голову; короткий прямой (боковой) правой в голову — левой снизу (боковой) в туловище или голову; правой снизу (боковой) в туловище — боковой левой (короткий прямой) в голову; боковой левой (короткий прямой) в голову — правой снизу (боковой) в туловище; левой снизу в голову — короткий прямой (боковой) правой в голову; короткий прямой (боковой) правой в голову — левой снизу в голову; правой снизу в голову — боковой левой (короткий правой) в голову; боковой (короткий прямой) левой в голову — правой снизу в голову","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-CMB-01","text":"Двухударные комбинации в голову, в голову и туловище — с весом на разноимённую, одноимённую, на обе ноги; акцентированным может быть первый, второй или оба. Повторные удары одной рукой (снизу в туловище — голову) + третий другой рукой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-COMBO2-69","title":"Комбинации из двух и защиты","review":false,"formats":["На мешке","На лапах","Работа в паре"],"criteria":[["Тактика","Защита: одним движением, если удары в одну цель (уклон/нырок от ударов в голову, подставка локтя от ударов в туловище), двумя — если в разные."],["Особенности выполнения","Выполнять быстро, в тренировке доводить до автоматизма; владеть всеми вариантами.\nТренер вместе с комбинацией подбирает защиту от неё, разучивают так же тщательно; излюбленные 1–3 комбинации поощрять."]],"exercises":[{"id":"OGE69-C-CMB-01","text":"В голову, в туловище, в голову и туловище, в туловище и голову — каждая с весом на разноимённую, одноимённую, обе ноги; акцентированным может быть первый, второй или оба.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-CMB2","text":"Порядок: координация без перчаток → по подставленным перчаткам → в парах с защитами → лапы и снаряды → учебный бой по заданию; разучить комбинации из частых исходных положений: после уклона влево — левой снизу в туловище — боковой правой; после отклона назад — начиная коротким прямым правой.","formats":["На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки","review":false}]}]},{"id":"CLOSE-INSIDE","no":39,"title":"Внутреннее положение рук","task":"4 способа захвата внутреннего положения. Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-INSIDE-O1","title":"Внутреннее положение рук","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-13","text":"Захват руками внутреннего положения (4 способа)","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-INS-01","text":"Четыре способа: кисти сверху на предплечья и развести — снизу в туловище; правая на запястье левой противника, левая снизу — развести — правой снизу в туловище или короткий/боковой левой; зеркально; кисти снизу вверх большими пальцами вверх между руками — развести — короткий прямой/боковой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-CLS-05","text":"Введение рук снизу внутрь — любой удар в голову; сверху внутрь — удары снизу в туловище; смешанные варианты (правая сверху/левая снизу и наоборот).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-INSIDE-69","title":"Внутреннее положение: 4 способа, шеренги, бой по заданию","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","После разведения рук удары наносить стремительно.\nЭтим заканчивается обучение одиночным и двойным ударам; затем серии — преимущественно из наступательной позиции."],["Типичные ошибки","Напряжённость и скованность в первых двух раундах — тренер прерывает и спокойно объясняет."]],"exercises":[{"id":"OGE69-C-INS-01","text":"1) кисти сверху на предплечья, развести — удары снизу в туловище; 2) правая сбоку на запястье левой, левая снизу внутрь — правой снизу в туловище или короткий/боковой левой; 3) зеркально; 4) кисти снизу вверх большими пальцами вверх, развести — короткий прямой/боковой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-INS","text":"Одна шеренга вводит руки внутрь позиции партнёра другой и бьёт снизу условно, не в полную силу; через две минуты смена ролей; в конце основной части — попарно ближний бой по заданию с изученными приёмами (три раунда).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"CLOSE-ACTIVE-DEF","no":40,"title":"Активные защиты","task":"Активные защиты от ударов снизу в туловище (2), боковых (5), коротких прямых (3). Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-ACTIVE-DEF-O1","title":"Активные защиты","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-14","text":"Активная защита от ударов снизу в туловище (по 2 защиты)","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-CP-15","text":"Активная защита от бокового удара в голову (по 5 защит)","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-CP-16","text":"Активная защита от короткого прямого в голову (по 3 защиты)","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-ACT-01","text":"От снизу в туловище (3): наложение предплечья — ответ боковым/снизу левой в голову; ладонь на двуглавую — правой снизу в голову; подставка левого локтя — боковой/снизу правой. От бокового правой в голову (5): нырок + боковой левой; ладонь на двуглавую + правой снизу/боковой/короткий; уклон вправо + правой снизу; отклон + боковой; присед + боковой левой. От бокового левой — аналогично (нырок + встречный снизу левой в туловище). От короткого прямого (2): уклон + боковой (снизу); присед + боковой. Каждый — с развитием серией.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-CLS-04","text":"Нырок, приседание, подставка плеча, локтя, двойная локтевая, остановка предплечьем/ладонью на бицепс, уклоны — каждая с конкретным ответным ударом и развитием атаки; «глухая» защита против продолжительной серии — выявить приёмы противника, утомить, перейти в контратаку.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-ACTIVE-DEF-69","title":"Активные защиты в парах","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Активной может быть любая защита, если после неё преднамеренно переходить в атаку подготовленным ударом или серией.\nДля перехода в контратаку достаточно одной, самое большее двух защит; долго защищаться без контратаки — проиграть бой."],["Типичные ошибки","Защита только чтобы избежать удара — бой становится вялым, захваты, толчки."]],"exercises":[{"id":"OGE69-C-ACT-01","text":"От удара снизу в туловище — 3 (остановка предплечьем с ответом боковым/снизу левой; ладонь на бицепс с ответом правой снизу; подставка локтя с ответом); от бокового в голову — 5 (нырок с ответным боковым; остановка; уклон с ответом снизу; отклон с боковым; приседание с боковым); от короткого прямого — 2 (уклон с ответным боковым/снизу; приседание с боковым) — каждая с развитием атаки серией.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-ACT","text":"Тренер задаёт одному определённый удар, другому — определённую защиту и контратаку одиночным ударом, затем комбинацией из двух, позже серией; удары лёгкие, без силы.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]}]},{"id":"S5","title":"Ближняя дистанция: выходы и входы","stages":[{"id":"CLOSE-EXIT","no":41,"title":"Ближний бой: освобождение, отрыв, заход","task":"Отрыв назад/в стороны, заход за противника, вход встречными","programs":[{"id":"PRG-CLOSE-2","title":"Отрыв и заход","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Ближний бой навязывать тому, кто слабее вблизи; с сильным в ближнем — вести бой на дальней и средней."],["Особенности выполнения","Порядок изучения по."]],"exercises":[{"id":"ROM-P2-N03","text":"Освобождение от связывания быстрым шагом назад или в сторону; противник проваливается — боковой (несколько сверху) в голову через руку. Накладка перчаток на плечи для задержки ударов.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"ROM-P2-N05","text":"Блокирование и удары с коротким отрывом назад и в стороны на среднюю и снова сближение; шаги в стороны с заходом за спину противника и удар в момент его поворота. Последовательность: на месте положения рук → удары из положений → удары с преодолением нажима → отрыв назад/в стороны и заход.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-EXIT-O1","title":"Выход из ближнего боя","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Выходить, когда противник физически превосходит в ближнем и контрмеры не помогают."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-17","text":"Выход из ближнего боя: наложением кистей на двуглавые мышцы с шагом назад правой ногой; нырком и шагом вправо от бокового левой; нырком и шагом влево от бокового правой; с прямым левой в голову и шагом назад правой ногой","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-EX-01","text":"1) кисти на плечевую часть рук противника и неожиданный шаг назад правой; 2) нырок от бокового правой, шаг влево левой, назад правой, вытянуть правую, затем левую; 3) нырок от бокового левой, шаг вправо, вытянуть левую; 4) короткий прямой левой с шагом назад правой; 5) короткий прямой правой с шагом назад правой, подтянуть левую — на дальней.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-EXIT-69","title":"Выход из ближнего боя — 5 способов","review":false,"formats":["На мешке","На лапах","Работа в паре"],"criteria":[["Тактика","Выходить, когда противник физически сильнее в ближнем бою и контрмеры не дают перехватить инициативу."]],"exercises":[{"id":"OGE69-C-EX-01","text":"1) кисти на плечевую часть рук противника и неожиданный шаг назад правой (левша — левой); 2) нырок от бокового правой, шаг влево левой, правой назад, вытянуть правую, затем левую руку; 3) нырок от бокового левой, шаг вправо, вытянуть левую; 4) короткий прямой левой и шаг назад правой; 5) короткий прямой правой и шаг назад правой, подтянуть левую — на дальней дистанции.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-EX","text":"В парах: один выходит указанным тренером способом; если выход с ударом — бить по перчаткам партнёра; затем снаряды, лапы, условный бой.","formats":["На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки","review":false}]}]},{"id":"CLOSE-ENTRY","no":42,"title":"Вхождение в ближний бой","task":"Вход во время своей атаки (3 способа) и контратакой на прямой/боковой левой (11 вариантов). Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-ENTRY-SAFE-69","title":"Сближение без столкновения головами","review":false,"formats":["Работа в паре"],"criteria":[["Техника","См. описание.\nВытянутая левая рука прикрывает плечом подбородок от контрудара правой."],["Особенности выполнения","В ближнем бою развивать периферическое зрение — видеть движение противника сбоку."],["Типичные ошибки","Наклон туловища и головы вперёд при сближении — частая причина столкновения головами и рассечения бровей."]],"exercises":[{"id":"OGE69-K-HEAD-01","text":"При сближении подавать таз вперёд, ноги согнуты на ширине плеч на полной ступне; голова естественно отклоняется назад; руки прижаты; головами не касаться; пользоваться прямым и периферическим зрением.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-K-HEAD-02","text":"После атаки акцентированным ударом правой немедленно заканчивать атаку прямым левой в голову с шагом назад; при невыгодной ситуации на ближней/средней — выбросить левую руку и шаг назад; иметь готовые средства против любого исходного положения для новой атаки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-ENTRY-CNT-O1","title":"Вход в ближний бой контратакой на атаку противника","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Тщательно страховать свободной рукой."],["Тактика","Наиболее распространённый способ; заставить противника атаковать прямым левой — замедленным отходом, открытием головы (опустить левую)."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-19","text":"Вхождение в ближний бой контратакой на атаку противника прямым (боковым) левой в голову — 11 вариантов: прямой левой встречный в голову — правой снизу в туловище; боковой левой в голову — короткий прямой правой; снизу левой в туловище — боковой правой в голову; прямой левой в туловище — боковой правой в голову; боковой левой в туловище — боковой правой, левой (прямой) в голову; прямой правой в туловище — боковой левой в голову; прямой правой в голову — левой снизу (боковой) в туловище; «кросс» правой в голову — снизу левой в туловище; уклон вправо; уклон влево — каждый с развитием атаки","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-ENT-02","text":"Контрудары прямыми правой/левой в голову/туловище; уклоны влево/вправо с ударами снизу, боковыми, короткими прямыми; боковые левой с уклоном вправо и шагом правой вперёд-вправо; отбивы правой внутрь / предплечьем наружу / левой ладонью — с ударами снизу, боковыми, прямыми, короткими; кросс правой; нырок с ответным боковым правой в туловище; нырок со встречным боковым левой в туловище; приседание с ответным левой снизу в голову. На прямой/боковой правой: встречные прямой/боковой правой с уклоном влево, боковой правой в туловище с уклоном влево, кросс левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-CLS-07","text":"Входить, чтобы использовать физическое преимущество, перехватить инициативу у высокого; использовать атаку противника прямыми/боковыми для контрудара и развития в ближнем; неожиданный выход — вызвать движение вперёд и встретить ударом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-ENTRY-CNT-69","title":"Вход в ближний бой контратакой: на прямой левой, в парах, условном бою, на лапах","review":false,"formats":["На лапах","Работа в паре"],"criteria":[["Техника","Не забывать о страховке и угрожать ударами.\nВходя с контрударом, тщательно страховать голову и туловище свободной рукой."],["Тактика","Заставить противника атаковать прямым левой: замедленный отход (шаг назад), открытие головы (опустить левую руку)."]],"exercises":[{"id":"OGE69-L-ENT","text":"Показать несколько способов входа на атаку прямым левой, закрепить в парах, в условном бою, на лапах (3–4 способа достаточно на первое время); для входа при своей атаке — маневры оттеснения к канатам: попеременные шаги вперёд с уклонами (шаг левой — уклон влево, правой — вправо), слитные скользящие шаги вправо-вперёд и влево-вперёд; затем применять в условном и вольном бою, сочетая вход с выходом.","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки","review":false},{"id":"OGE69-C-ENT-02","text":"Контрудары прямыми правой/левой в голову/туловище; уклоны с ударами снизу, боковыми, короткими прямыми; боковые с уклоном и шагом вперёд-вправо; отбивы ладонью правой внутрь / предплечьем наружу с ударами левой; отбив ладонью левой с ударами правой; перекрёстный правой; нырки с ответным/встречным боковым; приседание с ответом левой снизу. На атаку правой: встречный прямой/боковой правой с уклоном влево, боковой правой в туловище с уклоном вправо, перекрёстный левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-ENTRY-ATT-O1","title":"Вход в ближний бой во время собственной атаки","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Входить при преимуществе сложения (низкий рост, короткие руки), умении ближнего боя, стремлении захватить инициативу, «сбить» дыхание."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-18","text":"Вхождение в ближний бой во время собственной атаки: прямым левой в голову, боковым левой в голову, прямым левой в туловище — с развитием атаки","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-ENT-01","text":"В открытую голову/туловище; прямой левой в голову и развитие ударами снизу в туловище и боковым правой; финтовыми (прямые, боковые, снизу) открыть другое место (финт в туловище — удар в голову; финт левой — боковой правой); обманными движениями согнутым туловищем влево-вправо; под двойной локтевой; мимикой; приём «солнышко» (круговые финты туловищем, бросок с боковым).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-CLS-07","text":"Входить, чтобы использовать физическое преимущество, перехватить инициативу у высокого; использовать атаку противника прямыми/боковыми для контрудара и развития в ближнем; неожиданный выход — вызвать движение вперёд и встретить ударом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":true}]},{"id":"PRG-CLOSE-ENTRY-ATT-69","title":"Вход в ближний бой во время собственной атаки: манёвр к канатам/в угол","review":false,"formats":["Работа в паре"],"criteria":[],"exercises":[{"id":"OGE69-C-ENT-01","text":"В открытую голову/туловище; после атаки противника прямым левой — развить правой и левой снизу в туловище и боковым правой; через финты (прямой в туловище → в голову; финт прямым левой → боковой правой); обманные движения туловищем; под двойной локтевой защитой; мимикой; приём «солнышко» (круговые движения туловищем, затем бросок с боковым).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-ENT","text":"Показать несколько способов входа на атаку прямым левой, закрепить в парах, в условном бою, на лапах (3–4 способа достаточно на первое время); для входа при своей атаке — маневры оттеснения к канатам: попеременные шаги вперёд с уклонами (шаг левой — уклон влево, правой — вправо), слитные скользящие шаги вправо-вперёд и влево-вперёд; затем применять в условном и вольном бою, сочетая вход с выходом.","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки","review":true}]}]},{"id":"TR-CLOSE-COMBINE","no":43,"title":"Сочетание входа в ближний бой и выхода из него (условный и вольный бой)","task":"После разучивания способов выхода и входа — применять их по заданию в условном и вольном бою, сочетая вход с выходом.","programs":[{"id":"PRG-TR-CC-1","title":"Вход в ближний бой встречными действиями в произвольном бою","review":false,"formats":["Бой с тенью","На мешке","Работа в паре"],"criteria":[["Тактика","Используя атаку противника, от прямых ударов делает уклон, от боковых — нырок и этим самым достигает сближения."],["Особенности выполнения","Произвольный учебно-тренировочный бой с применением всех средств боя; практиковать преимущественно встречные действия для входа в ближний бой — 2 раунда."]],"exercises":[{"id":"ROM-HR-05","text":"Боевая практика 3 раунда — совершенствовать защиты, ответные и встречные; индивидуально с тренером; снаряды (серии ударов) 20 мин; произвольный бой 2 раунда — преимущественно встречные действия для входа в ближний бой; «бой с тенью» сериями.","formats":["Бой с тенью","На мешке","Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-TR-CC-2","title":"Смена тактики подхода, чтобы удержать противника на ближней","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Быстрый прямолинейный подход к противнику не принес успеха, не достиг боксер результата и при заходе с той стороны, в которую двигается противник. Тогда боксер должен попытаться создать такую обстановку, чтобы противник попадал в углы ринга."],["Особенности выполнения","Течение одного раунда боксер может трижды менять тактику подхода к противнику."],["Типичные ошибки","Боксер при подходе к противнику для атаки прямыми ударами из-за прямолинейности движения подвергает свою голову встречным ударам."]],"exercises":[{"id":"ROM-IM-04","text":"В течение одного раунда трижды менять тактику подхода, чтобы удержать противника на ближней: быстрый прямолинейный подход → заход в сторону движения противника → загонять в углы ринга.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-TR-CC-3","title":"Вход + выход по заданию тренера","review":true,"formats":["На мешке","На лапах","Работа в паре"],"criteria":[["Техника","Входя в ближний бой с контрударом, тщательно страховать свою голову и туловище свободной от удара рукой."],["Тактика","Выход из ближнего боя позволяет избежать невыгодного положения в ближнем бою с противником, более сильным физически."],["Особенности выполнения","В тех случаях, когда боксер выходит из ближнего боя с ударом, он наносит его по перчаткам партнера."],["Типичные ошибки","При сближении с противником чаще всего столкновение головами происходит от наклона боксерами туловища и головы вперед."]],"exercises":[{"id":"OGE69-C-EX-01","text":"1) кисти на плечевую часть рук противника и неожиданный шаг назад правой (левша — левой); 2) нырок от бокового правой, шаг влево левой, правой назад, вытянуть правую, затем левую руку; 3) нырок от бокового левой, шаг вправо, вытянуть левую; 4) короткий прямой левой и шаг назад правой; 5) короткий прямой правой и шаг назад правой, подтянуть левую — на дальней дистанции.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":true},{"id":"OGE69-C-ENT-02","text":"Контрудары прямыми правой/левой в голову/туловище; уклоны с ударами снизу, боковыми, короткими прямыми; боковые с уклоном и шагом вперёд-вправо; отбивы ладонью правой внутрь / предплечьем наружу с ударами левой; отбив ладонью левой с ударами правой; перекрёстный правой; нырки с ответным/встречным боковым; приседание с ответом левой снизу. На атаку правой: встречный прямой/боковой правой с уклоном влево, боковой правой в туловище с уклоном вправо, перекрёстный левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":true},{"id":"OGE69-L-EX","text":"В парах: один выходит указанным тренером способом; если выход с ударом — бить по перчаткам партнёра; затем снаряды, лапы, условный бой.","formats":["На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки","review":true},{"id":"OGE69-L-ENT","text":"Показать несколько способов входа на атаку прямым левой, закрепить в парах, в условном бою, на лапах (3–4 способа достаточно на первое время); для входа при своей атаке — маневры оттеснения к канатам: попеременные шаги вперёд с уклонами (шаг левой — уклон влево, правой — вправо), слитные скользящие шаги вправо-вперёд и влево-вперёд; затем применять в условном и вольном бою, сочетая вход с выходом.","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки","review":true}]}]}]},{"id":"S6","title":"Ближняя дистанция: повторные удары, серии, угол, тактика","stages":[{"id":"CLOSE-REPEAT","no":44,"title":"Повторные удары одной рукой","task":"12 вариантов повторных, одновременно защиты. Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-REPEAT-O1","title":"Повторные удары одной рукой","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-20","text":"Повторные удары одной рукой (одновременно изучаются защиты): два-три левой снизу в туловище; два-три правой снизу в туловище; два-три левой снизу в голову; два-три правой снизу в голову; два-три боковым левой в голову; два-три боковым правой в голову; левой снизу в туловище — левой снизу в голову; правой снизу в туловище — правой снизу в голову; боковые левой в туловище и голову; боковые правой в туловище и голову; боковой левой в голову — левой снизу в туловище; боковой правой в голову — правой снизу в туловище","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-CLS-06","text":"Удар в голову — раскрыть туловище; в туловище — раскрыть голову; снизу в подбородок — поднять голову и нанести боковой/короткий прямой; повторные одной рукой — снизу в туловище, затем снизу в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-REPEAT-69","title":"Повторные удары: перчатки, лапы, снаряды","review":false,"formats":["На мешке","На лапах","Работа в паре"],"criteria":[["Техника","Повторный снизу в туловище усиливать поворотом таза и туловища и движением вперёд; снизу в голову — выпрямить спину, рывок плечом, выпрямить ноги, подняться на носки."],["Тактика","От повторных — те же защиты, что от одиночных."],["Типичные ошибки","Упражняться в повторных ударах с партнёром нельзя — трудно защититься, травма."]],"exercises":[{"id":"OGE69-C-REP-01","text":"Повторные правой и левой в одну или разные точки; часто добавить третий удар другой рукой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-REP","text":"Показать, что удар можно повторить; упражняться по перчаткам партнёра, на лапах и снарядах; затем развивать атаку ударом другой руки, комбинацией, серией (после повторного снизу в туловище-голову — короткий прямой правой; после повторного бокового левой — правой снизу в туловище).","formats":["На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки, лапы, снаряды","review":false}]}]},{"id":"CLOSE-SERIES3","no":45,"title":"Серии из трёх ударов","task":"10 серий с акцентом на третьем ударе. Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-SERIES3-O1","title":"Серии из трёх ударов","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием.\nСистематически совершенствовать до почти автоматического выполнения."]],"exercises":[{"id":"OGE66-CP-21","text":"Серии из трёх ударов — 10 вариантов (одновременно изучаются защиты): левой—правой снизу в туловище — боковой (короткий прямой) левой в голову; правой—левой снизу в туловище — боковой (короткий прямой) правой в голову; левой—правой боковые в голову — левой снизу в туловище; правой—левой боковые в голову — правой снизу в туловище; два повторных боковых левой — боковой правой в голову; два повторных боковых правой — боковой левой в голову; левой снизу в туловище — левой снизу в голову — боковой правой; правой снизу в туловище — правой снизу в голову — боковой левой; левой снизу в туловище — боковой левой — боковой правой в голову; правой снизу в туловище — боковой правой — боковой левой в голову","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-SER-01","text":"Трёхударные серии с акцентом на третьем; первые два отвлекают от места акцента; второй готовит исходное положение.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-SERIES3-69","title":"Серии из трёх: от двух ударов к трём","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Первые два отвлекают от места третьего; вторым готовить исходное положение для акцентированного третьего."],["Тактика","Серии по неожиданно открывающимся целям практически невозможны — учить стандартным автоматизированным сериям."],["Особенности выполнения","Постоянная корректура ошибок.\nСовершенствовать до почти автоматического выполнения."]],"exercises":[{"id":"OGE69-L-SER","text":"Сначала простейшие комбинации из двух (два снизу в туловище; в туловище и голову; два боковых; снизу в туловище — боковой), затем добавить третий удар, затем целостные серии из трёх, позже из четырёх; порядок обучения — как для одиночных.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-C-SER3-01","text":"Трёхударные серии в голову и туловище с акцентом на третьем.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"CLOSE-SERIES4","no":46,"title":"Серии из четырёх ударов","task":"10 серий. Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-SERIES4-O1","title":"Серии из четырёх ударов","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-22","text":"Серии из четырёх ударов — 10 вариантов (одновременно изучаются защиты): левой—правой—левой снизу в туловище — боковой правой (короткий прямой) в голову; правой—левой—правой снизу в туловище — боковой левой (короткий прямой) в голову; левой снизу в туловище — боковые правой, левой в голову — правой снизу в туловище; боковой левой в голову — правой, левой снизу в туловище — боковой правой в голову; правой снизу в туловище — боковые левой, правой в голову — левой снизу в туловище; боковой правой в голову — левой, правой снизу в туловище — боковой левой в голову; боковые левой—правой—левой в голову — правой снизу в туловище; боковые правой—левой—правой в голову — левой снизу в туловище; боковой левой в туловище — боковой левой в голову — правой (боковой) в голову — левой снизу в туловище; боковой правой в туловище — боковой правой в голову — боковой левой в голову — правой снизу в туловище","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-SER-02","text":"Левой—правой—левой снизу в туловище — боковой правой в голову (акц.); правой—левой—правой снизу в туловище — боковой левой (акц.); левой снизу в туловище (акц.) — боковые правой, левой — правой снизу в туловище (акц.); боковой левой (акц.) — правой, левой снизу в туловище — боковой правой (акц.); правой снизу (акц.) — боковые левой, правой — левой снизу (акц.); боковой правой (акц.) — левой, правой снизу — боковой левой (акц.); боковые левой—правой—левой — правой снизу в туловище (акц.); боковые правой—левой—правой — левой снизу (акц.); боковой левой в туловище — боковые левой, правой в голову (акц.) — левой снизу в голову (акц.); боковой правой в туловище — боковые правой, левой (акц.) — правой снизу в туловище (акц.).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-SERIES4-69","title":"Серии из четырёх (10 образцов с акцентами)","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Отвлекающий (относительно слабый) удар готовит исходное положение для акцентированного."]],"exercises":[{"id":"OGE69-C-SER4-01","text":"1) левой—правой—левой снизу в туловище — боковой правой в голову (акц.); 2) зеркально; 3) левой снизу в туловище (акц.) — боковые правой, левой в голову — правой снизу в туловище (акц.); 4) боковой левой в голову (акц.) — правой, левой снизу в туловище — боковой правой (акц.); 5) правой снизу в туловище (акц.) — боковые левой, правой — левой снизу (акц.); 6) боковой правой (акц.) — левой, правой снизу — боковой левой (акц.); 7) боковые левой—правой—левой — правой снизу в туловище (акц.); 8) зеркально; 9) боковой левой в туловище — боковые левой, правой в голову (акц.) — левой снизу в голову (акц.); 10) боковой правой в туловище — боковые правой, левой в голову (акц.) — правой снизу в туловище (акц.).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"CLOSE-SERIES-DEF","no":47,"title":"Защита от серий","task":"Уклоны влево/вправо, двойная локтевая («глухая»). Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-SERIES-DEF-O1","title":"Защита от серий","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Двойная локтевая: таз вперёд, ноги согнуты, правая защищает голову, левая — туловище, подбородок к груди, плечи подняты и сведены."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."],["Типичные ошибки","Застаиваться в двойной локтевой («защита ради защиты»); злоупотреблять глухой."]],"exercises":[{"id":"OGE66-CP-23","text":"Защита от серии ударов: уклон влево; уклон вправо; двойная локтевая или глухая защита","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-C-ACT-02","text":"Уклоны влево/вправо прерывают серию и ставят под угрозу ответа; двойная локтевая — принять 2–3 удара и самому контратаковать серией; глухая — в исключительно редких случаях (после сильного удара).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-SERIES-DEF-69","title":"Защита от серий; двойная локтевая в парах","review":false,"formats":["Работа в паре"],"criteria":[["Типичные ошибки","Долго стоять на месте в двойной локтевой защите — «защита ради защиты».\nСильные удары партнёру — случайная ошибка приведёт к травме; долго задерживаться в глухой защите."]],"exercises":[{"id":"OGE69-C-SDEF-01","text":"Уклоны влево/вправо прерывают серию и ставят противника под угрозу ответного; двойная локтевая: таз вперёд, правая защищает голову, левая — туловище, подбородок к груди, плечи подняты и сведены; приняв 2–3 удара — контратака сериями; глухая защита — в исключительных случаях.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-L-SDEF","text":"Один наносит серии, второй в двойной локтевой защите; уклоны от серий; с двойной локтевой — продвигаться вперёд, тесня к канатам, для входа в ближний бой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"CLOSE-CORNER","no":48,"title":"Выход из углов и от канатов","task":"Активной защитой; уклонами с вытягиванием руки, шагом вперёд и ответными. Каждый приём: без перчаток в разомкнутом строю → по неподвижным перчаткам в двух шеренгах → условный бой: одностороннее, затем двустороннее задание → вольный бой с заданием.","programs":[{"id":"PRG-CLOSE-CORNER-O1","title":"Выход из углов и от канатов","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Выход вправо безопаснее (от сильнейшей руки); от левши — влево; противник после промаха сам в углу — атаковать серией."],["Особенности выполнения","Учебная последовательность изучения: имитация в разомкнутом строю без перчаток → удары по подставленным перчаткам в двух шеренгах (перчатку держать неподвижно) → условный бой: сначала одностороннее задание, затем двустороннее → вольный бой с заданием применять прием."]],"exercises":[{"id":"OGE66-CP-24","text":"Выход из углов и от канатов: активной защитой от боковых и ударов снизу; уклонами вправо или влево от боковых (прямых) в голову с вытягиванием вперёд руки, шагом вперёд и ответными ударами","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false},{"id":"OGE66-C-CRN-01","text":"Сгруппировавшись, порывистое движение как бы влево, затем толчком левой — выход вправо с разворотом на правой; или остановка наложением предплечий и серия ответных — шаг вправо — дальняя; или прыжок в сторону от удара с поворотом, «меняясь местами», с толчковым ударом в туловище; или уклон и вытянутая рука на уровне груди противника, мелкими шагами на дальнюю.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-CORNER-69","title":"Выход из угла и от канатов","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Выход вправо безопаснее — от сильнейшей руки; от левши — влево; использовать промах противника, чтобы он сам оказался в углу.\nЛучше всего выходить активной защитой — контратакой."]],"exercises":[{"id":"OGE69-C-CRN-01","text":"Сгруппировавшись, порывисто как бы влево, затем толчком левой — вправо с разворотом на правой; активной защитой (остановки) и серией ответных — шаг вправо и на дальнюю; прыжком в сторону от бокового с поворотом, «меняясь местами», с толчковым ударом в туловище; уклоном с вытянутой рукой мелкими шагами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false},{"id":"OGE69-L-CRN","text":"От канатов — быстрый уклон с контратакой или маневр в сторону (лучше вправо); угол: один в углу, другой атакует лёгкими ударами, защищающийся применяет показанный тренером способ; сначала медленно, потом быстрее, но не сильнее.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false}]}]},{"id":"CLOSE-TACTICS","no":49,"title":"Ведение ближнего боя","task":"Тактические приёмы ближнего боя: мгновенная атака при сближении, внутреннее положение, опережение; тактическое назначение каждого средства","programs":[{"id":"PRG-CLOSE-TACTICS-O1","title":"Тактика ближнего боя","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","По весу на ногах: на правой — готовит правую; на выставленной левой — ждать отхода/отклона; равномерно на согнутых — удар снизу."],["Особенности выполнения","В ближнем бою ориентироваться мышечным чувством, осязанием, слухом (ритм дыхания); план не схема, меняется по действиям противника."],["Типичные ошибки","Малоопытные в «грогги» сразу атакуют и обмениваются ударами — проигрывают; увлекаться видимым превосходством опасно."]],"exercises":[{"id":"OGE66-C-TAC-01","text":"Мгновенная атака при сближении; внутреннее положение рук; опережающий снизу/короткий при замахе бокового; смена дистанции шагом и новая атака; финты; финт взглядом; смена темпа; раскрытие глухой защиты (нажать на перчатку сверху — снизу правой в туловище — боковой левой); удар из захвата; удары снизу в клинче узкими локтями; обострение боя; энергичная непрерывная атака; спурт за 20–30 с до конца раунда; повторные удары; набор очков лёгкими ударами; создание исходного положения для акцентированного; ограничение маневра (оттеснение в угол); экономия сил; контратака; использование сопротивления/давления (шаг назад и удар снизу); чтение веса на ногах противника; вывод из равновесия; активные защиты; глухая защита — редко; полуклинч (высоким); клинч/глухая при «грогги»; забегание; против левши — чаще правой, следить за левой, уклон влево.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-CLS-01","text":"Начать серию ударов снизу и выйти; против более низких — четыре защитные позиции; высокорослый тоже должен владеть ближним боем.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-CLS-02","text":"Смена активной и активно-защитной позиций; повторные снизу + боковой; приёмы занятия внутреннего положения; четыре серии из 4-го способа внутреннего положения.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-CLS-03","text":"Использовать удары снизу в туловище (заставить опустить руки → акцентированный в голову), снизу в голову (выпрямить → снизу в туловище), боковые (оттеснить к канатам, раскрыть туловище), короткие прямые; отход, шаги вправо/влево для вызова поворота и для выхода из ближнего боя.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-TACTICS-69A","title":"Ведение ближнего боя: инициатива, финты, темп, захваты","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Противник должен поверить взгляду и ложному движению.\nПротивнику трудно приспособиться к спурту в конце раунда."],["Типичные ошибки","Увлекаться видимым превосходством — опасность ответного удара правой или левой в голову."]],"exercises":[{"id":"OGE69-T-01","text":"Мгновенно атаковать при сближении; ввести руки внутрь позиции и наносить снизу и боковые; против бокового — остановка в начале движения противостоящей рукой или подставка предплечья; когда противник отводит руку для бокового — опережающий снизу в голову или короткий прямой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-02","text":"Неожиданно шагом назад/влево/вправо сменить дистанцию и атаковать; финтовыми ударами подготовить исходное положение для удара в другую цель; направление взгляда с ложным движением; резко сменить относительно медленный темп на быстрый серией.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-03","text":"Ударом в открытое место головы, а когда поднимет руку — снизу в туловище; нажать открытой левой перчаткой сверху на перчатку, при сопротивлении (руки вверх) — правой снизу в туловище, затем боковой левой в голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-04","text":"Если противник захватил руки — ввести руку между его руками, резко повернуть плечо и правой снизу в подбородок с развитием серией; если обхватывает — держа локти узко, бить снизу в туловище до освобождения.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-05","text":"Сгруппироваться, спрятать подбородок и обрушить серию сильных ударов (при превосходстве в выносливости и силе); превосходство в быстроте — разнообразный бой; коренастому против «дальнего» — уклонами влево-вправо сблизиться и бить сериями в туловище и голову.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-06","text":"Ведя ближний бой в спокойном темпе, за 20—30 секунд до конца раунда начать атаку более интенсивно.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-07","text":"Захватив внутреннее положение — удар в туловище, повторный той же рукой снизу в подбородок, боковой другой рукой; повторными боковыми в голову или снизу в туловище подготавливать акцентированный; набирать очки множеством лёгких ударов; заканчивать серию лёгким левой с отклоном и разворотом правого плеча — короткий прямой правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-CLOSE-TACTICS-69B","title":"Ведение ближнего боя: маневр, экономия, контратака, чтение веса, защиты","review":false,"formats":["Работа в паре"],"criteria":[["Типичные ошибки","Излишнее напряжение, грубая борьба, удары, не достигающие цели.\nЗлоупотреблять глухой защитой; новичок в «грогги» сразу атакует и обменивается ударами."]],"exercises":[{"id":"OGE69-T-08","text":"Перенося вес с ноги на ногу и поворачивая согнутое туловище влево-вправо (угроза с флангов), отрезать путь к отступлению, оттеснить в угол/к канатам и атаковать непрерывной серией быстрых ударов.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false},{"id":"OGE69-T-09","text":"Не напрягать излишне мышцы, не допускать держаний, захватов, толчков, промахов; в касании головой во время защит расслаблять неработающие мышцы.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-10","text":"Опережающим ударом захватить инициативу и продолжить серией; при встречном сопротивлении — шаг назад и резко правой снизу; при давлении и толчках — неожиданный шаг назад и удар снизу, когда противник подался вперёд.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-11","text":"Вес на правой — готовит атаку правой (контрудар правой в голову); вес на выдвинутой левой — ожидать отхода/отклона; вес поровну на согнутых ногах — ждать удара снизу.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-12","text":"Заставить промахнуться против часто повторяемых ударов; финтом вызвать определённый удар и встретить подготовленной защитой и контрударом с серией; активные защиты: остановки, уклоны, нырки, отклоны, подставки локтей и плеч, приседание; неожиданные уклоны/отклон для исходного положения.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-13","text":"Глухая защита — в исключительных случаях против сильного, но не мастера ближнего боя, наблюдая и выжидая утомления; полуклинч для высоких: руки на руки, вплотную грудью, остановки предплечьями на локтевые сгибы, затем атака на дальней; при «грогги» — клинч или глухая защита, при сильном головокружении — опуститься на колено.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-14","text":"Забеганием вызвать неожиданный поворот и нанести короткий прямой правой, снизу левой в туловище; против левши — чаще удары правой, следить за его левой, вовремя активная защита уклоном влево.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-T-15","text":"Знать, для чего служит каждое средство: позиции, удары снизу/боковые/короткие прямые, отход и шаги в стороны, защиты (нырок, приседание, подставки, остановки, уклоны, двойная локтевая) с ответными, введение рук, комбинации, выход, повторные, вход, серии, выход из угла.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"","review":false}]}]},{"id":"CLOSE-PERFECT","no":50,"title":"Совершенствование ближнего боя","task":"Лапы, партнёр, условный и вольный бой, снаряды, акценты — после усвоения программы обучения","programs":[{"id":"PRG-CLOSE-PERFECT-PADS-1","title":"Лапы: удары снизу, боковые, короткие прямые","review":false,"formats":["На лапах"],"criteria":[["Техника","Лапы держать на вертикальной линии голова — туловище боксёра, не шире; целевой точкой вниз для ударов снизу (на высоте солнечного сплетения или чуть выше; для двойных — вторую лапу накладывать сверху), внутрь — для боковых (на высоте головы), вперёд — для коротких прямых; не двигать лапу навстречу удару, после касания — небольшое уступающее движение."],["Тактика","Начинать с правой снизу в туловище — боксёр легче схватывает координацию более развитой правой рукой."],["Особенности выполнения","Сигнал — постановка лапы в определённое положение; тренер заранее уславливается о варианте переноса веса."],["Типичные ошибки","Широко поставленные лапы и встречное движение лапы формируют неверный навык и неточный удар; удар ниже целевой точки травмирует запястье."]],"exercises":[{"id":"OGE69-S-PAD-UP","text":"Из учебной (фронтальной) позиции: правой снизу в туловище — сначала с весом на разноимённую ногу, затем на обе, затем на одноимённую; затем левой; снизу в голову (лапа на высоте подбородка); двойные левой—правой / правой—левой (акцент чаще на втором); серии из трёх и четырёх ударов снизу с акцентом на заключительном.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы","review":false},{"id":"OGE69-S-PAD-HK","text":"Боковой правой в голову — лапа внутрь на высоте подбородка, удар без шага; левой; боковые в туловище — лапы на высоте солнечного сплетения; боковые правой—левой и левой—правой; серии боковых в голову, затем в туловище: три удара, затем четыре с акцентом на последнем; короткий прямой — лапа целевой точкой вперёд, локоть опущен.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы","review":false}]},{"id":"PRG-CLOSE-PERFECT-PADS-2","title":"Лапы: продвижение, комбинации, защиты, выход и вход","review":false,"formats":["На лапах","Работа в паре"],"criteria":[["Техника","При каждом шаге назад выпрямлять вперёд левую руку."],["Особенности выполнения","Сначала все движения медленно, затем постепенно быстрее, пока не станут быстрыми и слитными.\nВход — сначала медленно, затем до предельно быстрого; у привыкшей пары положение лап — сигнал одного способа (развивает реакцию)."]],"exercises":[{"id":"OGE69-S-PAD-MOVE","text":"Однотипные серии с небольшими шагами вперёд (удар правой — шаг левой, удар левой — шаг правой; тренер отходит) и назад (удар правой — шаг назад правой; тренер надвигается); затем первые удары на месте, последний акцентированный — с шагом в сторону одноимённой ногой (правой — вправо, левой — влево), вперёд, назад, в промежуточных направлениях.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы","review":false},{"id":"OGE69-S-PAD-CMB","text":"Боковой правой в голову — снизу левой в туловище (и обратно); снизу левой в туловище — короткий прямой правой в голову (задерживаться дольше — удобна и действенна); боковой левой в голову — снизу правой и левой в туловище — боковой правой в голову (поворот лапы наружу для первого бокового).","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы","review":false},{"id":"OGE69-S-PAD-DEF","text":"Тренер показывает удар лапой — боксёр защищается и отвечает по другой лапе (снизу левой — подставка левого локтя и боковой/короткий правой; боковой левой — нырок, боковой правой, снизу левой); повторные удары; выход: оттолкнуться перчатками от плеч, шаг назад и сразу удар по лапе; нырок с шагом в сторону и короткий прямой; вход при атаке и контратакой (на прямой левой — шаг и уклон влево, встречный прямой правой); с подготовленными — кросс.","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"лапы","review":false}]},{"id":"PRG-CLOSE-PERFECT-PARTNER","title":"С партнёром: задания, условный и вольный бой","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Вначале медленно, затем темп выше; удары не сильно и не резко."],["Типичные ошибки","Бить резко и в полную силу в условном и вольном бою — в полную силу только по снарядам и в состязаниях."]],"exercises":[{"id":"OGE69-S-PRT-SEQ","text":"По очереди: один наносит отдельный короткий удар, другой защищается; затем защищающийся добавляет контрудар по перчатке атакующего; затем контрудар партнёру (не по перчатке), тот защищается; далее двойные разнотипные, серии, повторные, выход и вход.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-S-BOUT-01","text":"Условный бой: момент атаки и контратаки выбирать произвольно по заданию (занять внутреннее положение и бить снизу; входить определённым способом; выходить); обычно одно, редко два задания. Вольный бой — все приёмы по обстановке, с заданием одному, обоим или с подобранным партнёром (выше/ниже, легче/тяжелее, быстрее/медленнее).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false}]},{"id":"PRG-CLOSE-PERFECT-ENDUR","title":"Специальная выносливость: вольный бой и снаряды","review":false,"formats":["На мешке","На лапах","Работа в паре"],"criteria":[["Техника","Тщательно бинтовать руки; следить за страховкой."],["Тактика","Акцент по заданию: каждый второй удар в комбинациях, каждый третий или четвёртый в сериях."],["Особенности выполнения","Порядок на мешке — как при разучивании: одиночные → двухударные → серии; выход/вход; сначала из учебной позиции только на ближней, позже переходы с дальней; на снаряды — только после разучивания без партнёра, на лапах и с партнёром."],["Типичные ошибки","Беспорядочное «заколачивание» снаряда без задания, без страховки и защитных действий — может принести вред."]],"exercises":[{"id":"OGE69-S-END-01","text":"Оба ведут ближний бой в достаточно быстром темпе, по возможности не выходя из ближнего боя и немедленно входя, если дистанция разорвана; 1, 2 или 3 раунда по этапу подготовки, приёмы по усмотрению, без выхода на дальнюю.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false},{"id":"OGE69-S-APP-01","text":"После партнёра или условного/вольного боя, от тяжёлых снарядов к лёгким: мешок 2–3 раунда (нижний край на высоте пояса, растяжки, целевые точки мелом на высоте солнечного сплетения и головы); стенка и тяжёлая груша по 1–2 раунда (стенка — снизу и короткие прямые; груша — удары в голову); пневматическая груша 2–3 раунда; всего 4–8 раундов на трёх снарядах.","formats":["На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"мешок, стенка, тяжёлая груша, пневматическая груша, бинты","review":false}]},{"id":"PRG-CLOSE-PERFECT-ACCENT","title":"Акцентированные удары в сериях","review":false,"formats":["На мешке","На лапах","Работа в паре"],"criteria":[["Тактика","Ближний бой «избирательными» ударами по открывающимся точкам без автоматизированных серий превращается в грубую борьбу с захватами."],["Особенности выполнения","Комбинации и серии сначала заучить самостоятельно (без перчаток, на лапах, снарядах), затем в парах; к акцентам часто возвращаться."]],"exercises":[{"id":"OGE69-S-GRP-ACC","text":"В сериях делать акцент на каждом втором, третьем или четвёртом ударе по заданию, подчёркивая акцент командой.","formats":["На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки/снаряды","review":false}]},{"id":"PRG-CLOSE-PERFECT-TAC-1","title":"Тактические задания: невысокий против высокого; избегающий сближения","review":false,"formats":["На лапах","Работа в паре"],"criteria":[["Особенности выполнения","Если задание не выходит — повторить технику (уклоны с движением вперёд, защиты) медленно с партнёром, затем в тени и на лапах."]],"exercises":[{"id":"OGE69-S-TAC-SHORT","text":"Сближаться уклонами влево (шаг левой вперёд-влево) и вправо, атаковать, войти серией и не разрывать дистанцию, оттеснять в угол; вызвать на удар, отступая и намеренно открывая голову; на удар — уклон или нырок, сближение и контратака серией; против защитной позиции или обхвата — снизу в голову между руками. Партнёр — высокий или имитирует его (дальний бой, выход, прерывание).","formats":["На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки, ринг","review":false},{"id":"OGE69-S-TAC-TALL","text":"Быстро маневрировать, сохраняя дальнюю дистанцию длинными прямыми; в момент сближения — короткая очень быстрая серия и немедленный отход на дальнюю с прямым левой; защитные позиции с остановками предплечьями, прижиматься грудью, наложение рук сверху и снизу — без захватов.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false}]},{"id":"PRG-CLOSE-PERFECT-TAC-2","title":"Тактические задания: против сильного, равного, левши; частные задания","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Действовать быстро и разнообразно; не вести встречный бой, не идти на обмен ударами."],["Особенности выполнения","В каждой паузе расслаблять мышцы.\nК соревнованию достаточно разучить 3–5 новых приёмов."],["Типичные ошибки","Непрерывный бой только на ближней дистанции против разностороннего."]],"exercises":[{"id":"OGE69-S-TAC-STRONG","text":"Прерывать ближний бой короткими шагами назад или в сторону и тут же возвращаться с 1–2 сериями; вести комбинационный бой, неожиданно меняя дистанции; использовать его движение вперёд — «проваливать» в канаты и бить сериями.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false},{"id":"OGE69-S-TAC-EQUAL","text":"Комбинационный бой: финты, отвлекающие маневры, смена темпа, неожиданная смена дистанций, предельно быстрые действия в ближнем; готовить технические и тактические новинки.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false},{"id":"OGE69-S-TAC-LEFTY","text":"Опираться головой не о левое, а о правое плечо партнёра; следить за его левой: подставка локтя от ударов снизу, остановка и нырок от боковых — сразу контратака серией; активнее действовать правой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-S-TAC-PART","text":"Наложением рук раскрыть партнёра и занять исходное для удара; финт — умышленный промах правой, чтобы противник прикрылся плечом и открылся под левую; забегание мелкими шагами 3–4 шага вправо или влево, на повороте партнёра — боковой и ближний бой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]}]},{"id":"S7","title":"Комбинационный бой","stages":[{"id":"COMBO-CLOSE-MID","no":51,"title":"Комбинационный бой на ближней и средней","task":"Смена ближней/средней, ответные средства против восьми исходных положений, предвидение положения противника","programs":[{"id":"PRG-COMBO-CLOSE-MID-1","title":"Ответ на исходные положения противника","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Перенос веса противника на левую ногу — ждать удара левой, на правую — правой; акцентированный удар определяется толчковой ногой."],["Особенности выполнения","Близкое расстояние сокращает время на обдумывание — иметь в запасе подготовленные средства против каждого исходного положения; первые удары со средней — с шагом вперёд."]],"exercises":[{"id":"OGE69-K-IP-01","text":"Против уклона вправо — снизу правой в туловище/голову (акц.) и серии; против уклона влево — снизу левой; против поворота слева направо — короткий прямой/боковой правой; справа налево — боковой/короткий левой; против отклона назад — снизу в туловище, короткий прямой; против наклона вправо/влево — снизу или боковой одноимённой; против приседания — снизу в голову, боковые. Для каждого положения — по нескольку серий с акцентами.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-COMBO-CLOSE-MID-2","title":"Смена дистанции с прямым левой и предвидение","review":false,"formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"criteria":[["Тактика","Цели смены дистанции — перечень из 17 тактических задач.\nЗащитившись, создавать исходное положение для немедленной ответной контратаки; предвидеть положение тела противника после удара.\nИспользовать инстинктивное замешательство противника после пропущенных ударов."],["Особенности выполнения","Средства комбинационного боя многократными повторениями доводить до сознательного автоматизма — на снарядах, в бою с тенью, с тренером на лапах."]],"exercises":[{"id":"OGE69-K-SW-01","text":"Отход назад с прямым левой в голову, затем: акцентированный короткий прямой правой; снизу в туловище/голову с серией; боковой с серией; четырёхударная серия; вызов на атаку прямыми и контратака с отходом; не дать захватить руки; создать впечатление выхода и продолжить ближний бой; выйти из ближнего боя.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE69-K-PRED-01","text":"Финты прямыми левой в голову и в туловище с дальней → акцентированный короткий прямой правой → вес на левую и снизу левой в туловище, боковые правой, левой → при приседе противника опередить ударами снизу, при выпрямлении — боковые; при нокдауне — отойти в нейтральный угол; при продолжении атаки противника — шаг назад с выбрасыванием левой и акцентированный правой со страховкой.","formats":["Бой с тенью","На мешке","На лапах","Работа в паре"],"labels":[],"needs":"Нужен партнёр; для лап — держащий лапы","equipment":"перчатки","review":false},{"id":"OGE69-K-HEAD-03","text":"Шаг назад, на секунду вытянуть левую, толчком носка правой перенести вес вперёд — встречный прямой левой в голову — снизу правой в голову/туловище; затем короткая серия прямых на средней и заключительный прямой левой с отходом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]}]},{"id":"COMBO-PADS","no":52,"title":"Комбинационный бой на лапах","task":"Цепи приёмов на всех дистанциях по лапам тренера: сначала на месте (ближний), затем в передвижении (дальний, средний)","programs":[{"id":"PRG-COMBO-PADS-1","title":"Методика лап и цепи комбинационного боя №1–8","review":false,"formats":["На лапах"],"criteria":[["Техника","Лапы держать на вертикальной линии голова — туловище боксёра; для боковых — сблизить, чтобы бить в одну точку; пример: прямой в голову — снизу правой в туловище — боковой левой: правая лапа на уровне головы, левая у солнечного сплетения целевой стороной вниз, затем поворот."],["Тактика","Заканчивать приём прямым левой в голову с шагом назад: левое плечо прикрывает подбородок, отход на нужную дистанцию."],["Особенности выполнения","Задачи: проверка техники, исправление ошибок, маневрирование, атака/контратака на трёх дистанциях, защита с переходом в атаку, акцент.\nИзучать на лапах и в других упражнениях по индивидуальному заданию; приёмы основаны на наиболее вероятных исходных положениях."],["Типичные ошибки","Неумелое держание лап закрепляет ошибочные навыки."]],"exercises":[{"id":"OGE66-K-PAD-01","text":"Тренер на лапах даёт одиночные, двойные, серийные и повторные удары, перемещается, имитирует удары, заставляя защищаться и контратаковать; сначала на месте без передвижений (ближний бой), затем в передвижении (дальний и средний); затем соединяет усвоенные приёмы в комбинационный бой.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы","review":false},{"id":"OGE66-K-CH-01","text":"Атака прямым левой в голову, левой в туловище, левой, правой в голову, снизу левой в туловище, боковой левой в голову, короткий прямой правой в голову, снизу левой в туловище, шагом назад с прямой левой в голову, шагом вправо и атака боковым правой в голову, снизу левой в туловище, шагом назад с прямым левой в голову, шагом вправо и атака боковым правой в голову, снизу левой в туловище, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-02","text":"Атака прямыми ударами с дальней дистанции — левой, левой в голову, левой в туловище, правой в голову (с акцентом), снизу левой в туловище, боковые: правой, левой в голову, снизу правой в туловище, шагом назад с прямым левой в голову, атака коротким прямым правой в голову (с акцентом), шагом назад с прямым левой в голову, атака снизу правой в туловище, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-03","text":"Прямые «финтовые» удары с дальней дистанции левой, левой в голову и атака серией из четырех прямых ударов: левой, правой, левой, правой (с акцентом) в голову, шагом назад с прямым левой в голову, атака двумя прямыми: левой—правой в голову, шагом назад с прямым левой в голову, атака прямым левой в голову, снизу правой в туловище, шагом назад с прямым левой в голову, атака прямым левой в голову, снизу правой в туловище, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-04","text":"Прямые «финтовые» удары с дальней дистанции левой в голову и атака серией из четырех прямых ударов в голову и туловище: прямой левой в голову, правой, левой в туловище, прямой правой (с акцентом) в голову шагом назад с прямым левой в голову, атака серией уди ров снизу в туловище: правой, левой, правой, шагом назад с прямым левой в голову, атака коротким прямым правой в голову, шагом назад с прямым левой в голова прямые «финтовые» удары с дальней дистанции – левой, левой в голову, показ прямого левой несколько выше головы и атака прямым правой в туловище (с аи центом), шагом назад с прямым левой в голову, атак) прямым — левой, правой в голову, снизу левой в туловище, шагом назад с прямым левой в голову; атака коротким прямым правой в голову, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-05","text":"На атаку противника прямым правой в голову – контрудар прямым правой в голову («разрез»), прямой левой в голову снизу: правой, левой в туловище, боковой правой в голову, шагом назад с прямым левой в голову, атака коротким прямым в голову, шагом назад с прямым левой в голову, атака прямым правой в голову, снизу левой в туловище, шагом назад прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-06","text":"На атаку противника серией прямых ударов в голову — отход назад с прямыми левой, правой, левой, правой (с акцентом) в голову, шагом назад с прямым левой в голову и атака прямым левой в голову, снизу правой в туловище, боковым левой в голову, отход шагом назад с прямым левой в голову, атака коротким прямым правой в голову, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-07","text":"На атаку противника прямым левой в голову — встречный прямой левой в голову с уклоном вперед вправо, снизу правой и левой в туловище, боковой правой в голову, шагом назад с прямым левой в голову шагом влево и атакой боковым левой в голову, отход назад с прямыми правой, левой, правой, левой в голову, уклон вправо и атака прямым правой (с акцентом) в голову, шагом назад прямой левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-08","text":"На атаку противника прямым левой в голову — контрудары: прямым правой в туловище, боковым левой в голову, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false}]},{"id":"PRG-COMBO-PADS-2","title":"Цепи комбинационного боя №9–15","review":false,"formats":["На лапах"],"criteria":[["Тактика","Заканчивать приём прямым левой в голову с шагом назад: левое плечо прикрывает подбородок, отход на нужную дистанцию."],["Особенности выполнения","Изучать на лапах и в других упражнениях по индивидуальному заданию; приёмы основаны на наиболее вероятных исходных положениях."]],"exercises":[{"id":"OGE66-K-CH-09","text":"Атака прямыми: левой, правой в голову, снизу левой в туловище (с акцентом), шагом назад с прямым левой в голов» атака: снизу правой, левой, правой в туловище, боковой левой в голову (с акцентом), шагом назад с прямым левой в голову, атака: боковыми левой, правой в голову, снизу левой в туловище, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-10","text":"На атаку прямым левой в голову — контратака боковым левой в голову с шагом вперед и влево и отбивом правым предплечьем; прямым правой в туловище, боковым левой в голову, шагом назад с прямой левой в голову, атака прямыми — левой в голову, правой в туловище (с акцентом), боковой левой в голову, правой в голову (с акцентом), шагом назад с прямым левой в голову, атака прямым правой в туловище (с акцентом), шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-11","text":"На атаку противника прямым левой в голову — контратака снизу левой в туловище с шагом вперед и влево, прямой правой в голову, прямой левой в голову с шагом назад, атака прямыми — левой, правой в голову, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-12","text":"Обманное движение туловищем вправо, влево и атака боковым левой в голову, снизу правой в туловище, шагом назад с прямым левой в голову, атака прямым правой в голову, снизу левой в туловище, шагом назад с прямым левой в голову, атака левой снизу в голову, коротким прямым правой в голову, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-13","text":"«финт» прямым левой в голову с дальней дистанции, атака боковыми: левой, левой в голову, прямой правой в голову (с акцентом), удары снизу: левой, правой, левой в туловище — боковой правой в голову, шагом назад с прямым левой в голову; атака: снизу правой в голову (с акцентом), шагом назад с прямым левой в голову, атака коротким прямым правой в голову, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-14","text":"На атаку противника прямым левой в голову — контрудар прямым-правой в голову с шагом вперед и влево, снизу левой в туловище, короткий прямой правой в голову, шагом назад с прямым левой в голову и атака: снизу правой, левой в туловище, боковым правой в голову, шагом назад с прямым левой в голову, шагом влево и атака боковым левой в голову, шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false},{"id":"OGE66-K-CH-15","text":"Тактический отход шагом назад для вызова противника на атаку прямым левой в голову, контратака — «кросс» правой в голову, снизу левой в туловище, шагом назад с прямым левой в голову, атака коротким прямым правой в голову (с акцентом), шагом назад с прямым левой в голову.","formats":["На лапах"],"labels":[],"needs":"Нужен партнёр с лапами","equipment":"лапы/перчатки","review":false}]}]},{"id":"COMBO-RING","no":53,"title":"Использование площади ринга","task":"Атака у канатов (70–80 см), опасная/свободная зоны, способы оттеснить противника, выход от канатов и из угла","programs":[{"id":"PRG-COMBO-RING-1","title":"Зоны ринга и атака у канатов","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Расстояния 70–80 см от канатов достаточно; после акцентированного правой закончить прямым левой с небольшим отходом на шаг назад, чтобы не попасть в клинч."],["Особенности выполнения","Боксёрам ниже ростом особенно рекомендуются способы 3–6."],["Типичные ошибки","Атака серией прямых с дальней дистанции без тактической подготовки, стоя спиной недалеко от канатов: противник отскакивает, боксёр промахивается и теряет устойчивость."]],"exercises":[{"id":"OGE66-K-RNG-01","text":"Начинать неожиданную атаку серией прямых в голову/туловище, когда противник в 70–80 см от канатов; не «отпускать», передвигаясь вправо, влево, назад; не более четырёх ударов; заканчивать прямым левой с шагом назад.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false},{"id":"OGE66-T-RNG-01","text":"Начинать подготовленную атаку серией прямых, когда противник в опасной зоне (у канатов), развивать сериями снизу и сбоку; центр ринга — свободная зона.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false},{"id":"OGE66-T-RNG-02","text":"Прямолинейная атака с финтами левой; замедленный шаг назад с резким переходом в атаку; шаги вперёд-влево/вперёд-вправо с прямым или боковым; то же с поворотом и наклоном туловища; подскоки в сторону одновременно с противником с угрозой прямого; подскоки по кругу с резкой сменой направления.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false}]},{"id":"PRG-COMBO-RING-2","title":"Выход от канатов и из угла (медленно → быстро)","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Лучше выходить активной защитой с немедленной контратакой."],["Особенности выполнения","Каждый способ разучивать на тренировке; сначала медленно."]],"exercises":[{"id":"OGE66-K-RNG-02","text":"Один в углу, другой атакует лёгкими ударами; защищающийся применяет показанный тренером способ выхода; медленно, постепенно ускоряя. От канатов — быстрые уклоны с контратакой или маневр в сторону (вправо; от левши — влево).","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки, ринг","review":false}]}]},{"id":"COMBO-TACTICS","no":54,"title":"Тактика: форма боя, инициатива, раунд, противники","task":"Навязывание формы боя, инициатива, разведка и план раунда, бой против агрессивного, контратакующего, сильно бьющего, левши; турнир","programs":[{"id":"PRG-COMBO-TAC-1","title":"Форма боя по дистанциям и инициатива","review":false,"formats":["Работа в паре"],"criteria":[["Техника","При прямом левой — страховка головы правой рукой."],["Тактика","Навязать противнику невыгодную форму боя; выбор формы боя по физическим данным.\nОдна защита никогда не приведёт к победе; исходное положение для атаки готовить финтами и передвижениями."]],"exercises":[{"id":"OGE66-T-FAR-01","text":"Держать противника на дальней дистанции: встречный прямой левой в голову («стоп»), повторные прямые левой с угрозой «кросса»; не попадать к канатам; при отступлении — шаг назад одноимённой ногой с тем же ударом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-FAR-02","text":"Против отклона назад, наклонов/уклонов, готовящих боковые с подскоком: отход или нырок; опережение ударом левой снизу или прямым правой с шагом правой ногой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-MAN-01","text":"Шаг назад — вызвать противника вперёд и встретить «стопом»; шаг вправо — заставить его повернуться и нанести «раз-два»; шаг влево — нанести боковой левой.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-MID-01","text":"Серии прямых с отходом назад, затем разрыв дистанции длинным шагом.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-INI-01","text":"С первых секунд навязывать свою дистанцию: при выгодном ближнем — уклон от первого встречного с ответом и серия в ближнем; при выгодном дальнем — прямой левой со страховкой, серии прямых с отходом против сближения. После защиты от 1–2 ударов немедленно переходить в ответную контратаку.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-COMBO-TAC-2","title":"Разведка и план раунда","review":false,"formats":["Работа в паре"],"criteria":[["Особенности выполнения","Темп в раунде наращивать постепенно, максимум к концу; опасно начинать в предельном темпе."]],"exercises":[{"id":"OGE66-T-RND-01","text":"В начале 1-го раунда с незнакомым — разведка прямым левой в голову и туловище, затем «раз-два» и серии с дальней; выявить умение противника на средней и ближней; удары в туловище для сбива дыхания; последние 10–15 с раунда — завершить в свою пользу.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-COMBO-TAC-3","title":"Против агрессивного, контратакующего, сильно бьющего","review":false,"formats":["Работа в паре"],"criteria":[["Техника","Страховка головы ладонью левой руки при контрударе правой обязательна."],["Тактика","Нужны хладнокровие и выдержка; удары в туловище снижают темп противника ко второму раунду."],["Особенности выполнения","Не показывать, что боится удара."]],"exercises":[{"id":"OGE66-T-OPP-AGG","text":"«Стоп» прямым левой; шаги вправо/влево с поворотом туловища и ответными сериями; отход шагом назад толчком правой ноги и контрудар прямым правой; против прямой позиции — прямой правой в туловище; встречный правой «вразрез»; против финтящего туловищем — шаг назад с вытянутой левой и акцентированный правой снизу с серией; чаще удары снизу, а при выпрямлении — серии прямых.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-OPP-CTR","text":"Сближаться в особо собранной позиции, предвидя контрудар; больше обманных движений, вызов на себя отходом; прижимать к канатам/в угол и задерживать там.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-OPP-PWR","text":"Вызвать на излюбленный акцентированный удар: подчеркнуто замедленный шаг назад с иллюзией раскрытия (слегка опустить левую руку и плечо), вес на правую ногу; при атаке прямым правой — толчок носком правой ноги и опережающий прямой правой «вразрез», развить серией.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-COMBO-TAC-4","title":"Против левши; оба в правосторонней","review":false,"formats":["Работа в паре"],"criteria":[["Тактика","Выходить из ближнего боя шагом назад левой ногой с прямым правой, а не левой."]],"exercises":[{"id":"OGE66-T-OPP-LEFTY","text":"Передвигаться вправо осторожно, вызывая левшу на атаку левой и встречая правой; финты левой и обманные движения туловищем; при промахе левши — атака правой в голову с развитием в ближнем; в ближнем — нырок от бокового левой и ответная серия боковых с правого; от удара левой снизу — левый локоть внутрь; боковой левой — локоть выше, кулак сверху вниз.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-T-OPP-2LEFTY","text":"Положение аналогично обычному боксированию в левосторонней стойке; побеждает лучше подготовленный технически, маневренно, физически.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false}]},{"id":"PRG-COMBO-TAC-5","title":"Турнир и волевые бои по заданию","review":false,"formats":["На мешке","Работа в паре"],"criteria":[["Особенности выполнения","Не растрачивать силы на удары по защите; при несостоявшемся бое — небольшая скоростная тренировка.\nТренировочный бой с мешком в три раунда в предельно высоком темпе — пример трудного волевого задания."]],"exercises":[{"id":"OGE66-T-TRN-01","text":"Побеждать расчётливой техникой с минимальными затратами; вызов на удар правой и контрудар «вразрез»; если два раунда без преимущества — в третьем решительная атака; после атаки — челночный отход на шаг назад с выбрасыванием левой и новая серия.","formats":["Работа в паре"],"labels":[],"needs":"Нужен партнёр","equipment":"перчатки","review":false},{"id":"OGE66-WILL-01","text":"Пример: высокорослому средневесу — дальний бой быстрыми лёгкими ударами; полулегковесу — беспрерывно атаковать, входить в ближний бой, прижимать к канатам; при нарушении задания тренер подаёт «Стоп».","formats":["На мешке"],"labels":[],"needs":"","equipment":"перчатки, ринг","review":false}]}]}]}]};
